////////////////////////////////////////////////////////////////////////////////
//
/// Параметры преобразования объектов модели в деталь/локальную деталь.
/**
  Интерфейс позволяет задать параметры преобразования для функции IParts::SaveAsDetail.
*/
////////////////////////////////////////////////////////////////////////////////
struct ISaveAsDetailParam : IAPIObject
{
  /// Получить путь к файлу.
  virtual std::wstring GetFileName() = 0;
  /// Установить путь к файлу.
  virtual void SetFileName(const std::wstring & fileName) = 0;
  /// Получить имя нового компонента.
  virtual std::wstring GetName() = 0;
  /// Установить имя нового компонента.
  virtual void SetName(const std::wstring & name) = 0;
  /// Получить обозначение нового компонента.
  virtual std::wstring GetMarking() = 0;
  /// Установить обозначение нового компонента.
  virtual void SetMarking(const std::wstring & marking) = 0;
  /// Установить признак, является ли новый компонент локальной деталью.
  virtual void SetLocal(bool local) = 0;
  /// Получить признак, является ли новый компонент локальной деталью.
  virtual bool IsLocal() = 0;
  /// Получить признак, является ли новый компонент компоновочной геометрией.
  virtual bool IsLayoutGeometry() = 0;
  /// Установить признак, является ли новый компонент компоновочной геометрией.
  virtual void SetLayoutGeometry(bool layoutGeometry) = 0;
  /// Получить признак сохранения истории построения.
  virtual bool IsUnhistored() = 0;
  /// Установить признак сохранения истории построения.
  virtual void SetUnhistored(bool unhistored) = 0;
  /// Получить признак зеркальной вставки для нового компонента.
  virtual bool IsMirror() = 0;
  /// Установить признак зеркальной вставки для нового компонента.
  virtual void SetMirror(bool mirror) = 0;
  /// Установить признак сохранения исходных объектов (true - оставлять исходные объекты, false - удалить).
  virtual void SetSaveInitialObjects(bool saveInitialObjects) = 0;
  /// Получить признак сохранения исходных объектов (true - оставлять исходные объекты, false - удалить).
  virtual bool IsSaveInitialObjects() = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// Параметры удаления истории построения.
/**
  Интерфейс позволяет задать параметры удаления истории построения
  для функции IKompasDocument3D::DeleteHistoryWithParam.
*/
////////////////////////////////////////////////////////////////////////////////
struct IDeleteHistoryParam : IAPIObject
{
  /// Получить признак сохранения массы.
  virtual bool GetSaveMass() = 0;
  /// Установить признак сохранения массы.
  virtual void SetSaveMass(bool saveMass) = 0;
  /// Получить признак сохранения центра массы.
  virtual bool GetSaveCenterMass() = 0;
  /// Установить признак сохранения центра массы.
  virtual void SetSaveCenterMass(bool saveCenterMass) = 0;
  /// Получить признак учета скрытых компонент.
  virtual bool GetHiddenParts() = 0;
  /// Установить признак учета скрытых компонент.
  virtual void SetHiddenParts(bool hiddenParts) = 0;
  /// Получить признак объединения тел и компонент в одно тело (true - объединять в одно тело, false - специальное преобразование).
  virtual bool GetUnionParts() = 0;
  /// Установить признак объединения тел и компонент в одно тело (true - объединять в одно тело, false - специальное преобразование).
  virtual void SetUnionParts(bool unionParts) = 0;
  /// Получить признак удаления истории построения.
  virtual bool GetDeleteOwnHistory() = 0;
  /// Установить признак удаления истории построения.
  virtual void SetDeleteOwnHistory(bool deleteOwnHistory) = 0;
  /// Получить признак преобразования компонент.
  virtual bool GetDeletePartsHistory() = 0;
  /// Установить признак преобразования компонент.
  virtual void SetDeletePartsHistory(bool deletePartsHistory) = 0;
  /// Получить способ преобразования вставок.
  virtual ksTransformPartsTypeEnum GetTransformPartsType() = 0;
  /// Установить способ преобразования вставок.
  virtual void SetTransformPartsType(ksTransformPartsTypeEnum transformPartsType) = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// Параметры штриховки.
/**
    Дополнительный интерфейс для IHatch и IAssociationView.
*/
////////////////////////////////////////////////////////////////////////////////
struct IHatchParam : IAPIObject
{
  /// Получить стиль штриховки.
  virtual int32_t GetStyle() = 0;
  /// Установить стиль штриховки.
  virtual void SetStyle(int32_t style) = 0;
  /// Получить цвет штриховки.
  virtual Color GetHatchColor() = 0;
  /// Установить цвет штриховки.
  virtual void SetHatchColor(Color hatchColor) = 0;
  /// Получить шаг или масштаб штриховки.
  virtual double GetStep() = 0;
  /// Установить шаг или масштаб штриховки.
  virtual void SetStep(double step) = 0;
  /// Получить угол наклона штриховки (в градусах).
  virtual double GetHatchAngle() = 0;
  /// Установить угол наклона штриховки (в градусах).
  virtual void SetHatchAngle(double hatchAngle) = 0;
  /// Получить тип штриховки (true - область, false - полоса).
  virtual bool GetHatchType() = 0;
  /// Установить тип штриховки (true - область, false - полоса).
  virtual void SetHatchType(bool hatchType) = 0;
  /// Получить ширину полосы штриховки.
  virtual double GetWidth() = 0;
  /// Установить ширину полосы штриховки.
  virtual void SetWidth(double width) = 0;
  /// Получить признак листового угла (true - листовая обычная штриховка, false - сохраняется угол относительно границ).
  virtual bool IsSheetAngle() = 0;
  /// Установить признак листового угла (true - листовая обычная штриховка, false - сохраняется угол относительно границ).
  virtual void SetSheetAngle(bool isSheetAngle) = 0;
  /// Получить имя файла для стиля штриховки.
  virtual std::wstring GetHatchFileName() = 0;
  /// Получить идентификатор стиля в библиотеке.
  virtual NumericId GetLibraryStyleNumber() = 0;
  /// Инициализировать стиль штриховки из библиотеки стилей.
  virtual bool AddStyleFromLibrary(const std::wstring & fileName, NumericId styleNumber) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Параметры размера.
/**
  Параметры размера: задание стрелок, выносных линий и полок.
  \ingroup Dimensions
*/
////////////////////////////////////////////////////////////////////////////////
struct IDimensionParams : IAPIObject
{
  /// Получить признак отрисовки первой выносной линии.
  virtual bool IsRemoteLine1() = 0;
  /// Установить признак отрисовки первой выносной линии.
  virtual void SetRemoteLine1(bool draw) = 0;
  /// Получить признак отрисовки второй выносной линии.
  virtual bool IsRemoteLine2() = 0;
  /// Установить признак отрисовки второй выносной линии.
  virtual void SetRemoteLine2(bool draw) = 0;
  /// Получить тип стрелки у первой выносной линии.
  virtual ksArrowEnum GetArrowType1() = 0;
  /// Установить тип стрелки у первой выносной линии.
  virtual void SetArrowType1(ksArrowEnum arrowType) = 0;
  /// Получить тип стрелки у второй выносной линии.
  virtual ksArrowEnum GetArrowType2() = 0;
  /// Установить тип стрелки у второй выносной линии.
  virtual void SetArrowType2(ksArrowEnum arrowType) = 0;
  /// Получить способ размещения стрелок относительно выносной линии.
  virtual ksDimensionArrowPosEnum GetArrowPos() = 0;
  /// Установить способ размещения стрелок относительно выносной линии.
  virtual void SetArrowPos(ksDimensionArrowPosEnum arrowPosition) = 0;
  /**
    \brief Получить условное расстояние текста от выносной линии.
    \return Условное расстояние текста от выносной линии (в мм для линейных размеров, в градусах для угловых): \n
        0   - автоматическое размещение текста; \n
        > 0 - размещение текста на указанном расстоянии в направлении от первой точки ко второй; \n
        < 0 - размещение текста на указанном расстоянии в направлении от второй точки к первой.
  */
  virtual int32_t GetTextPos() = 0;
  /**
    \brief Установить условное расстояние текста от выносной линии.
    \param[in] distanceToLine - условное расстояние текста от выносной линии (в мм для линейных размеров, в градусах для угловых): \n
        0   - автоматическое размещение текста; \n
        > 0 - размещение текста на указанном расстоянии в направлении от первой точки ко второй; \n
        < 0 - размещение текста на указанном расстоянии в направлении от второй точки к первой.
  */
  virtual void SetTextPos(int32_t distanceToLine) = 0;
  /// Получить тип размерной надписи.
  virtual ksDimensionTextTypeEnum GetTextType() = 0;
  /// Установить тип размерной надписи.
  virtual void SetTextType(ksDimensionTextTypeEnum textType) = 0;
  /// Получить способ расположения размерной надписи относительно размерной линии.
  virtual ksDimensionTextPosEnum GetTextOnLine() = 0;
  /// Установить способ расположения размерной надписи относительно размерной линии.
  virtual void SetTextOnLine(ksDimensionTextPosEnum textPosition) = 0;
  /// Получить параметр отрисовки текста.
  virtual ksDimensionBaseEnum GetTextBase() = 0;
  /// Установить параметр отрисовки текста.
  virtual void SetTextBase(ksDimensionBaseEnum drawParam) = 0;
  /// Получить направление выносной полки.
  virtual ksShelfDirectionEnum GetShelfDirection() = 0;
  /// Установить направление выносной полки.
  virtual void SetShelfDirection(ksShelfDirectionEnum shelfDirection) = 0;
  /// Получить угол наклона выносной полки (в градусах).
  virtual double GetShelfAngle() = 0;
  /// Установить угол наклона выносной полки (в градусах).
  virtual void SetShelfAngle(double angle) = 0;
  /// Получить длину ножки выносной полки.
  virtual double GetShelfLength() = 0;
  /// Установить длину ножки выносной полки.
  virtual void SetShelfLength(double length) = 0;
  /// Получить признак применения значения для зазора или длины выносной линии (true - для зазора, false - для линии).
  virtual bool IsGap() = 0;
  /// Установить признак применения значения для зазора или длины выносной линии (true - для зазора, false - для линии).
  virtual void SetGap(bool isGap) = 0;
  /// Получить значение зазора или длины выносной линии.
  virtual int32_t GetGapValue() = 0;
  /// Установить значение зазора или длины выносной линии.
  virtual void SetGapValue(int32_t gapValue) = 0;
  /// Установить параметры значениями по умолчанию.
  virtual bool InitDefaultValues() = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Интерфейс для работы с типами загрузки.
/**
   Дополнительный интерфейс для IAssemblyDocument.
   Управляет пользовательскими типами загрузки. 
   Пользовательский тип загрузки это комбинация типов загрузки компонентов сборки.
*/
////////////////////////////////////////////////////////////////////////////////
struct ILoadCombination : IAPIObject
{
  /// Получить признак полноценной загрузки документа.
  virtual bool IsCompletelyLoaded() = 0;
  /// Получить массив имён типов загрузки.
  virtual std::vector<std::wstring> GetLoadCombinations() = 0;
  /// Получить индекс текущего типа загрузки.
  virtual int32_t GetCurrentIndex() = 0;
  /**
    \brief Создать тип загрузки с указанным именем (фиксируются типы загрузки вложенных компонентов) и вернуть его индекс.
    \param[in] name - имя типа загрузки.
    \return Индекс созданного типа загрузки.
  */
  virtual int32_t Create(const std::wstring & name) = 0;
  /**
    \brief Удалить тип загрузки по индексу.
    \param[in] index - индекс типа загрузки.
    \param[in] password - пароль.
    \param[in] deleteDependant - признак удаления вложенных типов загрузки (true - удалять, false - не удалять).
    \return Успешность удаления.
  */
  virtual bool Delete(int32_t index, const std::wstring & password, bool deleteDependant) = 0;
  /**
    \brief Удалить тип загрузки по имени.
    \param[in] name - имя типа загрузки.
    \param[in] password - пароль.
    \param[in] deleteDependant - признак удаления вложенных типов загрузки (true - удалять, false - не удалять).
    \return Успешность удаления.
  */
  virtual bool DeleteByName(const std::wstring & name, const std::wstring & password, bool deleteDependant) = 0;
  /**
    \brief Применить тип загрузки с указанным индексом.
    \param[in] index - индекс типа загрузки.
    \param[in] password - пароль.
    \return Успешность применения.
  */
  virtual bool Apply(int32_t index, const std::wstring & password) = 0;
  /**
    \brief Применить тип загрузки с указанным именем.
    \param[in] name - имя типа загрузки.
    \param[in] password - пароль.
    \return Успешность применения.
  */
  virtual bool ApplyByName(const std::wstring & name, const std::wstring & password) = 0;
  /**
    \brief Установить пароль для типа загрузки по индексу.
    \param[in] index - индекс типа загрузки.
    \param[in] oldPassword - старый пароль.
    \param[in] newPassword - новый пароль.
    \param[in] unprotectUsers - признак удаления паролей пользовательских типов загрузки 
               (true - при удалении пароля системного типа, удалять пароли пользовательских типов, false - не удалять).
    \return Успешность установки пароля.
  */
  virtual bool SetPassword(int32_t index, const std::wstring & oldPassword, const std::wstring & newPassword,
                           bool unprotectUsers) = 0;
  /**
    \brief Обновить тип загрузки по текущему состоянию модели.
    \param[in] index - индекс типа загрузки.
    \param[in] password - пароль.
    \return Успешность обновления.
  */
  virtual bool UpdateByModel(int32_t index, const std::wstring & password) = 0;
  /**
    \brief Установить комментарий к типу загрузки.
    \param[in] index - индекс типа загрузки.
    \param[in] comment - комментарий к типу загрузки.
    \param[in] password - пароль.
    \return Успешность добавления комментария.
  */
  virtual bool SetLoadCombinationComment(int32_t index, const std::wstring & comment, const std::wstring & password) = 0;
  /**
    \brief Получить комментарий к типу загрузки по индексу.
    \param[in] index - индекс типа загрузки.
    \return Комментарий к типу загрузки.
  */
  virtual std::wstring GetLoadCombinationComment(int32_t index) = 0;
  /**
    \brief Установить имя типа загрузки по индексу.
    \param[in] index - индекс типа загрузки.
    \param[in] name - устанавливаемое имя типа загрузки.
    \param[in] password - пароль.
    \return Успешность установки имени для типа загрузки.
  */
  virtual bool SetLoadCombinationName(int32_t index, const std::wstring & name, const std::wstring & password) = 0;
  /**
    \brief Получить имя типа загрузки по индексу.
    \brief Получить имя типа загрузки по индексу.
    \param[in] index - индекс типа загрузки.
    \return Имя типа загрузки.
  */
  virtual std::wstring GetLoadCombinationName(int32_t index) = 0;
  /// Получить массив признаков защищенности типов загрузок (индексы типов загрузок соотносятся с индексами элементов массива).
  virtual std::vector<bool> GetProtectedFlags() = 0;
  /// Установить индекс типа загрузки без применения.
  virtual void SetCurrentIndex(int32_t index) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Параметры вывода.
/**
  Дополнительный интерфейс для IPrintJob.
*/
////////////////////////////////////////////////////////////////////////////////
struct IPrintJobOutputParameters : IAPIObject
{
  /// Установить количество копий.
  virtual void SetNumberOfCopies(int32_t numberOfCopies) = 0;
  /// Получить количество копий.
  virtual int32_t GetNumberOfCopies() = 0;
  /// Установить признак "копии в подбор".
  virtual void SetCollateCopies(bool collateCopies) = 0;
  /// Получить признак "копии в подбор".
  virtual bool IsCollateCopies() = 0;
  /// Установить признак вывода в файл.
  virtual void SetPlotToFile(bool plotToFile) = 0;
  /// Получить признак вывода в файл.
  virtual bool IsPlotToFile() = 0;
  /// Установить цвет вывода.
  virtual void SetColor(ksOutputColorTypeEnum color) = 0;
  /// Получить цвет вывода.
  virtual ksOutputColorTypeEnum GetColor() = 0;
  /// Установить признак вывода тонкими линиями.
  virtual void SetOnlyThinLines(bool onlyThinLines) = 0;
  /// Получить признак вывода тонкими линиями.
  virtual bool IsOnlyThinLines() = 0;
  /// Установить признак альтернативного способа вывода заливок.
  virtual void SetAlternativeFillingOutput(bool alternativeFillingOutput) = 0;
  /// Получить признак альтернативного способа вывода заливок.
  virtual bool IsAlternativeFillingOutput() = 0;
  /// Установить точность вывода моделей (от 0 до 20, 0 - точно, 20 - грубо).
  virtual void SetAccuracyModelOutput(int32_t accuracyModelOutput) = 0;
  /// Получить точность вывода моделей (от 0 до 20, 0 - точно, 20 - грубо).
  virtual int32_t GetAccuracyModelOutput() = 0;
  /// Установить порядок вывода страниц на печать.
  virtual void SetPageOutputOrder(int32_t pageOutputOrder) = 0;
  /// Получить порядок вывода страниц на печать.
  virtual int32_t GetPageOutputOrder() = 0;
  /// Установить масштаб листов по умолчанию.
  virtual void SetDefaultScale(double defaultScale) = 0;
  /// Получить масштаб листов по умолчанию.
  virtual double GetDefaultScale() = 0;
  /// Установить признак автоподгонки масштаба при добавлении листов.
  virtual void SetAutoScale(bool autoScale) = 0;
  /// Получить признак автоподгонки масштаба при добавлении листов.
  virtual bool IsAutoScale() = 0;
  /// Установить признак привязки к углам листов.
  virtual void SetUseCatchSpacing(bool useCatchSpacing) = 0;
  /// Получить признак привязки к углам листов.
  virtual bool IsUseCatchSpacing() = 0;
  /// Установить зазор между листами при привязке к углам листов (в мм).
  virtual void SetCatchSpacing(int32_t catchSpacing) = 0;
  /// Получить зазор между листами при привязке к углам листов (в мм).
  virtual int32_t GetCatchSpacing() = 0;
  /// Установить признак привязки к узлам страниц.
  virtual void SetUseHooking(bool useHooking) = 0;
  /// Получить признак привязки к узлам страниц.
  virtual bool IsUseHooking() = 0;
  /// Установить диапазон привязки к узлам страниц (1-50%).
  virtual void SetHooking(int32_t hooking) = 0;
  /// Получить диапазон привязки к узлам страниц (1-50%).
  virtual int32_t GetHooking() = 0;
};

////////////////////////////////////////////////////////////////////////////////
