  virtual bool LoadPrinterConfig(const std::wstring & fileName) = 0;
  /// Сохранить конфигурацию принтера.
  virtual bool SavePrinterConfig(const std::wstring & fileName) = 0;
  /// Установить ориентацию бумаги.
  virtual void SetPortraitPage(bool isPortraitPage) = 0;
  /// Получить ориентацию бумаги.
  virtual bool IsPortraitPage() = 0;
  /// Установить идентификатор размера бумаги.
