////////////////////////////////////////////////////////////////////////////////
//
/// Менеджер пользовательских метаданных.
/**
  Дополнительный интерфейс для IKompasDocument.
*/
////////////////////////////////////////////////////////////////////////////////
struct IUserMetadataManager : IAPIObject
{
  /**
    \brief Создать хранилище файлов приложения.
    \details Все парметры обязательные.
    \param[in] applicationIID - идентификатор (GUID) для доступа к хранилищу.
    \param[in] applicationName - имя приложения. Записывается в параметр "storageInfo.appName".
    \param[in] version - версия приложения. Записывается в параметр "storageInfo.appVersion".
    \return - Успешность создания хранилища.
  */
  virtual bool CreateStorage(const std::wstring & applicationIID, const std::wstring & applicationName,
                             const std::wstring & version) = 0;
  /// Проверить наличие хранилища по идентификатору приложения (GUID) (true - хранилище существует, false - не существует).
  virtual bool IsStorageExist(const std::wstring & applicationIID) = 0;
  /// Проверить наличие хранилища по идентификатору приложения (GUID).
  virtual bool DeleteStorage(const std::wstring & applicationIID) = 0;
  /// Получить список файлов хранилища по идентификатору приложения (GUID).
  virtual std::vector<std::wstring> GetAllFilenames(const std::wstring & applicationIID) = 0;
  /**
    \brief  Получить данные из StorageInfo.
    \param[in] applicationIID - идентификатор (GUID) приложения.
    \param[in] parameterName - имя параметра ("storageInfo.appName" или "storageInfo.appVersion").
    \return Значение параметра.
  */
  virtual std::wstring GetStorageInfo(const std::wstring & applicationIID, const std::wstring & parameterName) = 0;
  /**
    \brief Удалить файл из хранилища.
    \param[in] applicationIID - идентификатор (GUID) приложения.
    \param[in] storageFileName - имя файла.
    \return Успешность удаления.
  */
  virtual bool DeleteFile(const std::wstring & applicationIID, const std::wstring & storageFileName) = 0;
  /**
    \brief Проверить наличие файла в хранилище.
    \param[in] applicationIID - идентификатор (GUID) приложения.
    \param[in] storageFileName - имя файла.
    \return Признак наличия файла (true - файл есть в хранилище, false - нету).
  */
  virtual bool IsFileExist(const std::wstring & applicationIID, const std::wstring & storageFileName) = 0;
  /**
    \brief Добавить файл в хранилище.
    \param[in] applicationIID - идентификатор (GUID) приложения.
    \param[in] destFileName - имя файла в хранилище.
    \param[in] srcFileName - имя файла-источника, копия которого будет добавлена в хранилище.
    \param[in] allowReplacement - признак перезаписи файла, если он уже существует (true - перезаписать, false - не перезаписывать).
    \return Успешность добавления.
  */
  virtual bool AddFile(const std::wstring & applicationIID, const std::wstring & destFileName, const std::wstring & srcFileName,
                       bool allowReplacement) = 0;
  /**
    \brief Извлечь файл из хранилища (файл из хранилища не удаляется).
    \param[in] applicationIID - идентификатор (GUID) приложения.
    \param[in] destFileName - имя файла в хранилище.
    \param[in] srcFileName - имя создаваемого файла.
    \param[in] allowReplacement - признак перезаписи файла, если он уже существует (true - перезаписать, false - не перезаписывать).
    \return Успешность извлечения.
  */
  virtual bool ExtractFile(const std::wstring & applicationIID, const std::wstring & srcFileName,
                           const std::wstring & destFileName, bool allowReplacement) = 0;
};

