////////////////////////////////////////////////////////////////////////////////
//
/// Параметры разрыва вида.
/**
   Дополнительный интерфейс для IView (для видов всех типов, кроме системного).
*/
////////////////////////////////////////////////////////////////////////////////
struct IBreakViewParam : IAPIObject
{
  /**
    \brief Добавить линию разрыва.
    \param[in] x1, y1 - координаты первой точки.
    \param[in] x2, y2 - координаты второй точки.
    \param[in] angle - угол (в градусах).
    \return Индекс линии разрыва в коллекции.
  */
  virtual int32_t AddBreakLine(double x1, double y1, double x2, double y2, double angle) = 0;
  /**
    \brief Удалить линию разрыва.
    \param[in] index - индекс линии разрыва в коллекции.
    \return Успешность удаления.
  */
  virtual bool DeleteBreakLine(int32_t index) = 0;
  /// Удалить все линии разрыва.
  virtual bool DeleteAllBreakLines() = 0;
  /**
    \brief Установить координаты границ разрыва.
    \param[in] index - индекс линии разрыва в коллекции.
    \param[in] x1, y1 - координаты первой точки.
    \param[in] x2, y2 - координаты второй точки.
    \return Успешность установки.
  */
  virtual bool SetBreakLinePosition(int32_t index, double x1, double y1, double x2, double y2) = 0;
  /**
    \brief Получить координаты границ разрыва.
    \param[in] index - индекс линии разрыва в коллекции.
    \param[out] x1, y1 - координаты первой точки.
    \param[out] x2, y2 - координаты второй точки.
    \return Успешность получения.
  */
  virtual bool GetBreakLinePosition(int32_t index, double & x1, double & y1, double & x2, double & y2) = 0;
  /**
    \brief Установить параметры линии разрыва.
    \param[in] index - индекс линии разрыва в коллекции.
    \param[in] angle - угол, кратный 90 (в градусах).
    \param[in] clearance - зазор.
    \param[in] breakLineType - тип линии разрыва.
    \param[in] amplitude - амплитуда.
    \param[in] maxAmplitude - максимальная амплитуда.
    \return Успешность установки.
  */
  virtual bool SetBreakLineParams(int32_t index, double angle, double clearance, ksBreakLineTypeEnum breakLineType,
                                  double amplitude, double maxAmplitude) = 0;
  /**
    \brief Получить параметры линии разрыва.
    \param[in] index - индекс линии разрыва в коллекции.
    \param[out] angle - угол, кратный 90 (в градусах).
    \param[out] clearance - зазор.
    \param[out] breakLineType - тип линии разрыва.
    \param[out] amplitude - амплитуда.
    \param[out] maxAmplitude - максимальная амплитуда.
    \return Успешность получения.
  */
  virtual bool GetBreakLineParams(int32_t index, double & angle, double & clearance, ksBreakLineTypeEnum & breakLineType,
                                  double & amplitude, double & maxAmplitude) = 0;
  /// Получить количество линий разрыва.
  virtual int32_t GetBreaksCount() = 0;
  /// Получить видимость линий разрыва.
  virtual bool IsBreaksVisible() = 0;
  /// Установить видимость линий разрыва.
  virtual void SetBreaksVisible(bool visible) = 0;
};

