////////////////////////////////////////////////////////////////////////////////
//
/// Параметры автосортировки буквенных обозначений.
/**
  Автосортировка позволяет автоматически упорядочивать буквы, использующиеся в обозначениях.
  В автосортировке участвуют только определённые символы, их можно добавлять/убавлять методами этого интерфейса.
*/
////////////////////////////////////////////////////////////////////////////////
struct IAutoSortObjectsParameters : IAPIObject
{
  /// Получить набор символов, участвующих в автосортировке.
  virtual std::wstring GetAutoNumerationSymbols() = 0;
  /// Установить набор символов, участвующих в автосортировке.
  virtual void SetAutoNumerationSymbols(const std::wstring & symbols) = 0;
  /**
    \brief Получить признак включенности автосортировки для объектов по типу.
    \param[in] objectType - тип (DrawingObjectTypeEnum) объекта для получения признака включенности автосортировки.
    \return Признак включенности автосортировки.
  */
  virtual bool GetAutoNumerationEnable(int32_t objectType) = 0;

  /**
    \brief Включить автосортировку для объектов по типу.
    \param[in] objectType - тип (DrawingObjectTypeEnum) объекта для включения/выключения автосортировки.
               Для автосортировки доступны следующие типы:
               DrawingObjectTypeEnum::ksDrWPointer (стрелка вида),
               DrawingObjectTypeEnum::ksDrRemoteElement (выносной элемент),
               DrawingObjectTypeEnum::ksDrCut (линия разреза),
               DrawingObjectTypeEnum::ksDrBase (база),
               DrawingObjectTypeEnum::ksDrLeader (простая линия выноски),
               DrawingObjectTypeEnum::ksDrLDimension (линейный размер).
    \param[in] enable - Флаг автосортировки (true - включить автосортировку для объектов указанного типа, false - выключить).
  */
  virtual void SetAutoNumerationEnable(int32_t objectType, bool enable) = 0;
  /// Получить массив объектов в порядке их сортировки.
  virtual std::vector<int32_t> GetAutoNumerationObjects() = 0;

  /**
    \brief  Установить порядок сортировки объектов с помощью массива их типов (DrawingObjectTypeEnum).
    \param[in] objectTypes - массив типов (DrawingObjectTypeEnum), определяющий порядок сортировки.
               Для автосортировки доступны следующие типы:
               DrawingObjectTypeEnum::ksDrWPointer (стрелка вида),
               DrawingObjectTypeEnum::ksDrRemoteElement (выносной элемент),
               DrawingObjectTypeEnum::ksDrCut (линия разреза),
               DrawingObjectTypeEnum::ksDrBase (база),
               DrawingObjectTypeEnum::ksDrLeader (простая линия выноски),
               DrawingObjectTypeEnum::ksDrLDimension (линейный размер).
    \param[in] enable - Флаг автосортировки (true - включить автосортировку для объектов указанного типа, false - выключить).
  */
  virtual void SetAutoNumerationObjects(const std::vector<int32_t> & objectTypes) = 0;
  /// Установить порядок сортировки по символьным обозначениям типов объектов.
  virtual void SetAutoNumerationObjectsBySymbolicDesignations(const std::wstring & objectTypes) = 0;
};

