////////////////////////////////////////////////////////////////////////////////
//
/// Окно документа.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IDocumentFrame : IKompasAPIObject
{
  /// Установить состояние окна в активное.
  virtual void SetActive() = 0;
  /// Получить состояние активности окна.
  virtual bool IsActive() = 0;
  /// Получить заголовок окна.
  virtual std::wstring GetCaption() = 0;
  /// Растянуть часть документа, заданную рамкой (по координатам СК текущего вида).
  virtual void Zoom(double x1, double y1, double x2, double y2) = 0;
  /// Отобразить предыдущий/следующий масштаб или показать весь документ.
  virtual void ZoomPrevNextOrAll(ZoomTypeEnum zoomType) = 0;
  /// Установить масштаб изображения окна с центром в точке (по координатам СК документа).
  virtual void ZoomScale(double x, double y, double scale) = 0;
  /// Получить масштаб и центр окна документа (по координатам СК текущего вида).
  virtual void GetZoomScale(double & x, double & y, double & scale) = 0;
  /// Получить Handle окна.
  virtual WindowHandle GetWindowHandle() = 0;
  /// Взвести флаг изменения габарита документа (для собственного рисования в окне).
  virtual void SetGabaritModifying() = 0;
  /// Обновить изображение окна.
  virtual void RefreshWindow() = 0;
  /// Преобразовать оконные координаты в координаты документа.
  virtual bool ConvertCoordinates(ConvertCoordTypeEnum coordinateType, int32_t windowX, int32_t windowY, double & x, double & y,
                                  double & z) = 0;
  /// Выполнить команду системы КОМПАС.
  virtual bool ExecuteKompasCommand(int32_t commandId, bool postMessage) = 0;
  /// Проверить доступность выполнения команды.
  virtual bool IsKompasCommandEnable(int32_t commandId) = 0;
  /// Проверить нажата ли кнопка команды (0 - отжата, 1 - нажата).
  virtual int32_t IsKompasCommandCheck(int32_t commandId) = 0;
  /// Получить данные отрисовки.
  virtual std::vector<uint8_t> GetFPSData() = 0;
  /**
    \brief Преобразовать оконные координаты в луч взгляда.
    \param[in] windowX, windowY - координаты в экранных пикселах.
    \param[out] x, y, z - координаты точки на ближайший к лучу взгляда объект, в координатах компонента.
    \param[out] zx, zy, zz - направления вектора взгляда.
    \return Успешность выполнения операции.
  */
  virtual bool GetPickRay(int32_t windowX, int32_t windowY, double & x, double & y, double & z, double & zx, double & zy,
                          double & zz) = 0;
  /// Получить признак режима округления линейных величин до значений кратных шагу курсора.
  virtual bool IsRoundModeOn() = 0;
  /// Получить текущий шаг дискретного перемещения курсора.
  virtual double GetCurrentCursorStep() = 0;
  /// Получить размеры свободной рабочей области (за вычетом быстрой панели).
  virtual void GetWorkAreaRect(int32_t & left, int32_t & top, int32_t & right, int32_t & bottom) = 0;
  /// Преобразовать координаты документа в оконные координаты.
  virtual bool UnConvertCoordinates(ConvertCoordTypeEnum coordinateType, double x, double y, double z, int32_t & windowX,
                                    int32_t & windowY) = 0;
  /**
    \brief Растянуть изображение окна.
    \param[in] x, y - координаты точки центра.
    \param[in] scale - масштаб.
    \param[in] viewCoordinates - true  - координаты заданы в системе координат текущего вида,
                                 false - координаты заданы в системе координат листа.
    \return Успешность выполнения операции.
  */
  virtual bool SetZoomScale(double x, double y, double scale, bool viewCoordinates) = 0;
  /// Получить события окна документа.
  virtual IDocumentFrameEventsPtr Events() = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// События окна документа.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IDocumentFrameEvents : IAPIObject
{
  /// Удалить все обработчики.
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;
  /// Описание обработчика события "Начало отрисовки документа".
  using OnBeginPaintHandler = std::function<bool(const IPaintObjectPtr & paintObject)>;
  /// Добавить обработчик события "Начало отрисовки документа".
  virtual void AddBeginPaintHandler(const std::wstring & handlerOwner, OnBeginPaintHandler eventHandler) = 0;
  /// Описание обработчика события "Конец отрисовки документа".
  using OnClosePaintHandler = std::function<void(const IPaintObjectPtr & paintObject)>;
  /// Добавить обработчик события "Конец отрисовки документа".
  virtual void AddClosePaintHandler(const std::wstring & handlerOwner, OnClosePaintHandler eventHandler) = 0;
  /// Описание обработчика события "Нажатие кнопки мыши".
  using OnMouseDownHandler = std::function<bool(const IPressedKeysPtr & pressedKeys, int32_t x, int32_t y)>;
  /// Добавить обработчик события "Нажатие кнопки мыши".
  virtual void AddMouseDownHandler(const std::wstring & handlerOwner, OnMouseDownHandler eventHandler) = 0;
  /// Описание обработчика события "Отпускание кнопки мыши".
  using OnMouseUpHandler = std::function<bool(const IPressedKeysPtr & pressedKeys, int32_t x, int32_t y)>;
  /// Добавить обработчик события "Отпускание кнопки мыши".
  virtual void AddMouseUpHandler(const std::wstring & handlerOwner, OnMouseUpHandler eventHandler) = 0;
  /// Описание обработчика события "Двойное нажатие кнопки мыши".
  using OnMouseDblClickHandler = std::function<bool(const IPressedKeysPtr & pressedKeys, int32_t x, int32_t y)>;
  /// Добавить обработчик события "Двойное нажатие кнопки мыши".
  virtual void AddMouseDblClickHandler(const std::wstring & handlerOwner, OnMouseDblClickHandler eventHandler) = 0;
  /// Описание обработчика события "Начало отрисовки в контексте OpenGL".
  using OnBeginPaintGlHandler = std::function<bool(uint32_t drawMode, const IOpenGLObjectPtr & glObject)>;
  /// Добавить обработчик события "Начало отрисовки в контексте OpenGL".
  virtual void AddBeginPaintGlHandler(const std::wstring & handlerOwner, OnBeginPaintGlHandler eventHandler) = 0;
  /// Описание обработчика события "Окончание отрисовки в контексте OpenGL".
  using OnClosePaintGlHandler = std::function<void(uint32_t drawMode, const IOpenGLObjectPtr & glObject)>;
  /// Добавить обработчик события "Окончание отрисовки в контексте OpenGL".
  virtual void AddClosePaintGlHandler(const std::wstring & handlerOwner, OnClosePaintGlHandler eventHandler) = 0;
  /// Описание обработчика события "Определение габаритов документа".
  using OnAddGabaritHandler = std::function<void(const IGabaritObjectPtr & gabaritObject)>;
  /// Добавить обработчик события "Определение габаритов документа".
  virtual void AddAddGabaritHandler(const std::wstring & handlerOwner, OnAddGabaritHandler eventHandler) = 0;
  /// Описание обработчика события "Окно активизировалось".
  using OnActivateHandler = std::function<void()>;
  /// Добавить обработчик события "Окно активизировалось".
  virtual void AddActivateHandler(const std::wstring & handlerOwner, OnActivateHandler eventHandler) = 0;
  /// Описание обработчика события "Окно деактивизировалось".
  using OnDeactivateHandler = std::function<void()>;
  /// Добавить обработчик события "Окно деактивизировалось".
  virtual void AddDeactivateHandler(const std::wstring & handlerOwner, OnDeactivateHandler eventHandler) = 0;
  /// Описание обработчика события "Закрытие окна".
  using OnCloseHandler = std::function<void()>;
  /// Добавить обработчик события "Закрытие окна".
  virtual void AddCloseHandler(const std::wstring & handlerOwner, OnCloseHandler eventHandler) = 0;
  /// Описание обработчика события "Перемещение мыши".
  using OnMouseMoveHandler = std::function<bool(const IPressedKeysPtr & pressedKeys, int32_t x, int32_t y)>;
  /// Добавить обработчик события "Перемещение мыши".
  virtual void AddMouseMoveHandler(const std::wstring & handlerOwner, OnMouseMoveHandler eventHandler) = 0;
  /// Описание обработчика события "Начало отрисовки временных объектов(фантомов)".
  using OnBeginPaintTmpObjectsHandler = std::function<bool()>;
  /// Добавить обработчик события "Начало отрисовки временных объектов(фантомов)".
  virtual void AddBeginPaintTmpObjectsHandler(const std::wstring & handlerOwner, OnBeginPaintTmpObjectsHandler eventHandler) = 0;
  /// Описание обработчика события "Конец отрисовки временных объектов(фантомов)".
  using OnClosePaintTmpObjectsHandler = std::function<void()>;
  /// Добавить обработчик события "Конец отрисовки временных объектов(фантомов)".
  virtual void AddClosePaintTmpObjectsHandler(const std::wstring & handlerOwner, OnClosePaintTmpObjectsHandler eventHandler) = 0;

  /// Описание обработчика события "Вращение колеса мыши".
  using OnMouseWheelHandler = std::function<bool(const IPressedKeysPtr & pressedKeys, int32_t zDelta, int32_t x, int32_t y)>;
  /// Добавить обработчик события "Вращение колеса мыши".
  virtual void AddMouseWheelHandler(const std::wstring & handlerOwner, OnMouseWheelHandler eventHandler) = 0;
};


