////////////////////////////////////////////////////////////////////////////////
//
/// Формат листа.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISheetFormat : IKompasAPIObject
{
  /// Получить формат.
  virtual ksDocumentFormatEnum GetFormat() = 0;
  /// Установить формат.
  virtual void SetFormat(ksDocumentFormatEnum format) = 0;
  /// Получить кратность формата листа.
  virtual int32_t GetFormatMultiplicity() = 0;
  /// Установить кратность формата листа.
  virtual void SetFormatMultiplicity(int32_t formatMultiplicity) = 0;
  /// Получить вертикальную ориентацию формата листа.
  virtual bool IsVerticalOrientation() = 0;
  /// Установить вертикальную ориентацию формата листа.
  virtual void SetVerticalOrientation(bool verticalOrientation) = 0;
  /// Получить ширину пользовательского формата.
  virtual double GetFormatWidth() = 0;
  /// Установить ширину пользовательского формата.
  virtual void SetFormatWidth(double formatWidth) = 0;
  /// Получить высоту пользовательского формата.
  virtual double GetFormatHeight() = 0;
  /// Установить высоту пользовательского формата.
  virtual void SetFormatHeight(double formatHeight) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Стиль колонки спецификации.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISpecificationColumnStyle : IKompasAPIObject
{
  /// Получить имя колонки.
  virtual std::wstring GetName() = 0;
  /// Получить тип колонки.
  virtual ksSpecificationColumnTypeEnum GetColumnType() = 0;
  /// Получить уникальный номер колонки среди колонок одного типа.
  virtual int32_t GetNumber() = 0;
  /// Получить признак возможности редактирования колонки.
  virtual bool IsEdit() = 0;
  /**
    \brief Получить признак сложения значения в таблице при вызове команды "Сложить значения в колонках".
    \details Используется только для колонок со значением типа (GetValueType)
    вещественный (ksValueTypeEnum::ksValueTypeFloat) 
    или целый (ksValueTypeEnum::ksValueTypeInteger).
  */
  virtual bool IsCalculateSum() = 0;
  /**
    \brief Получить признак умножения значения в колонке на число в колонке "Количество".
    \details Используется только для колонок со значением типа (GetValueType)
    вещественный (ksValueTypeEnum::ksValueTypeFloat) 
    или целый (ksValueTypeEnum::ksValueTypeInteger). 
  */
  virtual bool IsMultiplyToCount() = 0;
  /**
    \brief Признак вывода заголовков разделов спецификации в колонку.
    \details Используется только для основных колонок спецификации.
    В стандартных спецификациях заголовки разделов обычно располагаются в колонке "Наименование".
    Значение этого свойства true - может быть только для одной колонки спецификации.
    Если у всех колонок значение свойства false, заголовки разделов показываться не будут 
    (даже при включении в настройке разделов опции "Показывать за­головки разделов").
  */
  virtual bool IsUseForSectionTitle() = 0;
  /// Получить признак расположения текста в нижней части колонки.
  virtual bool IsTextDown() = 0;
  /**
    \brief Получить номер ячейки штампа с которым связана колонка.
    \details Данное свойство определяет ячейку штампа чертежа детали,
    данные из которой могут автоматически передаваться в данную колонку спецификации.
    Например, в колонку "Формат" можно передавать текст из ячейки "Формат" штампа чертежа детали.
  */
  virtual int32_t GetStampLinkId() = 0;
  /// Получить тип значения колонки.
  virtual ksValueTypeEnum GetValueType() = 0;

  /**
    \brief Получить имя файла библиотеки типов атрибутов для колонок типа "Запись".
    \details Используется только для колонок со значением типа "Запись" (ksValueTypeEnum::ksValueTypeRecord).
    Структура записи в колонке определяется типом атрибута из библиотеки типов атрибу­тов.
    Для данной колонки можно будет использовать типы атрибутов только из указанной би­блиотеки.
  */
  virtual std::wstring GetAttributeLibraryName() = 0;
  /// Получить первый ключ атрибута для колонок типа "Запись".
  virtual int32_t GetAttributeKey1() = 0;
  /// Получить второй ключ атрибута для колонок типа "Запись".
  virtual int32_t GetAttributeKey2() = 0;
  /// Получить третий ключ атрибута для колонок типа "Запись".
  virtual int32_t GetAttributeKey3() = 0;
  /// Получить четвертый ключ атрибута для колонок типа "Запись".
  virtual int32_t GetAttributeKey4() = 0;

  /**
    \brief Получить минимальное возможное значение.
    \details Определяет минимальное значение числа в колонке.
    Используется только для колонок со значением типа (GetValueType)
    вещественный (ksValueTypeEnum::ksValueTypeFloat) 
    или целый (ksValueTypeEnum::ksValueTypeInteger).
  */
  virtual double GetMinValue() = 0;
  /**
    \brief Получить максимальное возможное значение.
    \details Определяет максимальное значение числа в колонке.
    Используется только для колонок со значением типа (GetValueType)
    вещественный (ksValueTypeEnum::ksValueTypeFloat) 
    или целый (ksValueTypeEnum::ksValueTypeInteger).
  */
  virtual double GetMaxValue() = 0;
  /**
    \brief Получить признак использования колонки моделью.
    \details Свойство позволяет настроить стиль спецификации так, 
    чтобы в документах-моделях формировались частично заполненные объекты спецификации. 
    Это позволяет избежать конфликтов взаимодействия документа-модели со спецификацией и чертежом.
    \return - true - в колонку можно вводить данные при формировании объектов спецификации в документе-модели, 
       false - заполнение колонки в объектах спецификации модели невозможно.
  */
  virtual bool IsUseIn3D() = 0;
};

