////////////////////////////////////////////////////////////////////////////////
//
/// Стиль раздела спецификации.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISpecificationSectionStyle : IKompasAPIObject
{
  /// Получить имя раздела.
  virtual std::wstring GetName() = 0;
  /// Получить номер раздела.
  virtual int32_t GetNumber() = 0;
  /// Получить по индексу общий тип колонки, по которой проводить сортировку.
  virtual ksSpecificationColumnTypeEnum GetSortColumnType(int32_t index) = 0;
  /// Получить по индексу номер колонки, по которой проводить сортировку.
  virtual int32_t GetSortColumnNumber(int32_t index) = 0;
  /**
    \brief Получить признак чтения данных из штампа.
    \return Признак чтения данных из штампа: \n 
              true  - заполнение колонок вручную с возможностью чтения информации из основных надписей, связанных с объектами спецификации чертежей, \n
              false - заполнение колонок вручную.
  */
  virtual bool IsFillDataFromStamp() = 0;
  /// Получить тип сортировки по индексу.
  virtual ksSortTypeEnum GetSortType(int32_t index) = 0;
  /// Получить колонки.
  virtual ISpecificationColumnStylesPtr GetColumns() = 0;
  /// Получить дополнительные колоноки.
  virtual ISpecificationColumnStylesPtr GetAdditionalColumns() = 0;
  /// Получить блоки дополнительных разделов.
  virtual IAdditionalBlockStylesPtr GetAdditionalBlocks() = 0;
  /// Получить количество уровней сортировки.
  virtual int32_t GetSortLevelsCount() = 0;
};

