////////////////////////////////////////////////////////////////////////////////
//
/// Элемент колонки объекта спецификации.
/**
  Элемент колонки позволяет работать с данными колонки определенного типа. 
  Этот тип соответствует типу колонки объекта спецификации или типу колонки атрибута для коло­нок типа "Запись" (ksValueTypeEnum::ksValueTypeRecord). 
  Если у колонки типа "Запись" тип атрибута не задан, то она состоит из одного элемента с типом "Строка" (ksValueTypeEnum::ksValueTypeString). 
*/
////////////////////////////////////////////////////////////////////////////////
struct ISpecificationColumnItem : IKompasAPIObject
{
  /// Получить тип значения элемента колонки.
  virtual ksValueTypeEnum GetValueType() = 0;
  /// Получить ключ: 0 - сортировки нет, >0 приоритет для сортировки.
  virtual int32_t GetKey() = 0;
  /// Установить ключ : 0 - сортировки нет, >0 приоритет для сортировки.
  virtual void SetKey(int32_t key) = 0;
  /// Получить видимость элемента.
  virtual bool IsVisible() = 0;
  /// Установить видимость элемента.
  virtual void SetVisible(bool visible) = 0;
  /// Получить значение элемента.
  virtual PropertyValue GetValue() = 0;
  /// Установить значение элемента.
  virtual void SetValue(const PropertyValue & value) = 0;
};

