////////////////////////////////////////////////////////////////////////////////
//
/// Редактор значений свойств.
/**
    Дополнительный интерфейс для IPart, IBody, IMacroObject, IInsertionObject, 
    IKompasDocument2D.
*/
////////////////////////////////////////////////////////////////////////////////
struct IPropertyKeeper : IAPIObject
{
  /**
    \brief Получить значение свойства.
    \param[in] property - свойство.
    \param[out] value - значение свойства.
    \param[in] baseUnit - признак использования базовых единиц измерения.
    \param[out] fromSource - признак получения значение свойства из источника.
    \return Успешность выполнения операции.
  */
  virtual bool GetValue(const IPropertyPtr & property, PropertyValue & value, bool baseUnit, bool & fromSource) = 0;
  /**
    \brief Установить значение свойства.
    \param[in] property - свойство.
    \param[in] value - значение свойства.
    \param[in] baseUnit - признак использования базовых единиц измерения.
    \return Успешность выполнения операции.
  */
  virtual bool SetValue(const IPropertyPtr & property, const PropertyValue & value, bool baseUnit) = 0;

  /**
    \brief Получить дополнительные данные, связанные со свойством.
    \details При первом изменении значения свойства дополнительные данные очищаются автоматически.
    \param[in] property - свойство.
    \param[in] create - признак создания хранилища, если оно отсутствует.
    \param[out] fromSource - признак получения хранилища из источника.
    \return Успешность выполнения операции.
  */
  virtual IUserDataStoragePtr GetPropertyAdditionalStorage(const IPropertyPtr & property, bool create, bool & fromSource) = 0;
  /**
    \brief Получить менеджер для работы с пользовательским хранилищем данных.
    \param[in] fromSource - признак возврата менеджера из источника объекта (true - из файла источника объекта, false - из файла владельца объекта).
    \return Менеджер пользовательских хранилищ.
  */
  virtual IUserDataStoragesMngPtr GetUserDataStoragesManager(bool fromSource) = 0;
  /**
    \brief Добавить ссылку в свойство.
    \param[in] property - свойство, в которое добавляется ссылка.
    \param[in] object - объект, на свойство или текст которого ссылаемся.
    \param[in] type - тип ссылки.
    \param[in] brackets - признак добавления скобки у ссылки.
    \param[in] textLineIndex - индекс строки в тексте объекта.
    \param[in] precision - количество выводимых знаков после запятой (для переменной).
    \param[in] propertyId - идентификатор свойства, на которое ссылаемся.
    \return Успешность выполнения операции.
  */
  virtual bool InsertHypertextReference(const IPropertyPtr & property, const IKompasAPIObjectPtr & object,
                                        ksHypertextTypeEnum type, bool brackets, int32_t textLineIndex, int32_t precision,
                                        NumericId propertyId) = 0;
  /// Получить метаданные объекта.
  virtual std::wstring GetProperties() = 0;
  /// Установить метаданные объекта.
  virtual void SetProperties(const std::wstring & properties) = 0;
  /// Получить уникальный идентификатор объекта.
  virtual std::wstring GetUniqueMetaObjectKey() = 0;
  /// Получить признак составного значения свойства.
  virtual bool IsComplexPropertyValue(const IPropertyPtr & property) = 0;
  /**
    \brief Получить значение составного свойства.
    \param[in] property - свойство.
    \param[out] fromSource - признак получения значения свойства из источника.
    \return xml-строка со структурой значения составного свойства.
  */
  virtual std::wstring GetComplexPropertyValue(const IPropertyPtr & property, bool & fromSource) = 0;
  /**
    \brief Установить значение составного свойства.
    \param[in] property - свойство.
    \param[in] propertyValue - xml-строка со структурой значения составного свойства.
    \return Успешность выполнения операции.
  */
  virtual bool SetComplexPropertyValue(const IPropertyPtr & property, const std::wstring & propertyValue) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Штамп.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IStamp : IKompasAPIObject
{
  /// Получить текст по идентификатору ячейки.
  virtual ITextPtr GetText(int32_t id) = 0;
  /// Обновить данные.
  virtual bool Update() = 0;
  /// Очистить штамп или ячейку (id <= 0 - очистить все ячейки штампа, id > 0 - очистить ячейку с указанным идентификатором).
  virtual bool Clear(int32_t id) = 0;
  /**
    \brief Получить идентификатор следующей не пустой ячейки штампа.
    \param[in] id - идентификатор ячейки с которой начинается поиск.
    \return Идентификатор не пустой ячейки.
  */
  virtual int32_t GetNextColumnId(int32_t id) = 0;
  /// Получить признак необходимости перестроения штампа.
  virtual bool IsCrossed() = 0;
  /// Получить события штампа.
  virtual IStampEventsPtr Events() = 0;
  /// Габариты таблиц штампа.
  virtual std::vector<double> GetTablesGabarits() = 0;
  /// Проверить наличие ячейки с идентификатором в текущем оформлении штампа.
  virtual bool IsCellPresent(int32_t cellId) = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// События основной надписи (штампа).
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IStampEvents : IAPIObject
{
  /// Удалить все обработчики.
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;
  /// Описание обработчика события "Начало работы со штампом".
  using OnBeginEditStampHandler = std::function<bool()>;
  /// Добавить обработчик события "Начало работы со штампом".
  virtual void AddBeginEditStampHandler(const std::wstring & handlerOwner, OnBeginEditStampHandler eventHandler) = 0;
  /// Описание обработчика события "Завершение работы со штампом".
  using OnEndEditStampHandler = std::function<void(bool wasChanged)>;
  /// Добавить обработчик события "Завершение работы со штампом".
  virtual void AddEndEditStampHandler(const std::wstring & handlerOwner, OnEndEditStampHandler eventHandler) = 0;
  /// Описание обработчика события "Двойной клик в ячейке штампа".
  using OnStampCellDblClickHandler = std::function<bool(int32_t cellId)>;
  /// Добавить обработчик события "Двойной клик в ячейке штампа".
  virtual void AddStampCellDblClickHandler(const std::wstring & handlerOwner, OnStampCellDblClickHandler eventHandler) = 0;
  /// Описание обработчика события "Начало редактирования в ячейке штампа".
  using OnStampCellBeginEditHandler = std::function<bool(int32_t cellId)>;
  /// Добавить обработчик события "Начало редактирования в ячейке штампа".
  virtual void AddStampCellBeginEditHandler(const std::wstring & handlerOwner, OnStampCellBeginEditHandler eventHandler) = 0;
  /// Описание обработчика события "Начало очистки ячеек штампа".
  using OnStampBeginClearCellsHandler = std::function<bool(const std::vector<int32_t> & currentCellId)>;
  /// Добавить обработчик события "Начало очистки ячеек штампа".
  virtual void AddStampBeginClearCellsHandler(const std::wstring & handlerOwner, OnStampBeginClearCellsHandler eventHandler) = 0;
};


