  virtual int32_t GetId() = 0;
  /// Установить состояние доступность контрола.
  virtual void SetEnable(bool enable) = 0;
  /// Получить состояние доступность контрола.
  virtual bool IsEnable() = 0;
  /// Установить идентификатор предопределённого ввода.
  virtual void SetPredefineNumber(int32_t predefineNumber) = 0;
  /// Получить идентификатор предопределённого ввода.
  virtual int32_t GetPredefineNumber() = 0;
  /// Добавить дополнительную кнопку.
