////////////////////////////////////////////////////////////////////////////////
//
/// События панели свойств и параметров процесса.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IPropertiesManagerEvents : IAPIObject
{
  /// Отписаться от всех событий.
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;

  /// Описание обработчика "Нажатие кнопки спецпанели".
  using OnButtonClickHandler = std::function<bool(int32_t buttonId)>;
  /// Добавить обработчик события "Нажатие кнопки спецпанели".
  virtual void AddButtonClickHandler(const std::wstring & handlerOwner, OnButtonClickHandler eventHandler) = 0;

  /// Описание обработчика "Изменение значения контрола".
  using OnChangeControlValueHandler = std::function<void(const IPropertyControlPtr & control)>;
  /// Добавить обработчик события "Изменение значения контрола".
  virtual void AddChangeControlValueHandler(const std::wstring & handlerOwner, OnChangeControlValueHandler eventHandler) = 0;

  /// Описание обработчика "Нажатие кнопки контрола".
  using OnControlCommandHandler = std::function<void(const IPropertyControlPtr & control, int32_t buttonId)>;
  /// Добавить обработчик события "Нажатие кнопки контрола".
  virtual void AddControlCommandHandler(const std::wstring & handlerOwner, OnControlCommandHandler eventHandler) = 0;

  /// Описание обработчика "Установка состояния кнопки спецпанели".
  using OnButtonUpdateHandler = std::function<bool(int32_t buttonId, bool & enable, int32_t & checked)>;
  /// Добавить обработчик события "Установка состояния кнопки спецпанели".
  virtual void AddButtonUpdateHandler(const std::wstring & handlerOwner, OnButtonUpdateHandler eventHandler) = 0;

  /// Описание обработчика "Активизация процесса".
  using OnProcessActivateHandler = std::function<void()>;
  /// Добавить обработчик события "Активизация процесса".
  virtual void AddProcessActivateHandler(const std::wstring & handlerOwner, OnProcessActivateHandler eventHandler) = 0;

  /// Описание обработчика "Деактивизация процесса".
  using OnProcessDeactivateHandler = std::function<void()>;
  /// Добавить обработчик события "Деактивизация процесса".
  virtual void AddProcessDeactivateHandler(const std::wstring & handlerOwner, OnProcessDeactivateHandler eventHandler) = 0;

  /// Описание обработчика "Выделение элемента".
  using OnSelectItemHandler = std::function<void(const IPropertyControlPtr & control, int32_t index, bool select)>;
  /// Добавить обработчик события "Выделение элемента".
  virtual void AddSelectItemHandler(const std::wstring & handlerOwner, OnSelectItemHandler eventHandler) = 0;

  /// Описание обработчика "Выбор элемента".
  using OnCheckItemHandler = std::function<void(const IPropertyControlPtr & control, int32_t index, bool check)>;
  /// Добавить обработчик события "Выбор элемента".
  virtual void AddCheckItemHandler(const std::wstring & handlerOwner, OnCheckItemHandler eventHandler) = 0;

  /// Описание обработчика "Выделение ячейки таблицы".
  using OnSelectCellHandler = std::function<void(const IPropertyControlPtr & control, int32_t row, int32_t column)>;
  /// Добавить обработчик события "Выделение ячейки таблицы".
  virtual void AddSelectCellHandler(const std::wstring & handlerOwner, OnSelectCellHandler eventHandler) = 0;

  /// Описание обработчика "Установка/снятие фокуса на редакторе ввода".
  using OnEditFocusHandler = std::function<void(const IPropertyControlPtr & control, bool setFocus)>;
  /// Добавить обработчик события "Установка/снятие фокуса на редакторе ввода".
  virtual void AddEditFocusHandler(const std::wstring & handlerOwner, OnEditFocusHandler eventHandler) = 0;
  /// Описание обработчика "Нажатие пункта пользовательского меню".
  using OnUserMenuCommandHandler = std::function<void(const IPropertyControlPtr & control, int32_t commandId)>;
  /// Добавить обработчик события "Нажатие пункта пользовательского меню".
  virtual void AddUserMenuCommandHandler(const std::wstring & handlerOwner, OnUserMenuCommandHandler eventHandler) = 0;
  /// Описание обработчика "CLLBACK для получения типа контекстного меню".
  using OnGetContextMenuTypeHandler = std::function<ksProcessContextMenuType(int32_t screenX, int32_t screenY)>;
  /// Добавить обработчик события "CLLBACK для получения типа контекстного меню".
  virtual void AddGetContextMenuTypeHandler(const std::wstring & handlerOwner, OnGetContextMenuTypeHandler eventHandler) = 0;
  /// Описание обработчика "CLLBACK для накачки контекстной панели".
  using OnFillContextPanelHandler = std::function<void(const IProcessContextPanelPtr & contextPanel)>;
  /// Добавить обработчик события "CLLBACK для накачки контекстной панели".
  virtual void AddFillContextPanelHandler(const std::wstring & handlerOwner, OnFillContextPanelHandler eventHandler) = 0;
  /// Описание обработчика "CLLBACK для накачки контекстного меню".
  using OnFillContextIconMenuHandler = std::function<void(const IProcessContextIconMenuPtr & contextMenu)>;
  /// Добавить обработчик события "CLLBACK для накачки контекстного меню".
  virtual void AddFillContextIconMenuHandler(const std::wstring & handlerOwner, OnFillContextIconMenuHandler eventHandler) = 0;
  /// Описание обработчика "Завершение редактирования текста элемента списка".
  using OnEndEditItemHandler = std::function<void(const IPropertyControlPtr & control, int32_t itemIndex)>;
  /// Добавить обработчик события "Завершение редактирования текста элемента списка".
  virtual void AddEndEditItemHandler(const std::wstring & handlerOwner, OnEndEditItemHandler eventHandler) = 0;
  /// Описание обработчика "Сворачивание/разворачивание закладки панели свойств".
  using OnChangeTabExpandedHandler = std::function<void(int32_t tabIndex)>;
  /// Добавить обработчик события "Сворачивание/разворачивание закладки панели свойств".
  virtual void AddChangeTabExpandedHandler(const std::wstring & handlerOwner, OnChangeTabExpandedHandler eventHandler) = 0;
  /// Описание обработчика "Двойной клик по элементу в списке".
  using OnDoubleClickItemHandler = std::function<void(const IPropertyControlPtr & control, int32_t itemIndex)>;
  /// Добавить обработчик события "Двойной клик по элементу в списке".
  virtual void AddDoubleClickItemHandler(const std::wstring & handlerOwner, OnDoubleClickItemHandler eventHandler) = 0;

  /// Описание обработчика события "Запрос контекстного меню для контрола".
  using OnContextMenuRequestHandler = std::function<void(const IPropertyControlPtr & control)>;
  /// Добавить обработчик события "Запрос контекстного меню для контрола".
  virtual void AddContextMenuRequestHandler(const std::wstring & handlerOwner, OnContextMenuRequestHandler eventHandler) = 0;
  /// Описание обработчика "Установка состояния команд меню для контрола".
  using OnMenuCommandUpdateHandler =
    std::function<void(const IPropertyControlPtr & control, int32_t commandId, bool & enable, bool & checked)>;
  /// Добавить обработчик события "Установка состояния команд меню для контрола".
  virtual void AddMenuCommandUpdateHandler(const std::wstring & handlerOwner, OnMenuCommandUpdateHandler eventHandler) = 0;
};

////////////////////////////////////////////////////////////////////////////////
