  /// Получить фильтр слоёв по статусу (ksStateTRUE - фильтрация по непустым слоям, ksStateFALSE - по пустым).
  virtual FilterConditionStateEnum GetHaveObjects() = 0;
  /// Установить фильтр слоёв по цвету.
  virtual void SetColor(Color color) = 0;
  /// Получить фильтр слоёв по цвету.
  virtual Color GetColor() = 0;
  /// Установить фильтр слоёв по комментарию.
  virtual void SetComment(const std::wstring & comment) = 0;
  /// Получить фильтр слоёв по комментарию.
  virtual std::wstring GetComment() = 0;
  /// Установить фильтр слоёв по разрешению к проецированию (для 3D слоёв) (ksStateTRUE - фильтровать по разрешенным к проецированию, ksStateFALSE - по запрещённым).
  virtual void SetProjected(FilterConditionStateEnum projected) = 0;
  /// Получить фильтр слоёв по разрешению к проецированию (для 3D слоёв) (ksStateTRUE - фильтрация по разрешенным к проецированию, ksStateFALSE - по запрещённым).
