////////////////////////////////////////////////////////////////////////////////
//
/// Объект дерева, представитель объекта модели.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IFeature : IAPIObject
{
  /// Получить имя объекта.
  virtual std::wstring GetName() = 0;
  /// Получить значение, определяющее время изменения геометрии.
  virtual int32_t GetUpdateStamp() = 0;
  /// Получить объект-владелец.
  virtual IFeaturePtr GetOwnerFeature() = 0;
  /// Получить признак невырожденности объекта.
  virtual bool IsValid() = 0;
  /// Установить признак исключения из расчета.
  virtual void SetExcluded(bool excluded) = 0;
  /// Получить признак исключения из расчета.
  virtual bool IsExcluded() = 0;
  /// Получить объекты, входящие в состав данного объекта (грани, ребра, вершины).
  virtual std::vector<IModelObjectPtr> GetModelObjects(const std::vector<int32_t> & objType) = 0;
  /// Получить тип объекта модели (из ksObj3dTypeEnum: o3d_part - деталь, o3d_entity - объект, o3d_mateConstraint - сопряжение).
  virtual ksObj3dTypeEnum GetFeatureType() = 0;
  /// Удалить компонент.
  virtual bool Delete() = 0;
  /**
    \brief Получить массив элементов дерева заданного типа.
    \param[in] treeType - тип дерева.
    \param[in] through - признак получения невидимых элементов (true - получить невидимые, false - не получать).
    \param[in] libObject - признак получения элементов, если текущий объект - библиотечный (true - вернуть вложенные элементы, false - не возвращать).
    \return Массив вложенных элементов.
  */
  virtual std::vector<IFeaturePtr> GetSubFeatures(ksTreeTypeEnum treeType, bool through, bool libObject) = 0;
  /// Получить массив всех тел элемента дерева.
  virtual std::vector<IBodyPtr> GetResultBodies() = 0;
  /**
    \brief Получить массив параметрических переменных.
    \param[in] external - признак получения только внешних переменных (true - получить только внешние, false - получить все).
    \param[in] inSource - признак получения только переменных источника (true - получить только переменные источника, false - получить все).
    \return Массив переменных.
  */
  virtual std::vector<IVariablePtr> GetVariables(bool external, bool inSource) = 0;
  /**
    \brief Получить параметрическую переменную по индексу.
    \param[in] external - признак получения только внешних переменных (true - получить только внешние, false - получить все).
    \param[in] inSource - признак получения только переменных источника (true - получить только переменные источника, false - получить все).
    \param[in] index - индекс переменной.
    \return Переменная.
  */
  virtual IVariablePtr GetVariable(bool external, bool inSource, int32_t index) = 0;
  /**
    \brief Получить параметрическую переменную по имени.
    \param[in] external - признак получения только внешних переменных (true - получить только внешние, false - получить все).
    \param[in] inSource - признак получения только переменных источника (true - получить только переменные источника, false - получить все).
    \param[in] name - имя переменной.
    \return Переменная.
  */
  virtual IVariablePtr GetVariableByName(bool external, bool inSource, const std::wstring & name) = 0;
  /// Получить параметрическую переменную по размеру.
  virtual IVariablePtr GetDimensionVariable(const IDimension3DPtr & dimension) = 0;
  /**
    \brief Получить количество параметрических переменных.
    \param[in] external - признак подсчёта только внешних переменных (true - получить количество только внешних, false - всех).
    \param[in] inSource - признак подсчёта только переменных источника (true - получить количество переменных источника, false - всех).
    \return Количество переменных.
  */
  virtual int32_t GetVariablesCount(bool external, bool inSource) = 0;
  /// Получить номер ошибки.
  virtual int32_t GetObjectError() = 0;
  /// Получить комбинацию флагов состояния объекта (из перечисления ksFeatureStateEnum).
  virtual int32_t GetState() = 0;
  /// Получить отображаемое имя объекта в дереве.
  virtual std::wstring GetLabel() = 0;
  /// Получить признак нахождения объекта ниже конца построения модели.
  virtual bool IsRollBacked() = 0;
  /// Получить признак изменения объекта с момента последнего перестроения.
  virtual bool IsModified(bool recursive) = 0;
  /// Получить порядковый номер.
  virtual int32_t GetOrderNumber() = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// Модельный объект.
/**
  
*/
////////////////////////////////////////////////////////////////////////////////
struct IModelObject : IKompasAPIObject
{
  /// Получить имя элемента трехмерной модели.
  virtual std::wstring GetName() = 0;
  /// Установить имя элемента трехмерной модели.
  virtual void SetName(const std::wstring & name) = 0;
  /// Установить состояние видимости объекта.
  virtual void SetHidden(bool hidden) = 0;
  /// Получить состояние видимости объекта.
  virtual bool IsHidden() = 0;
  /// Обновить данные объекта.
  virtual bool Update() = 0;
  /// Получить признак невырожденности объекта.
  virtual bool IsValid() = 0;
  /// Получить компонент, владеющий элементом.
  virtual IPartPtr GetPart() = 0;
  /// Получить тип 3D объекта.
  virtual ksObj3dTypeEnum GetModelObjectType() = 0;
  /// Получить объект, породивший этот объект.
  virtual IFeaturePtr GetOwner() = 0;
  /// Получить признак многочастичности компонента.
  virtual bool IsMultiBodyParts() = 0;
  /// Получить "части тела".
  virtual IBodyPartsPtr GetBodyParts() = 0;
  /**
    \brief Получить родителей объекта.
    \param[in] relationType - тип родственных отношений.
    \return Массив родителей объекта.
  */
  virtual std::vector<IModelObjectPtr> GetParents(ksRelationTypeEnum relationType) = 0;
  /**
    \brief Получить потомков объекта.
    \param[in] relationType - тип родственных отношений.
    \return Массив потомков объекта.
  */
  virtual std::vector<IModelObjectPtr> GetChildrens(ksRelationTypeEnum relationType) = 0;
  /// Получить ccылки на опорные примитивы объекта.
  virtual std::vector<IModelObjectPtr> GetLinks() = 0;
  /**
    \brief Проверить, является ли примитив опорным для объекта.
    \param[in] relationType - тип родственных отношений.
    \param[in] primitive - проверяемый примитив.
    \return Признак, что примитив является опорным.
  */
  virtual bool IsMyLink(ksRelationTypeEnum relationType, const IModelObjectPtr & primitive) = 0;
  /// Получить номер слоя.
  virtual int32_t GetLayerNumber() = 0;
  /// Установить номер слоя.
  virtual void SetLayerNumber(int32_t layerNumber) = 0;
  /// Установить опции проецирования.
  virtual void SetProjected(ksProjectionOptionEnum projectionType) = 0;
  /// Получить опции проецирования.
  virtual ksProjectionOptionEnum GetProjected() = 0;
  /// Установить состояние видимости объекта.
  virtual void SetVisibleState(ksVisibleStateEnum visibleState) = 0;
  /// Получить состояние видимости объекта.
  virtual ksVisibleStateEnum GetVisibleState() = 0;
  /// Установить способ редактирования.
  virtual void SetEditable(ksEditableStateEnum editableState) = 0;
  /// Получить способ редактирования.
  virtual ksEditableStateEnum GetEditable() = 0;
  /// Сбросить заданные параметры.
  virtual bool Reset() = 0;
  /// Получить математический объект.
  virtual IKompasAPIObjectPtr GetMathObject() = 0;
  /// Установить признак связи объекта зависимого исполнения с соответствующим объектом исходного исполнения.
  virtual void SetConnectedWithInitialEmbodiment(bool connected) = 0;
  /// Получить признак связи объекта зависимого исполнения с соответствующим объектом исходного исполнения.
  virtual bool IsConnectedWithInitialEmbodiment() = 0;
  /// Получить признак текущей доступности редактирования объекта.
  virtual bool IsEditableObject() = 0;
  /// Получить признак, что объект является внешним по отношению к текущему редактируемому контексту.
  virtual bool IsExternalObject() = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Модельный объект.
/**
  
*/
////////////////////////////////////////////////////////////////////////////////
struct IModelObjectEx : IAPIObject
{
  /**
    \brief Получить параметры цвета объекта с учетом настроек объекта и его владельцев.
    \param[out] color - цвет.
    \param[out] ambient - рассеяный свет в тени (в долях от единицы).
    \param[out] diffuse - диффузный свет (воздействие на объект направленного источника света) (в долях от единицы).
    \param[out] specularity - зеркальность. Определяет блики (зеркальные отражения) на объекте (в долях от единицы).
    \param[out] shininess - блеск. Определяет размер и интенсивность бликов на объекте (в долях от единицы).
    \param[out] transparency - прозрачность (в долях от единицы, 0 - полностью непрозрачный, 1 - полностью прозрачный).
    \param[out] emission - собственный свет объекта (в долях от единицы).
    \return Успешность получения параметров.
  */
  virtual bool GetDrawColor(Color & color, double & ambient, double & diffuse, double & specularity, double & shininess,
                            double & transparency, double & emission) = 0;
};


