////////////////////////////////////////////////////////////////////////////////
//
/// Таблица переменных.
/**
*/
////////////////////////////////////////////////////////////////////////////////
struct IVariableTable : IAPIObject
{
  /// Получить количество строк.
  virtual int32_t GetRowsCount() = 0;
  /// Получить количество столбцов.
  virtual int32_t GetColumnsCount() = 0;

  /// Получить имя переменной по индексу.
  virtual std::wstring GetVariableName(int32_t column) = 0;
  /// Установить имя переменной по индексу.
  virtual void SetVariableName(int32_t column, const std::wstring & variableName) = 0;

  /// Получить массив переменных.
  virtual std::vector<std::wstring> GetVariableNames() = 0;
  /// Установить массив переменных.
  virtual void SetVariableNames(const std::vector<std::wstring> & variableNames) = 0;

  /// Получить комментарий к строке.
  virtual std::wstring GetComment(int32_t row) = 0;
  /// Установить комментарий к строке.
  virtual void SetComment(int32_t row, const std::wstring & comment) = 0;

  /// Получить строку таблицы по индексу.
  virtual std::vector<double> GetTableRow(int32_t row) = 0;
  /// Получить строку таблицы по комментарию.
  virtual std::vector<double> GetTableRowByComment(const std::wstring & comment) = 0;

  /// Установить строку таблицы по индексу.
  virtual void SetTableRow(int32_t row, const std::vector<double> & values) = 0;
  /// Установить строку таблицы по комментарию.
  virtual void SetTableRowByComment(const std::wstring & comment, const std::vector<double> & values) = 0;

  /// Получить значение ячейчки.
  virtual double GetCell(int32_t row, int32_t column) = 0;
  /// Установить значение ячейчки.
  virtual void SetCell(int32_t row, int32_t column, double value) = 0;

  /// Применить параметры строки, заданной по индексу, к компоненту.
  virtual bool ApplyVariables(int32_t row) = 0;
  /// Применить параметры строки, заданной по комментарию, к компоненту.
  virtual bool ApplyVariablesByComment(const std::wstring & comment) = 0;

  /**
    \brief Открыть диалоговое окно выбора строки таблицы.
    \param[in] windowHandle - дескриптор окна (nullptr - главное окно).
    \param[in] selectString - признак открытия окна только для выбора строки таблицы.
                              true - убрать возможность редактирования таблицы (скрыть кнопку "Применить"), 
                              false - оставить возможность редактирования таблицы.
    \return индекс выбранной пользователем строки.
  */
  virtual int32_t GetVisualTable(WindowHandle windowHandle, bool selectString) = 0;

  /**
    \brief Добавить столбец.
    \param[in] variableName - имя переменной.
    \return Индекс добавленого столбца (-1 в случае неудачи).
  */
  virtual int32_t AddColumn(const std::wstring & variableName) = 0;
  /// Удалить столбец по индексу.
  virtual bool DeleteColumn(int32_t column) = 0;
  /// Удалить столбец по имени переменной.
  virtual bool DeleteColumnByName(const std::wstring & variableName) = 0;

  /**
    \brief Добавить строку.
    \param[in] comment - коментарий к строке.
    \return Индекс добавленой строки (-1 в случае неудачи).
  */
  virtual int32_t AddRow(const std::wstring & comment) = 0;
  /// Удалить строку по индексу.
  virtual bool DeleteRow(int32_t row) = 0;
  /// Удалить строку по комментарию.
  virtual bool DeleteRowByComment(const std::wstring & comment) = 0;

  /// Очистить содержимое таблицы.
  virtual bool Clear() = 0;
  /// Получить номер столбца по имени переменной.
  virtual int32_t FindColumnIndex(const std::wstring & variableName) = 0;
};


