////////////////////////////////////////////////////////////////////////////////
//
/// Локальная система координат.
/**
*/
////////////////////////////////////////////////////////////////////////////////
struct ILocalCoordinateSystem : IPoint3D
{
  /**
    \brief Установить смещение вдоль собственной оси.
    \param[in] axis - ось, вдоль которой требуется сместить ЛСК. 
               Доступные значения: (ksObj3dTypeEnum::o3d_axisOX, ksObj3dTypeEnum::o3d_axisOY, ksObj3dTypeEnum::o3d_axisOZ).
    \param[in] displacement - расстояние смещения.
    \return Успешность смещения.
  */
  virtual bool SetDisplacementByAxis(ksObj3dTypeEnum axis, double displacement) = 0;
  /// Установить тип ориентирования ЛСК.
  virtual void SetOrientationType(ksOrientationTypeEnum orientationType) = 0;
  /// Получить тип ориентирования ЛСК.
  virtual ksOrientationTypeEnum GetOrientationType() = 0;
  /**
    \brief Прочитать и установить направления осей из текстового файла.
    \details Файл должен иметь текстовый формат и состоять из трёх строк. 
             Каждая строка соответствует оси координат и должна состоять из трёх вещественных чисел, разделённых символом ' ' (пробел).
             Файл можно записать методом WriteToFile.
    \param[in] filename - имя файла с параметрами.
    \return Успешность выполнения.
  */
  virtual bool ReadFromFile(const std::wstring & fileName) = 0;
  /**
    \brief Записать направления осей в текстовый файл.
    \details В результате выполнения будут записаны данные в текстовый файл.
             Данные представляют из себя три строки по три координаты, разделённые символом ' ' (пробел).
             Файл можно использовать в методое ReadFromFile.
    \param[in] filename - имя файла с параметрами.
    \return Успешность записи.
  */
  virtual bool WriteToFile(const std::wstring & fileName) = 0;
  /// Установить исходную ориентацию (исходной СК).
  virtual bool SetStartingOrientation() = 0;
  /**
    \brief Получить вектора направлений главных осей.
    \param[in] axis - тип оси (доступные типы: ksObj3dTypeEnum::o3d_axisOX, ksObj3dTypeEnum::o3d_axisOY, ksObj3dTypeEnum::o3d_axisOZ).
    \param[out] x, y, z - вектор направления заданной оси.
    \return Успешность записи.
  */
  virtual bool GetVector(ksObj3dTypeEnum axis, double & x, double & y, double & z) = 0;
  /**
    \brief Получить интерфейс параметров ЛСК.
    \return Интерфейс параметров ЛСК.
            Тип возвращаемого интерфейса зависит от заданного типа ориентации (метод SetOrientationType).
            Для ksOrientationTypeEnum::ksAxisOrientation интерфейс ILocalCSAxesDirectionParam,
            для ksOrientationTypeEnum::ksEulerCorners интерфейс ILocalCSEulerParam,
            для ksOrientationTypeEnum::ksOrientByObject интерфейс ILocalCSOrientByObjectParam.
  */
  virtual IKompasAPIObjectPtr GetLocalCSParameters() = 0;
  /// Установить для данной ЛСК признак текущей ЛСК (true - сделать текущей, false - не текущей).
  virtual void SetCurrent(bool current) = 0;
  /// Получить для данной ЛСК признак текущей ЛСК (true - текущая, false - не текущая).
  virtual bool IsCurrent() = 0;
  /**
    \brief Получить примитив ЛСК (ось или плоскость).
    \param[in] Тип получаемого примитива. Доступные типы:
               ksObj3dTypeEnum::o3d_planeXOY, ksObj3dTypeEnum::o3d_planeXOZ, ksObj3dTypeEnum::o3d_planeYOZ,
               ksObj3dTypeEnum::o3d_axisOX, ksObj3dTypeEnum::o3d_axisOY, ksObj3dTypeEnum::o3d_axisOZ.
    \return Интерфейс примитива ЛСК. Тип возвращаемого интерфейса, для плоскостей - IPlane3D, для осей - IAxis3D.
  */
  virtual IModelObjectPtr GetDefaultObject(ksObj3dTypeEnum objectType) = 0;
  /// Установить систему координат по матрице 4х4, представленной массивом из 16-ти элементов.
  virtual bool InitByMatrix3D(const std::vector<double> & mtr) = 0;
  /**
    \brief Получить вектор, задающий направление оси.
    \param[in] axis - тип оси (доступные типы: ksObj3dTypeEnum::o3d_axisOX, ksObj3dTypeEnum::o3d_axisOY, ksObj3dTypeEnum::o3d_axisOZ).
    \return Вектор, представляющий ось координат.
  */
  virtual IVector3DPtr GetVector3D(ksObj3dTypeEnum axis) = 0;
  /// Установить признак видимости имени ЛСК (имя задаётся через интерфейс IModelObject) (true - показывать имя, false - не показывать).
  virtual void SetShowName(bool showName) = 0;
  /// Получить признак видимости имени ЛСК (имя задаётся через интерфейс IModelObject) (true - имя видимо, false - не видимо).
  virtual bool IsShowName() = 0;

  /// Преобразовать координаты точки из присланной СК в текущую систему координат.
  virtual bool TransformPointFromLocalCS(double & x, double & y, double & z, const IModelObjectPtr & otherCS) = 0;
  /// Преобразовать координаты точек из присланной СК в текущую систему координат.
  virtual bool TransformPointsFromLocalCS(std::vector<double> & points, const IModelObjectPtr & otherCS) = 0;
  /// Преобразовать координаты точки из текущей системы координат в присланную СК.
  virtual bool TransformPointToLocalCS(double & x, double & y, double & z, const IModelObjectPtr & otherCS) = 0;
  /// Преобразовать координаты точек из текущей системы координат в присланную СК.
  virtual bool TransformPointsToLocalCS(std::vector<double> & points, const IModelObjectPtr & otherCS) = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// Локальная система координат (положение объекта).
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IPlacement3D : IKompasAPIObject
{
  /// Получить координаты начала локальной системы координат.
  virtual bool GetOrigin(double & x, double & y, double & z) = 0;
  /// Установить координаты начала локальной системы координат.
  virtual bool SetOrigin(double x, double y, double z) = 0;
  /// Получить вектор для указанной оси.
  virtual bool GetVector(ksObj3dTypeEnum axis, double & x, double & y, double & z) = 0;
  /// Установить вектор для указанной оси.
  virtual bool SetVector(ksObj3dTypeEnum axis, double x, double y, double z) = 0;
  /// Установить систему координат по матрице (размер 4x4).
  virtual bool InitByMatrix3D(const std::vector<double> & matrix) = 0;
  /// Получить в виде массива матрицу системы координат (размер 4x4).
  virtual std::vector<double> GetMatrix3D() = 0;
  /// Получить проекцию точки на плоскость XY.
  virtual bool GetPointProjectionToXY(double pointX, double pointY, double pointZ, double & projectionX,
                                      double & projectionY) = 0;
  /// Получить координаты пространственной точки по координатам точки на плоскости XY.
  virtual bool GetPoint3D(double planeX, double planeY, double & pointX, double & pointY, double & pointZ) = 0;
  /**
    \brief Повернуть систему координат на угол вокруг оси.
    \param[in] x0, y0, z0 - координаты точки оси.
    \param[in] axisX, axisY, axisZ - координаты направляющего ось вектора.
    \param[in] angle - угол поворота (в градусах).
    \return Успешность выполнения операции.
  */
  virtual bool Rotate(double x0, double y0, double z0, double axisX, double axisY, double axisZ, double angle) = 0;
  /**
    \brief Получить направления углов Эйлера.
    \param[out] v - угол нутации (в градусах).
    \param[out] fi - угол прецессии (в градусах).
    \param[out] fau - угол чистого вращения (в градусах).
    \return Успешность выполнения операции.
  */
  virtual bool GetEulerAngles(double & v, double & fi, double & fau) = 0;
  /**
    \brief Установить направления углов Эйлера.
    \param[in] v - угол нутации (в градусах).
    \param[in] fi - угол прецессии (в градусах).
    \param[in] fau - угол чистого вращения (в градусах).
    \return Успешность выполнения операции.
  */
  virtual bool SetEulerAngles(double v, double fi, double fau) = 0;
};

