////////////////////////////////////////////////////////////////////////////////
//
/// Твердое тело.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IBody : IModelObject
{
  /// Получить габарит.
  virtual bool GetGabarit(double & x1, double & y1, double & z1, double & x2, double & y2, double & z2) = 0;
  /// Получить обозначение тела.
  virtual std::wstring GetMarking() = 0;
  /// Установить обозначение тела.
  virtual void SetMarking(const std::wstring & marking) = 0;
  /// Получить параметры штриховки.
  virtual IHatchParamPtr GetHatchParam() = 0;
  /// Получить параметры.
  virtual IAPIObjectPtr GetUserParameters(const std::wstring & parameters) = 0;
  /// Получить идентификатор тела.
  virtual int32_t GetBodyId() = 0;
  /// Установить признак создания объектов спецификации.
  virtual void SetCreateSpcObjects(bool create) = 0;
  /// Получить признак создания объектов спецификации.
  virtual bool IsCreateSpcObjects() = 0;
  /// Получить идентификатор начального тела.
  virtual int32_t GetBeginBodyId() = 0;
  /// Получить идентификатор конечного тела.
  virtual int32_t GetFinalBodyId() = 0;
  /// Получить идентификатор тела, которое поглотило это тело.
  virtual int32_t GetOwnerBodyId() = 0;
  /// Получить признак твёрдого тела или оболочки (true - твердое тело, false - оболочка).
  virtual bool IsSolid() = 0;

  /**
    \brief Найти пересечения c кривой.
    \param[in] curve - 3D кривая.
    \param[out] faces - грани, пересекаемые кривой.
    \param[out] points - координаты точек пересечений.
    \return true - пересечения найдены, false - в случае неудачи.
  */
  virtual bool CurveIntersection(const IMathCurve3DPtr & curve, std::vector<IFacePtr> & faces, std::vector<double> & points) = 0;

  /**
    \brief Проверить наличие пересечений с другим телом.
    \param[in] otherBody - тело, с которым проверяется пересечение.
    \param[in] checkTangent - считать касания пересечениями.
    \return Массив Intersection_Type типов пересечений (0 в случае неудачи).
  */
  virtual std::vector<int32_t> CheckIntersectionWithBody(const IBodyPtr & otherBody, bool checkTangent) = 0;

  /**
    \brief Проверить наличие пересечений с другим телом.
    \param[in] otherBody - тело, с которым проверяется пересечение.
    \param[out] intersectionFaces1 - пересекаемые грани первого тела.
    \param[out] intersectionFaces2 - пересекаемые грани второго тела.
    \param[out] connectedFaces1 - совпадающие грани первого тела.
    \param[out] connectedFaces2 - совпадающие грани второго тела.
    \return true - пересечения найдены, false - в случае неудачи.
  */
  virtual bool GetIntersectedFaces(const IBodyPtr & otherBody, std::vector<IFacePtr> & intersectionFaces1,
                                   std::vector<IFacePtr> & intersectionFaces2, std::vector<IFacePtr> & connectedFaces1,
                                   std::vector<IFacePtr> & connectedFaces2) = 0;
};

