  /// Снять выделение со всех объектов.
  virtual bool UnselectAll() = 0;
  /// Получить признак является ли объект выделенным.
  virtual bool IsSelected(const IKompasAPIObjectPtr & object) = 0;
  /// Получить массив выделенных объектов.
