////////////////////////////////////////////////////////////////////////////////
//
/// События менеджера выделенных объектов.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISelectionManagerEvents : IAPIObject
{
  /// Удалить все обработчики.
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;
  /// Описание обработчика события "Объект выделен".
  using OnSelectHandler = std::function<void(const std::vector<IKompasAPIObjectPtr> & objects)>;
  /// Добавить обработчик события "Объект выделен".
  virtual void AddSelectHandler(const std::wstring & handlerOwner, OnSelectHandler eventHandler) = 0;
  /// Описание обработчика события "Снято выделение объекта".
  using OnUnselectHandler = std::function<void(const std::vector<IKompasAPIObjectPtr> & objects)>;
  /// Добавить обработчик события "Снято выделение объекта".
  virtual void AddUnselectHandler(const std::wstring & handlerOwner, OnUnselectHandler eventHandler) = 0;
  /// Описание обработчика события "Снято выделение всех объектов".
  using OnUnselectAllHandler = std::function<void()>;
  /// Добавить обработчик события "Снято выделение всех объектов".
  virtual void AddUnselectAllHandler(const std::wstring & handlerOwner, OnUnselectAllHandler eventHandler) = 0;
};

