////////////////////////////////////////////////////////////////////////////////
//
/// Процесс в 3D документе.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IProcess3D : IAPIObject
{
  /// Получить положение объекта.
  virtual IPlacement3DPtr GetPlacement() = 0;

  /// Получить фантомный объект.
  virtual IModelObjectPtr GetPhantomObject() = 0;
  /// Установить фантомный объект.
  virtual void SetPhantomObject(const IModelObjectPtr & object) = 0;

  /// Получить объекты для сопряжения.
  virtual std::vector<IModelObjectPtr> GetMateConstraintsObjects() = 0;
  /// Установить объекты для сопряжения.
  virtual void SetMateConstraintsObjects(const std::vector<IModelObjectPtr> & objects) = 0;

  /// Получить коллекцию сопряжений.
  virtual IMateConstraints3DPtr GetMateConstraints() = 0;

  /**
    \brief Запустить подчиненный режим создания объектов.
    \param[in] processType - тип подпроцесса.
    \param[in] takeObject - редактируемый объект.
    \param[in] needCreateTakeObj - признак создания объекта в подпроцессе.
    \param[in] lostTakeObj - фиксировать параметры создаваемого объекта.
    \return Успешность выполнения операции.
  */
  virtual bool RunTakeCreateObjectProcess(ProcessTypeEnum processType, const IModelObjectPtr & takeObject, bool needCreateTakeObj,
                                          bool lostTakeObj) = 0;

  /// Получить объект, редактируемый в подпроцессе.
  virtual IModelObjectPtr GetTakeProcessObject() = 0;
  /// Установить объект для редактирования в подроцессе.
  virtual void SetTakeProcessObject(const IModelObjectPtr & object) = 0;

  /// Получить коллекцию манипуляторов.
  virtual IManipulatorsPtr GetManipulators() = 0;

  /// Получить режим использования прямоугольной рамки для выделения объектов.
  virtual ksSelectionBandMode GetSelectionBandMode() = 0;
  /// Установить режим использования прямоугольной рамки для выделения объектов.
  virtual void SetSelectionBandMode(ksSelectionBandMode bandMode) = 0;

  /// Получить способ фильтрации 3D объектов.
  virtual bool GetObjectsFilter3D(ksProcessObjectsFilter3DEnum objectsFilter) = 0;
  /// Установить способ фильтрации 3D объектов.
  virtual void SetObjectsFilter3D(ksProcessObjectsFilter3DEnum objectsFilter, bool set) = 0;

  /// Получить признак очистки стэка команд Undo процесса.
  virtual bool IsClearProcessUndo() = 0;
  /// Установить признак очистки стэка команд Undo процесса.
  virtual void SetClearProcessUndo(bool clear) = 0;

  /// Создать фантом из файла.
  virtual IModelObjectPtr CreatePhantomFromFile(const std::wstring & fileName) = 0;
  /// Сохранить фантом.
  virtual bool StorePhantom() = 0;

  /// Получить события.
  virtual IProcess3DEventsPtr Events() = 0;
};

