////////////////////////////////////////////////////////////////////////////////
//
/// Параметры текста в размере.
/**
  Параметры текста в размере:
    значение, точность, стиль, шрифт, префикс и суффикс.
*/
////////////////////////////////////////////////////////////////////////////////
struct IDimensionText : IAPIObject
{
  /// Получить стиль текста.
  virtual int32_t GetStyle() = 0;
  /// Установить стиль текста.
  virtual void SetStyle(int32_t style) = 0;
  /**
    \brief Получить номер условного значка перед номиналом.
    \return Значение свойства: \n
                0 - нет значка, \n
                1 - диаметр, \n
                2 - квадрат, \n
                3 - К - радиус, \n
                4 - М - метрическая резьба, \n
                > 4 - символ из любого шрифта, задаваемого через свойство SignFont.
  */
  virtual int32_t GetSign() = 0;
  /**
    \brief Установить номер условного значка перед номиналом.
    \param[in] sign значение свойства: \n
                0 - нет значка, \n
                1 - диаметр, \n
                2 - квадрат, \n
                3 - К - радиус, \n
                4 - М - метрическая резьба, \n
                > 4 - символ из любого шрифта, задаваемого через свойство SignFont.
  */
  virtual void SetSign(int32_t sign) = 0;
  /// Получить шрифт для условного значка перед номиналом (по умолчанию "Symbol type A").
  virtual std::wstring GetSignFont() = 0;
  /// Установить шрифт для условного значка перед номиналом (по умолчанию "Symbol type A").
  virtual void SetSignFont(const std::wstring & fontName) = 0;
  /// Получить значение размера.
  virtual double GetNominalValue() = 0;
  /// Установить значение размера
  virtual void SetNominalValue(double nominalValue) = 0;
  /// Получить признак автоматического определения номинального значения размера.
  virtual bool IsAutoNominalValue() = 0;
  /// Установить признак автоматического определения номинального значения размера.
  virtual void SetAutoNominalValue(bool autoNominal) = 0;
  /// Получить признак отображения обозначения класса допуска.
  virtual bool IsToleranceOn() = 0;
  /// Установить признак отображения обозначения класса допуска.
  virtual void SetToleranceOn(bool toleranceOn) = 0;
  /// Получить признак включения допуска.
  virtual bool IsHasTolerance() = 0;
  /// Установить признак включения допуска.
  virtual void SetHasTolerance(bool hasToletance) = 0;
  /// Получить признак включения отклонения.
  virtual bool IsDeviationOn() = 0;
  /// Установить признак включения отклонения.
  virtual void SetDeviationOn(bool deviationOn) = 0;
  /// Получить тип отклонений.
  virtual ksDimensionDeviationEnum GetDeviationType() = 0;
  /// Установить тип отклонений.
  virtual void SetDeviationType(ksDimensionDeviationEnum deviationType) = 0;
  /// Получить признак текста в рамке.
  virtual bool IsRectangle() = 0;
  /// Установить признак текста в рамке.
  virtual void SetRectangle(bool textInRectangle) = 0;
  /// Получить признак подчеркнутого текста.
  virtual bool IsUnderLine() = 0;
  /// Установить признак подчеркнутого текста.
  virtual void SetUnderLine(bool underLine) = 0;
  /// Получить признак отображения размера в скобках.
  virtual ksDimensionTextBracketsEnum GetBrackets() = 0;
  /// Установить признак отображения размера в скобках.
  virtual void SetBrackets(ksDimensionTextBracketsEnum inBrackets) = 0;
  /// Получить тип выравнивания текста.
  virtual ksDimensionTextAlignEnum GetTextAlign() = 0;
  /// Установить тип выравнивания текста.
  virtual void SetTextAlign(ksDimensionTextAlignEnum align) = 0;
  /// Получить класс допуска для размера.
  virtual std::wstring GetTolerance() = 0;
  /// Установить класс допуска для размера.
  virtual void SetTolerance(const std::wstring & tolerance) = 0;
  /// Получить формат отображаемого значения размера (для углового размера и углового размера с обрывом).
  virtual ksDimTextFormatEnum GetTextFormat() = 0;
  /// Установить формат отображаемого значения размера (для углового размера и углового размера с обрывом).
  virtual void SetTextFormat(ksDimTextFormatEnum decimalFormat) = 0;
  /// Получить значение верхнего отклонения.
  virtual double GetHighDeviationValue() = 0;
  /// Получить значение нижнего отклонения.
  virtual double GetLowDeviationValue() = 0;
  /// Установить значения отклонений.
  virtual bool InitDeviations(double highDeviationValue, double lowDeviationValue) = 0;
  /// Получить количество знаков после запятой.
  virtual ksAccuracyEnum GetAccuracy() = 0;
  /// Установить количество знаков после запятой.
  virtual void SetAccuracy(ksAccuracyEnum accuracy) = 0;
  /// Получить количество знаков после запятой используемое при округлении размера.
  virtual int32_t GetAccuracyDecimalsCount() = 0;
  /// Получить текст до (префикс) номинального значения.
  virtual ITextLinePtr GetPrefix() = 0;
  /// Получить текст номинального значения.
  virtual ITextLinePtr GetNominalText() = 0;
  /// Получить текст верхнего отклонения.
  virtual ITextLinePtr GetHighDeviation() = 0;
  /// Получить текст нижнего отклонения.
  virtual ITextLinePtr GetLowDeviation() = 0;
  /// Получить текст единиц измерения.
  virtual ITextLinePtr GetUnit() = 0;
  /// Получить текст после (суффикс) номинального значения.
  virtual ITextLinePtr GetSuffix() = 0;
  /// Получить текст под размерной надписью.
  virtual ITextPtr GetTextUnder() = 0;
  /// Получить ширину размерной надписи (в мм).
  virtual double GetWidth() = 0;
  /// Получить высоту размерной надписи (в мм).
  virtual double GetHeight() = 0;
  /// Получить текст, заменяющий знак в размерной надписи.
  virtual ITextLinePtr GetSignText() = 0;
};


