  /// Установить начальное положение относительно базовой точки штриховки по Y.
  virtual void SetLineBeginY(int32_t index, double lineBeginY) = 0;
  /// Получить добавочный угол поворота относительно угла штриховки (в градусах).
  virtual double GetLineAngle(int32_t index) = 0;
  /// Установить добавочный угол поворота относительно угла штриховки (в градусах).
  virtual void SetLineAngle(int32_t index, double lineAngle) = 0;
  /// Получить смещение по направлению линии.
