////////////////////////////////////////////////////////////////////////////////
//
/// Стиль отчета.
/**
*/
////////////////////////////////////////////////////////////////////////////////
struct IReportStyle : IKompasAPIObject
{
  /// Получить количество столбцов.
  virtual int32_t GetColumnsCount() = 0;
  /// Получить интерфейс столбца отчёта по его индексу.
  virtual IReportStyleColumnPtr GetColumn(int32_t index) = 0;
  /// Получить интерфейс столбца отчёта по его уникальному идентификатору.
  virtual IReportStyleColumnPtr GetColumnById(NumericId id) = 0;
  /**
    \brief Создать столбец, и добавить его в коллекцию столбцов отчёта.
    \param[in] indexAt - индекс столбца, перед которым требуется вставить созданный столбец.
    \param[in] name - имя столбца.
    \param[in] property - описание типа свойства столбца.
    \return Интерфейс созданного столбца. 
  */
  virtual IReportStyleColumnPtr AddColumn(int32_t indexAt, const std::wstring & name, const IPropertyPtr & property) = 0;
  /// Поменять местами столбцы с заданными индексами.
  virtual bool SwapColumn(int32_t index1, int32_t index2) = 0;
  /// Удалить столбец по индексу.
  virtual bool DeleteColumn(int32_t index) = 0;
  /// Удалить столбец по уникальному идентификатору.
  virtual bool DeleteColumnById(NumericId id) = 0;
  /// Очистить стиль.
  virtual bool Clear() = 0;
  /// Получить количество строк на странице таблицы.
  virtual int32_t GetRowsCount() = 0;
  /// Установить количество строк на странице таблицы.
  virtual void SetRowsCount(int32_t rowsCount) = 0;
  /// Получить признак разделения таблицы на страницы (true - разделяются, false - не разделяются).
  virtual bool IsDivideIntoPage() = 0;
  /// Установить признак разделения таблицы на страницы (true - разделять, false - не разделять).
  virtual void SetDivideIntoPage(bool divideIntoPage) = 0;
  /// Получить высоту заголовка (в миллиметрах).
  virtual int32_t GetTitleHeight() = 0;
  /// Установить высоту заголовка (в миллиметрах).
  virtual void SetTitleHeight(int32_t titleHeight) = 0;
  /// Получить высоту строки ячейки таблицы (в миллиметрах).
  virtual int32_t GetRowHeight() = 0;
  /// Установить высоту строки ячейки таблицы (в миллиметрах).
  virtual void SetRowHeight(int32_t rowHeight) = 0;
  /// Получить признак отображения пустых строк (true - отображаются, false - не отображаются).
  virtual bool IsShowEmptyRows() = 0;
  /// Установить признак отображения пустых строк (true - отображать, false - не отображать).
  virtual void SetShowEmptyRows(bool showEmptyRows) = 0;
  /// Получить признак отображения заголовка (true - отображается, false - не отображается).
  virtual bool IsShowTitle() = 0;
  /// Установить признак отображения заголовка (true - отображать, false - не отображать).
  virtual void SetShowTitle(bool showTitle) = 0;
  /// Получить тип нумерации строк.
  virtual ksRowsNumberingTypeEnum GetRowsNumberingType() = 0;
  /// Установить тип нумерации строк.
  virtual void SetRowsNumberingType(ksRowsNumberingTypeEnum rowsNumberingType) = 0;
  /// Получить тип нумерации столбцов.
  virtual ksNumberingTypeEnum GetColumnNumberingType() = 0;
  /// Установить тип нумерации столбцов.
  virtual void SetColumnNumberingType(ksNumberingTypeEnum columnNumberingType) = 0;
  /// Получить номер первого столбца.
  virtual int32_t GetColumnNumberingInitVal() = 0;
  /// Установить номер первого столбца.
  virtual void SetColumnNumberingInitVal(int32_t columnNumberingInitVal) = 0;
  /// Получить тип заполнения таблицы (true - сверху вниз, false - снизу вверх).
  virtual bool IsDrawBottom() = 0;
  /// Установить тип заполнения таблицы (true - сверху вниз, false - снизу вверх).
  virtual void SetDrawBottom(bool drawBottom) = 0;
  /// Инициализация стиля параметрами по умолчанию.
  virtual bool Init(ksReportStyleInitEnum reportStyleInitType) = 0;
  /**
    \brief Получить параметры сортировки строк по уровню сортировки.
    \param[in] level - уровень (приоритет) сортировки среди всех столбцов, участвующих в сортировке (0 - наивысшый приоритет).
    \param[out] columnNumber - номер столбца.
    \param[out] sortType - тип сортировки.
    \return Успешность получения параметров сортировки.
  */
  virtual bool GetSortParameters(int32_t level, int32_t & columnNumber, ksSortTypeEnum & sortType) = 0;
  /**
    \brief Установить параметры сортировки строк.
    \param[in] level - уровень (приоритет) сортировки среди всех столбцов, участвующих в сортировке (0 - наивысшый приоритет).
    \param[in] columnNumber - номер столбца.
    \param[in] sortType - тип сортировки.
    \return Успешность получения параметров сортировки.
  */
  virtual bool SetSortParameters(int32_t level, int32_t columnNumber, ksSortTypeEnum sortType) = 0;
  /// Очистить параметры сортировки.
  virtual bool ClearSortParameters() = 0;
  /// Установить имя стиля.
  virtual void SetName(const std::wstring & name) = 0;
  /// Получить имя стиля.
  virtual std::wstring GetName() = 0;
  /// Получить уникальный номер стиля.
  virtual NumericId GetId() = 0;
};

