////////////////////////////////////////////////////////////////////////////////
//
/// Локальная система координат.
/**
  ЛСК создаётся для вида. Положение ЛСК задаётся относительно СК вида.
*/
////////////////////////////////////////////////////////////////////////////////
struct ILocalCoordinateSystem2D : IKompasAPIObject
{
  /// Установить имя ЛСК.
  virtual void SetName(const std::wstring & name) = 0;
  /// Получить имя ЛСК.
  virtual std::wstring GetName() = 0;
  /// Установить координату начальной точки по оси X в СК вида.
  virtual void SetX(double x) = 0;
  /// Получить координату начальной точки по оси X в СК вида.
  virtual double GetX() = 0;
  /// Установить координату начальной точки по оси Y в СК вида.
  virtual void SetY(double y) = 0;
  /// Получить координату начальной точки по оси Y в СК вида.
  virtual double GetY() = 0;
  /// Установить угол наклона оси Х (в градусах) относительно оси X СК вида.
  virtual void SetAngle(double angle) = 0;
  /// Получить угол наклона оси Х (в градусах) относительно оси X СК вида.
  virtual double GetAngle() = 0;
  /// Установить обозначение оси X.
  virtual void SetAxisXLabel(const std::wstring & name) = 0;
  /// Получить обозначение оси X.
  virtual std::wstring GetAxisXLabel() = 0;
  /// Установить обозначение оси Y.
  virtual void SetAxisYLabel(const std::wstring & name) = 0;
  /// Получить обозначение оси Y.
  virtual std::wstring GetAxisYLabel() = 0;
  /// Удалить ЛСК.
  virtual bool Delete() = 0;
  /**
    \brief Преобразовать координаты точки из СК вида в ЛСК.
    \param[in] x, y - координаты точки в СК вида.
    \param[out] xn, yn - координаты точки ЛСК.
    \return Успешность преобразования.
  */
  virtual bool TransformPointIntoView(double x, double y, double & xn, double & yn) = 0;
  /**
    \brief Преобразовать координаты точки из ЛСК в СК вида.
    \param[in] x, y - координаты точки в ЛСК.
    \param[out] xn, yn - координаты точки СК вида.
    \return Успешность преобразования.
  */
  virtual bool TransformPointFromView(double x, double y, double & xn, double & yn) = 0;
  /**
    \brief Преобразовать угол из CK вида в ЛCK.
    \param[in, out] angle - угол, преобразуемый из СК вида в ЛСК (в градусах).
    \return Успешность преобразования.
  */
  virtual bool TransformAngleIntoView(double & angle) = 0;
  /**
    \brief Преобразовать угол из ЛCK в CK вида.
    \param[in, out] angle - угол, преобразуемый из ЛСК в СК вида (в градусах).
    \return Успешность преобразования.
  */
  virtual bool TransformAngleFromView(double & angle) = 0;
};

