////////////////////////////////////////////////////////////////////////////////
//
/// Скругление.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IFillet : IModelObject
{
  /// Получить способ построения скругления.
  virtual ksFilletBuildingTypeEnum GetBuildingType() = 0;
  /// Установить способ построения скругления.
  virtual void SetBuildingType(ksFilletBuildingTypeEnum buildingType) = 0;
  /// Получить массив скругляемых объектов (граней и ребер).
  virtual std::vector<IModelObjectPtr> GetBaseObjects() = 0;
  /// Установить массив скругляемых объектов (граней и ребер).
  virtual void SetBaseObjects(const std::vector<IModelObjectPtr> & objects) = 0;
  /// Получить радиус скругления или полуось 1 (для круглого, эллиптического или с коэффициентом профиля).
  virtual double GetRadius1() = 0;
  /// Установить радиус скругления или полуось 1 (для круглого, эллиптического или с коэффициентом профиля).
  virtual void SetRadius1(double radius1) = 0;
  /// Получить полуось 2 (для эллиптического профиля).
  virtual double GetRadius2() = 0;
  /// Установить полуось 2 (для эллиптического профиля).
  virtual void SetRadius2(double radius2) = 0;
  /**
    \brief Получить коэффициент (для профиля коническая кривая с коэффициентом).
    \details Коэффициент k (инженерный дискриминант) — это отношение части медианы треугольника, расположенной под конической кривой, к полной длине медианы. \n
                Значение k находится в пределах 0,0001 — 0,9999 и определяет форму кривой: \n
                   k < 0,5 — часть эллипса, \n
                   k = 0,5 — часть параболы, \n
                   k > 0,5 — часть гиперболы.
    \return Коэффициент (инженерный дискриминант).
  */
  virtual double GetCoefficient() = 0;
  /**
    \brief Установить коэффициент (для профиля коническая кривая с коэффициентом).
    \details Коэффициент k (инженерный дискриминант) — это отношение части медианы треугольника, расположенной под конической кривой, к полной длине медианы. \n
                Значение k находится в пределах 0,0001 — 0,9999 и определяет форму кривой: \n
                   k < 0,5 — часть эллипса, \n
                   k = 0,5 — часть параболы, \n
                   k > 0,5 — часть гиперболы.
    \param[in] coefficient - коэффициент (инженерный дискриминант).
  */
  virtual void SetCoefficient(double coefficient) = 0;
  /// Получить длину хорды (для профиля с постоянной хордой).
  virtual double GetChord() = 0;
  /// Установить длину хорды (для профиля с постоянной хордой).
  virtual void SetChord(double chord) = 0;
  /// Установить признак "по касательным ребрам".
  virtual void SetTangent(bool tangent) = 0;
  /// Получить признак "по касательным ребрам".
  virtual bool IsTangent() = 0;
  /// Получить признак сглаживания углов.
  virtual bool IsSmoothCorner() = 0;
  /// Установить признак сглаживания углов.
  virtual void SetSmoothCorner(bool smoothCorner) = 0;
  /// Получить признак обхода углов с гладкой стыковкой (false - обход без гладкой стыковки, true - обход с гладкой стыковкой).
  virtual bool IsRoundCorners() = 0;
  /// Установить признак обхода углов с гладкой стыковкой (false - обход без гладкой стыковки, true - обход с гладкой стыковкой).
  virtual void SetRoundCorners(bool roundCorner) = 0;
  /// Установить признак автоопределение сохранения кромки.
  virtual void SetAutoSaveEdge(bool autoSaveEdge) = 0;
  /// Получить признак автоопределение сохранения кромки.
  virtual bool IsAutoSaveEdge() = 0;
  /// Установить признак сохранения кромки (сохранение кромки на всех ребрах соседних граней).
  virtual void SetSaveEdge(bool saveEdge) = 0;
  /// Получить признак сохранения кромки (сохранение кромки на всех ребрах соседних граней).
  virtual bool IsSaveEdge() = 0;
  /// Установить признак использования точки останова скругления.
  virtual void SetStopFilletOn(bool first, bool stopFilletOn) = 0;
  /// Получить признак использования точки останова скругления.
  virtual bool IsStopFilletOn(bool first) = 0;
  /// Установить способ расчета смещения для точки останова скругления.
  virtual void SetStopFilletOffsetMode(bool first, ksFilletOffsetModeEnum mode) = 0;
  /// Получить способ расчета смещения для точки останова скругления.
  virtual ksFilletOffsetModeEnum GetStopFilletOffsetMode(bool first) = 0;
  /// Установить величину смещения для точки останова скругления (если угол , т.е. OffsetMode = ksFilletOffsetByAngle, то в радианах).
  virtual void SetStopFilletOffset(bool first, double stopFilletOffset) = 0;
  /// Получить величину смещения для точки останова скругления (если угол , т.е. OffsetMode = ksFilletOffsetByAngle, то в радианах).
  virtual double GetStopFilletOffset(bool first) = 0;
  /// Установить секущий объект для точки останова скругления.
  virtual void SetStopFilletCutObject(bool first, const IModelObjectPtr & object) = 0;
  /// Получить секущий объект для точки останова скругления.
  virtual IModelObjectPtr GetStopFilletCutObject(bool first) = 0;
  /// Установить признак усечения по объекту (при секущей) для точки останова скругления.
  virtual void SetStopFilletCutByObject(bool first, bool stopFilletCutByObject) = 0;
  /// Получить признак усечения по объекту (при секущей) для точки останова скругления.
  virtual bool IsStopFilletCutByObject(bool first) = 0;
  /// Установить индекс точки пересечения с секущим объектом для точки останова скругления.
  virtual void SetStopFilletCutPointIndex(bool first, int32_t index) = 0;
  /// Получить индекс точки пересечения с секущим объектом для точки останова скругления.
  virtual int32_t GetStopFilletCutPointIndex(bool first) = 0;
  /// Установить направление усечения в точке останова (false - направление от начальной точки до конечной).
  virtual void SetStopFilletDirection(bool direction) = 0;
  /// Получить направление усечения в точке останова (false - направление от начальной точки до конечной).
  virtual bool GetStopFilletDirection() = 0;
  /// Установить признак работы настройки переменных радиусов скругления.
  virtual void SetVariableRadiusOn(bool variableRadiusOn) = 0;
  /// Получить признак работы настройки переменных радиусов скругления.
  virtual bool IsVariableRadiusOn() = 0;
  /// Получить количество вершин в настройках переменных радиусов скруглений.
  virtual int32_t GetVariableRadiusCount() = 0;
  /**
    \brief Добавить настройку переменного радиуса для ребра в точке, заданной смещением.
    \param[in] point - фиксирующий объект.
    \param[in] radius - радиус скругления.
    \param[in] position - положение на кривой.
    \param[in] positionType - способ определения положения на кривой (true - задано величиной, false - в процентах от длины кривой).
    \return Успешность добавления.
  */
  virtual bool AddVariableRadius(const IModelObjectPtr & point, double radius, double position, bool positionType) = 0;
  /// Очистить список настроек переменных радиусов скруглений.
  virtual bool VariableRadiusClear() = 0;
  /// Удалить настройку переменного радиуса скруглений по индексу.
  virtual bool VariableRadiusDelete(int32_t index) = 0;
  /// Установить значение переменного радиуса в точке по индексу.
  virtual void SetVariableRadius(int32_t index, double radius) = 0;
  /// Получить значение переменного радиуса в точке по индексу.
  virtual double GetVariableRadius(int32_t index) = 0;
  /// Установить величину смещения точки настройки переменного радиуса в процентах по индексу.
  virtual void SetVariableRadiusPosition(int32_t index, double position) = 0;
  /// Получить величину смещения точки настройки переменного радиуса в процентах по индексу.
  virtual double GetVariableRadiusPosition(int32_t index) = 0;
  /// Установить величину смещения точки настройки переменного радиуса в мм по индексу.
  virtual void SetVariableRadiusPositionLength(int32_t index, double length) = 0;
  /// Получить величину смещения точки настройки переменного радиуса в мм по индексу.
  virtual double GetVariableRadiusPositionLength(int32_t index) = 0;
  /**
    \brief Получить ребро, для которого задана настройка переменного радиуса по индексу.
    \param[in] index - индекс параметров скругления, для которого задана настройка переменного радиуса.
    \return Ребро.
  */
  virtual IEdgePtr GetVariableRadiusEdge(int32_t index) = 0;
  /// Установить способ построения при скруглении с переменным радиусом.
  virtual void SetVariableRadiusBuildingType(ksVariableRadiusBuildingTypeEnum buildingType) = 0;
  /// Получить способ построения при скруглении с переменным радиусом.
  virtual ksVariableRadiusBuildingTypeEnum GetVariableRadiusBuildingType() = 0;
  /// Установить граничную кривую.
  virtual void SetVariableRadiusCurve(const std::vector<IModelObjectPtr> & curve) = 0;
  /// Получить граничную кривую.
  virtual std::vector<IModelObjectPtr> GetVariableRadiusCurve() = 0;
};

