////////////////////////////////////////////////////////////////////////////////
//
/// Сплайн.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISpline3D : IModelObject
{
  /// Установить признак замкнутости.
  virtual void SetClosed(bool closed) = 0;
  /// Получить признак замкнутости.
  virtual bool IsClosed() = 0;
  /// Установить тип построения (true - сплайн по точкам, false - полюсам).
  virtual void SetSplineOnPoles(bool splineOnPoles) = 0;
  /// Получить тип построения (true - сплайн по точкам, false - полюсам).
  virtual bool IsSplineOnPoles() = 0;
  /// Установить порядок сплайна (значение порядка должно принадлежать диапазону 2...10).
  virtual void SetSplineOrder(int32_t splineOrder) = 0;
  /// Получить порядок сплайна.
  virtual int32_t GetSplineOrder() = 0;
  /// Получить количество вершин.
  virtual int32_t GetVertexCount() = 0;
  /// Получить параметры вершины по индексу.
  virtual ICurveVertexParamPtr GetVertexParams(int32_t index) = 0;
  /**
    \brief Создать новую вершину перед указанной вершиной и получить её параметры.
    \param[in] index - индекс существующей вершины перед которой добавляется новая (index <0 - добавить в конец).
    \return Параметры вершины.
  */
  virtual ICurveVertexParamPtr AddVertex(int32_t index) = 0;
  /// Удалить вершину с указанным индексом.
  virtual bool DeleteVertex(int32_t index) = 0;
  /// Очистить массив вершин.
  virtual bool Flush() = 0;
  /**
    \brief Прочитать параметры вершин из текстового файла.
    \details Формат файла - строки вида "x y z weight", где x, y, z - координты вершины сплайна, weight - вес, разделённые символом " " (пробел).
    \param[in] fileName - путь к файлу с параметрами вершин.
    \return Успешность чтения файла.
  */
  virtual bool ReadFromFile(const std::wstring & fileName) = 0;
  /**
    \brief Записать параметры вершин в текстового файла.
    \param[in] fileName - путь к файлу с параметрами вершин.
    \return Успешность записи в файл.
  */
  virtual bool WriteToFile(const std::wstring & fileName) = 0;
  /// Получить массив параметров вершин.
  virtual std::vector<ICurveVertexParamPtr> GetVertexParamsArray() = 0;
  /**
    \brief Получить массивы координат и весов вершин.
    \details Массивы являются согласованными.
    \param[out] coordinates - массив координат вершин вида "x0, y0, z0, x1, y1, z1 ... xi, yi, zi".
    \param[out] weights - массив весов вершин вида "weight0, weight1, ... weighti" (Для сплайна по точкам: 0, 0, 0 ... 0).
    \return Успешность получения.
  */
  virtual bool GetVertexCoordinatesArray(std::vector<double> & coordinates, std::vector<double> & weights) = 0;
  /// Установить массив узлов кривой NURBS.
  virtual void SetKnots(const std::vector<double> & knots) = 0;
  /// Получить массив узлов кривой NURBS.
  virtual std::vector<double> GetKnots() = 0;
  /// Установить способ создания сопряжения в заданной по индексу вершине.
  virtual void SetSplineTransitionType(int32_t pointIndex, ksSplineTransitionTypeEnum splineTransitionType) = 0;
  /// Получить создания сопряжения в заданной по индексу вершине.
  virtual ksSplineTransitionTypeEnum GetSplineTransitionType(int32_t pointIndex) = 0;
  /// Установить объект сопряжения в заданной по индексу вершине.
  virtual void SetConstraintObject(int32_t pointIndex, const IModelObjectPtr & constraintObject) = 0;
  /// Получить объект сопряжения в заданной по индексу вершине.
  virtual IModelObjectPtr GetConstraintObject(int32_t pointIndex) = 0;
  /// Установить объект, задающий границу в указанной по индексу вершине.
  virtual void SetConstraintLimitObject(int32_t pointIndex, const IModelObjectPtr & constraintLimitObject) = 0;
  /// Получить объект, задающий границу в указанной по индексу вершине.
  virtual IModelObjectPtr GetConstraintLimitObject(int32_t pointIndex) = 0;
  /// Установить тип сопряжения в указанной по индексу вершине.
  virtual void SetConstraintType(int32_t pointIndex, ksNurbsByPointsPointConstraintsEnum constraintType) = 0;
  /// Получить тип сопряжения в указанной по индексу вершине.
  virtual ksNurbsByPointsPointConstraintsEnum GetConstraintType(int32_t pointIndex) = 0;
  /// Противоположное направление.
  virtual void SetConstraintReverse(int32_t pointIndex, bool constraintReverse) = 0;
  /// Установить признак противоположного направления в указанной по индексу вершине.
  virtual bool IsConstraintReverse(int32_t pointIndex) = 0;
  /// Получить признак противоположного направления в указанной по индексу вершине.
  virtual void SetTangentVectorLenght(int32_t pointIndex, double tangentVectorLenght) = 0;
  /// Получить длину касательного вектора в указанной по индексу вершине.
  virtual double GetTangentVectorLenght(int32_t pointIndex) = 0;
  /// Установить радиус кривизны в указанной по индексу вершине.
  virtual void SetCurvatureRadius(int32_t pointIndex, double curvatureRadius) = 0;
  /// Получить радиус кривизны в указанной по индексу вершине.
  virtual double GetCurvatureRadius(int32_t pointIndex) = 0;
  /// Установить величину кривизны в указанной по индексу вершине.
  virtual void SetCurvature(int32_t pointIndex, double curvature) = 0;
  /// Получить величину кривизны в указанной по индексу вершине.
  virtual double GetCurvature(int32_t pointIndex) = 0;
  /**
    \brief Получить координаты направления касательного вектора (в сопряжении).
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \param[out] x, y, z - координаты направления вектора.
    \return Успешность получения.
  */
  virtual bool GetVector(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex, double & x, double & y, double & z) = 0;
  /**
    \brief Установить координаты направления касательного вектора (в сопряжении).
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \param[in] x, y, z - координаты направления вектора.
    \return Успешность установки координат.
  */
  virtual bool SetVector(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex, double x, double y, double z) = 0;
  /**
    \brief Сменить направление касательного вектора на обратное.
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \return Успешность смены направления.
  */
  virtual bool InvertVector(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex) = 0;
  /**
    \brief Установить направляющий объект вектора в точке сопряжения.
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \param[in] vectorDirectionObject - направляющий объект.
  */
  virtual void SetVectorDirectionObject(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex,
                                        const IModelObjectPtr & vectorDirectionObject) = 0;
  /**
    \brief Получить направляющий объект вектора в точке сопряжения.
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \return Направляющий объект.
  */
  virtual IModelObjectPtr GetVectorDirectionObject(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex) = 0;
  /**
    \brief Установить направление вектора в точке сопряжения.
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \param[in] vectorOrientation - направление вектора.
  */
  virtual void SetVectorOrientation(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex, bool vectorOrientation) = 0;
  /**
    \brief Получить направление вектора в точке сопряжения.
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \return Направление вектора.
  */
  virtual bool GetVectorOrientation(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex) = 0;
  /**
    \brief Получить вектор в точке сопряжения.
    \param[in] pointIndex - индекс вершины.
    \param[in] vectorIndex - cпособ создания сопряжения в заданной вершине сплайна.
    \return Вектор.
  */
  virtual IVector3DPtr GetDirectionVector(int32_t pointIndex, ksTransitionVectorIndexEnum vectorIndex) = 0;
  /**
    \brief Получить координаты центра кривизны вектора в указанной точке.
    \param[in] pointIndex - индекс вершины.
    \param[out] x, y, z - координаты центра кривизны.
    \return Успешность получения координат.
  */
  virtual bool GetCenterPoint(int32_t pointIndex, double & x, double & y, double & z) = 0;
  /**
    \brief Установить координаты центра кривизны вектора в указанной точке.
    \param[in] pointIndex - индекс вершины.
    \param[in] x, y, z - координаты центра кривизны.
    \return Успешность установки координат.
  */
  virtual bool SetCenterPoint(int32_t pointIndex, double x, double y, double z) = 0;
  /**
    \brief Получить параметры точки центра кривизны.
    \details: В зависимости от типа ISpline3D::CenterPointType, получаемый интерфейс приводится к одному из вариантов:
      - ksPDisplace: IPoint3DParamDisplace (параметры пространственной точки, заданной по смещению от опорного объекта),
      - ksPIntersect: IPoint3DParamIntersect (параметры параметров пространственной точки, заданной на пересечении опорных объектов),
      - ksPCenter: IPoint3DParamCenter (параметры параметров пространственной точки, заданной в центре опорного объекта),
      - ksPCurve: IPoint3DParamCurve (параметры пространственной точки, заданной на кривой со смещением),
      - ksPSurface: IPoint3DparamSurface (параметры пространственной точки, заданной на поверхности),
      - ksPProjection: IPoint3DParamProjection (параметры пространственной точки, заданной проецированием).
    \param[in] pointIndex - индекс вершины.
  */
  virtual IKompasAPIObjectPtr GetCenterPointParams(int32_t pointIndex) = 0;
  /**
    \brief Установить способ построения точки центра кривизны.
    \param[in] pointIndex - индекс вершины.
    \param[in] centerPointType - способ построения точки центра кривизны.
  */
  virtual void SetCenterPointType(int32_t pointIndex, ksPoint3DTypeEnum centerPointType) = 0;
  /// Получить способ построения точки центра кривизны в указанной по индексу вершине.
  virtual ksPoint3DTypeEnum GetCenterPointType(int32_t pointIndex) = 0;
  /**
    \brief Установить опорный объект точки центра кривизны.
    \param[in] pointIndex - индекс вершины.
    \param[in] centerPointAssociationObject - опорный объект.
  */
  virtual void SetCenterPointAssociationObject(int32_t pointIndex, const IModelObjectPtr & centerPointAssociationObject) = 0;
  /// Получить опорный объект точки центра кривизны в указанной по индексу вершине.
  virtual IModelObjectPtr GetCenterPointAssociationObject(int32_t pointIndex) = 0;
  /// Удалить параметры центра кривизны в указанной по индексу вершине.
  virtual bool DeleteCenterPointParams(int32_t pointIndex) = 0;
  /// Удалить параметры управления во всех точках.
  virtual bool ClearTangentParameters() = 0;
  /// Получить способ построения.
  virtual ksSplineBuildingTypeEnum GetBuildingType() = 0;
  /// Установить способ построения.
  virtual void SetBuildingType(ksSplineBuildingTypeEnum buildingType) = 0;
};

