  virtual bool GetEdgesCheck(int32_t contourIndex) = 0;
  /**
    \brief Установить признак выбора контура.
    \param[in] contourIndex - индекс массива рёбер.
    \param[in] check - признак выбора контура.
  */
  virtual void SetEdgesCheck(int32_t contourIndex, bool check) = 0;

  /// Получить количество доступных для создания контуров.
