////////////////////////////////////////////////////////////////////////////////
//
/// Математическая кривая в трехмерном пространстве.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IMathCurve3D : IKompasAPIObject
{
  /// Получить точку на кривой.
  virtual bool GetPoint(double t, double & x, double & y, double & z) = 0;
  /// Получить тангенциальный вектор (нормализованный).
  virtual bool GetTangentVector(double t, double & x, double & y, double & z) = 0;
  /// Получить нормаль.
  virtual bool GetNormal(double t, double & x, double & y, double & z) = 0;
  /// Получить первую производную по t.
  virtual bool GetDerivativeT(double t, double & x, double & y, double & z) = 0;
  /// Получить вторую производную по t.
  virtual bool GetDerivativeTT(double t, double & x, double & y, double & z) = 0;
  /// Получить третью производную по t.
  virtual bool GetDerivativeTTT(double t, double & x, double & y, double & z) = 0;
  /// Получить начальное значение параметра.
  virtual double GetParamMin() = 0;
  /// Получить конечное значение параметра.
  virtual double GetParamMax() = 0;
  /// Получить признак замкнутости кривой.
  virtual bool IsClosed() = 0;
  /// Получить признак периодичности замкнутой кривой.
  virtual bool IsPeriodic() = 0;
  /// Получить метрическую длину кривой.
  virtual double GetMetricLength(double startT, double endT) = 0;
  /// Получить габарит кривой.
  virtual bool GetGabarit(double & x1, double & y1, double & z1, double & x2, double & y2, double & z2) = 0;
  /// Получить признак вырожденности кривой.
  virtual bool IsDegenerate() = 0;
  /// Получить тип кривой.
  virtual ksMathCurve3DTypeEnum GetCurveType() = 0;
  /// Получить длину кривой в соответствующих единицах измерения.
  virtual double GetLength(ksLengthUnitsEnum units) = 0;
  /**
    \brief Получить ближайшую проекцию точки на кривую.
    \param[in] x, y, z - координаты исходной пространственной точки.
    \param[in, out] t - параметрические координаты точки на кривой (на входе - начальное приближение, на выходе - ближайшей проекции).
    \param[in] extended - искать ли проекцию на продолжении кривой (true - искать на продолжении, false - найти ближайшую граничную точку).
    \return Успешность выполнения операции.
  */
  virtual bool NearPointProjection(double x, double y, double z, double & t, bool extended) = 0;
  /// Получить полигон точек на кривой.
  virtual std::vector<float> CalculatePolygon(double sag) = 0;
  /// Получить центр кривой.
  virtual bool GetCentre(double & x, double & y, double & z) = 0;
  /// Получить центр тяжести кривой.
  virtual bool GetWeightCentre(double & x, double & y, double & z) = 0;
  /// Получить радиус кривой.
  virtual double GetRadius() = 0;
  /// Получить признак, является ли кривая плоской.
  virtual bool IsPlanar() = 0;
  /// Получить признак, является ли кривая прямолинейной.
  virtual bool IsStraight() = 0;
  /// Получить признак, является ли кривая линией.
  virtual bool IsLineSeg() = 0;
  /// Получить признак, является ли кривая дугой окружности.
  virtual bool IsArc() = 0;
  /// Получить признак, является ли кривая окружностью.
  virtual bool IsCircle() = 0;
  /// Получить признак, является ли кривая эллипсом.
  virtual bool IsEllipse() = 0;
  /// Получить признак, является ли кривая NURBS.
  virtual bool IsNurbs() = 0;
  /// Получить признак, является ли кривая дугой эллипса.
  virtual bool IsEllipseArc() = 0;
  /**
    \brief Получить параметры NURBS-представления кривой.
    \param[in] closed - признак того, что запрашивается замкнутое представление.
    \param[out] degree - порядок сплайна (степень + 1).
    \param[out] tMin, tMax - минимальное и максимальное значение параметра кривой.
    \param[out] points - массив координат вершин.
    \param[out] weights - массив весов точек.
    \param[out] knots - массив узлов сплайна.
    \return Успешность выполнения операции.
  */
  virtual bool GetNurbs3DParams(bool closed, int32_t & degree, double & tMin, double & tMax, std::vector<double> & points,
                                std::vector<double> & weights, std::vector<double> & knots) = 0;
  /// Получить локальную систему координат (положение объекта).
  virtual IPlacement3DPtr GetPlacement() = 0;
  /// Получить параметры эллипса (угол в градусах).
  virtual bool GetEllipseParam(double & majorRadius, double & minorRadius, double & angle) = 0;
  /// Получить тип базовой 2D кривой.
  virtual ksMathCurve2DTypeEnum GetBaseCurve2DType() = 0;
  /// Получить тип базовой 3D кривой.
  virtual ksMathCurve3DTypeEnum GetBaseCurveType() = 0;
  /// Получить расстояние до точки.
  virtual double GetDistanceToPoint(double x, double y, double z) = 0;
};

