////////////////////////////////////////////////////////////////////////////////
//
/// NURBS-поверхность.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct INurbsSurface : IModelObject
{
  /**
    \brief Получить параметры NURBS-поверхности.
    \param[in] closedV - признак получение параметров для замкнутого по V представления (true - замкнутый, false - разомкнутый).
    \param[in] closedU - признак получение параметров для замкнутого по U представления (true - замкнутый, false - разомкнутый).
    \param[out] degreeV - порядок сплайна (степень + 1) по V (от 2 до 10).
    \param[out] degreeU - порядок сплайна (степень + 1) по U (от 2 до 10).
    \param[out] pointsVCount - количество точек по V.
    \param[out] pointsUCount - количество точек по U.
    \param[out] points - массив координат 3D точек.
    \param[out] weights - массив весов.
    \param[out] knotsV - массив узлов сплайна по V.
    \param[out] knotsU - массив узлов сплайна по U.
    \return Успешность операции.
  */
  virtual bool GetNurbsParams(bool closedV, bool closedU, int32_t & degreeV, int32_t & degreeU, int32_t & pointsVCount,
                              int32_t & pointsUCount, std::vector<double> & points, std::vector<double> & weights,
                              std::vector<double> & knotsV, std::vector<double> & knotsU) = 0;
  /**
    \brief Установить параметры NURBS-поверхности.
    \param[in] closedV - признак замкнутого по V представления (true - замкнутый, false - разомкнутый).
    \param[in] closedU - признак замкнутого по U представления (true - замкнутый, false - разомкнутый).
    \param[in] degreeV - порядок сплайна (степень + 1) по V (от 2 до 10).
    \param[in] degreeU - порядок сплайна (степень + 1) по U (от 2 до 10).
    \param[in] pointsVCount - количество точек по V.
    \param[in] pointsUCount - количество точек по U.
    \param[in] points - массив координат 3D точек.
    \param[in] weights - массив весов.
    \param[in] knotsV - массив узлов сплайна по V.
    \param[in] knotsU - массив узлов сплайна по U.
    \return Успешность операции.
  */
  virtual bool SetNurbsParams(bool closedV, bool closedU, int32_t degreeV, int32_t degreeU, int32_t pointsVCount,
                              int32_t pointsUCount, const std::vector<double> & points, const std::vector<double> & weights,
                              const std::vector<double> & knotsV, const std::vector<double> & knotsU) = 0;
  /// Инициализировать параметры NURBS-поверхности по грани.
  virtual bool InitParamByFace(const IModelObjectPtr & face) = 0;
  /// Получить признак замкнутости поверхности по U.
  virtual bool IsClosedU() = 0;
  /// Установить признак замкнутости поверхности по U.
  virtual void SetClosedU(bool closedU) = 0;
  /// Получить признак замкнутости поверхности по V.
  virtual bool IsClosedV() = 0;
  /// Установить признак замкнутости поверхности по V.
  virtual void SetClosedV(bool closedV) = 0;
  /// Получить количество циклов (границ).
  virtual int32_t GetBoundaryCount() = 0;
  /**
    \brief Добавить границу для NURBS-поверхности.
    \param[in] uv - признак использования UV координат (true - параметры кривой заданы в UV координатах поверхности, false - параметры заданы 3D координатами).
    \param[in] closed - признак замкнутого представления (true - замкнутый, false - разомкнутый).
    \param[in] degree - порядок сплайна (степень + 1) (от 2 до 10).
    \param[in] points - массив координат точек.
    \param[in] weights - массив весов точек.
    \param[in] knots - массив узлов сплайна.
    \param[in] tMin, tMax - минимальное и максимальное значение параметра.
    \return Успешность операции.
  */
  virtual bool AddBoundary(bool uv, bool closed, int32_t degree, const std::vector<double> & points,
                           const std::vector<double> & weights, const std::vector<double> & knots, double tMin, double tMax) = 0;
  /**
    \brief Получить параметры NURBS-представления границы.
    \param[in] uv - признак получения UV координат (true - параметры представления в UV координатах поверхности, false - параметры заданы 3D координатами).
    \param[in] closed - признак замкнутого представления (true - замкнутый, false - разомкнутый).
    \param[in] boundaryIndex - индекс границы.
    \param[out] degree - порядок сплайна (степень + 1) (от 2 до 10).
    \param[out] points - массив координат точек.
    \param[out] weights - массив весов точек.
    \param[out] knots - массив узлов сплайна.
    \param[out] tMin, tMax - минимальное и максимальное значение параметра.
    \return Успешность операции.
  */
  virtual bool GetBoundary(bool uv, bool closed, int32_t boundaryIndex, int32_t & degree, std::vector<double> & points,
                           std::vector<double> & weights, std::vector<double> & knots, double & tMin, double & tMax) = 0;
  /// Удалить границу.
  virtual bool DeleteBoundary(int32_t boundaryIndex) = 0;
};

