////////////////////////////////////////////////////////////////////////////////
//
/// Поверхность по сети точек.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IMeshPointsSurface : IModelObject
{
  /// Получить тип поверхности по сети точек.
  virtual ksMeshPointsSurfaceBuildingTypeEnum GetBuildingType() = 0;
  /// Установить тип поверхности по сети точек.
  virtual void SetBuildingType(ksMeshPointsSurfaceBuildingTypeEnum buildingType) = 0;
  /**
    \brief Получить параметры поверхности.
    \param[out] closedV - признак замкнутости по V (true - замкнутый, false - разомкнутый).
    \param[out] closedU - признак замкнутости по U (true - замкнутый, false - разомкнутый).
    \param[out] degreeV - порядок сплайна (степень + 1) по V (от 2 до 10).
    \param[out] degreeU - порядок сплайна (степень + 1) по U (от 2 до 10).
    \param[out] pointVCount - количество точек по V.
    \param[out] pointUCount - количество точек по U.
    \param[out] points - массив координат точек.
    \param[out] weights - массив весов точек.
    \return Успешность операции.
  */
  virtual bool GetParams(bool & closedV, bool & closedU, int32_t & degreeV, int32_t & degreeU, int32_t & pointVCount,
                         int32_t & pointsUCount, std::vector<double> & points, std::vector<double> & weights) = 0;
  /**
    \brief Установить параметры поверхности.
    \param[in] closedV - признак замкнутости по V (true - замкнутый, false - разомкнутый).
    \param[in] closedU - признак замкнутости по U (true - замкнутый, false - разомкнутый).
    \param[in] degreeV - порядок сплайна (степень + 1) по V (от 2 до 10).
    \param[in] degreeU - порядок сплайна (степень + 1) по U (от 2 до 10).
    \param[in] pointVCount - количество точек по V.
    \param[in] pointUCount - количество точек по U.
    \param[in] points - массив координат точек.
    \param[in] weights - массив весов точек.
    \return Успешность операции.
  */
  virtual bool SetParams(bool closedV, bool closedU, int32_t degreeV, int32_t degreeU, int32_t pointVCount, int32_t pointsUCount,
                         const std::vector<double> & points, const std::vector<double> & weights) = 0;
  /// Создать поверхность по объекту.
  virtual bool InitParamByFace(const IModelObjectPtr & face) = 0;
  /// Получить признак замкнутости поверхности по направлению U.
  virtual bool IsClosedU() = 0;
  /// Установить признак замкнутости поверхности по направлению U.
  virtual void SetClosedU(bool closedU) = 0;
  /// Получить признак замкнутости поверхности по направлению V.
  virtual bool IsClosedV() = 0;
  /// Установить признак замкнутости поверхности по направлению V.
  virtual void SetClosedV(bool closedV) = 0;
  /// Получить порядок (степень + 1) сплайна по направлению U.
  virtual int32_t GetDegreeU() = 0;
  /// Установить порядок (степень + 1) сплайна по направлению U.
  virtual void SetDegreeU(int32_t degreeU) = 0;
  /// Получить порядок (степень + 1) сплайна по направлению V.
  virtual int32_t GetDegreeV() = 0;
  /// Установить порядок (степень + 1) сплайна по направлению V.
  virtual void SetDegreeV(int32_t degreeV) = 0;
  /**
    \brief Начать добавление нового ряда точек.
    \param[in] addNewRow - ряд или колонка (true - добавлять ряд, false - добавлять колонку).
    \param[in] indexAt - индекс ряда, перед которым добавлять новый ряд.
    \return Успешность выполнения операции.
  */
  virtual bool BeginPointsSeries(bool addNewRow, int32_t indexAt) = 0;
  /// Добавить точку в создаваемый ряд точек.
  virtual IKompasAPIObjectPtr AddPoint(double x, double y, double z, double weight, ksPoint3DTypeEnum pointType,
                                       const IModelObjectPtr & associationObject) = 0;
  /// Завершить создание ряда точек.
  virtual bool EndPointsSeries() = 0;
  /**
    \brief Добавить ряд точек.
    \param[in] addNewRow - ряд или колонка (true - добавлять ряд, false - добавлять колонку).
    \param[in] indexAt - индекс ряда, перед которым добавлять новый ряд.
    \param[in] points - массив координат точек.
    \param[in] weights - массив весов точек.
    \return Успешность выполнения операции.
  */
  virtual bool AddPointsSeries(bool addNewRow, int32_t indexAt, const std::vector<double> & points,
                               const std::vector<double> & weights) = 0;
  /// Удалить ряд точек.
  virtual bool DeletePointsSeries(bool deleteRow, int32_t index) = 0;
  /// Удалить все точки поверхности.
  virtual bool ClearPointsSeries() = 0;
  /// Получить количество рядов по направлению V.
  virtual int32_t GetRowsCount() = 0;
  /// Получить количество точек в одном ряду по направлению U.
  virtual int32_t GetColumnsCount() = 0;
  /// Установить тип параметров построения точки поверхности.
  virtual void SetPointType(int32_t row, int32_t column, ksPoint3DTypeEnum pointType) = 0;
  /// Получить тип параметров построения точки поверхности.
  virtual ksPoint3DTypeEnum GetPointType(int32_t row, int32_t column) = 0;
  /// Получить параметры точки поверхности.
  virtual IKompasAPIObjectPtr GetPointParameters(int32_t row, int32_t column) = 0;
  /// Получить параметры точки.
  virtual bool GetPoint(int32_t row, int32_t column, double & x, double & y, double & z, double & weight) = 0;
  /// Установить параметры точки поверхности.
  virtual bool SetPoint(int32_t row, int32_t column, double x, double y, double z, double weight) = 0;
  /// Получить признак проверки самопересечений.
  virtual bool IsCheckSelfIntersection() = 0;
  /// Установить признак проверки самопересечений.
  virtual void SetCheckSelfIntersection(bool checkSelfIntersection) = 0;
  /// Установить опорный объект для вершины.
  virtual void SetAssociationObject(int32_t row, int32_t column, const IModelObjectPtr & associationObject) = 0;
  /// Получить опорный объект для вершины.
  virtual IModelObjectPtr GetAssociationObject(int32_t row, int32_t column) = 0;
};

