////////////////////////////////////////////////////////////////////////////////
//
/// Поверхность соединения.
/**
*/
////////////////////////////////////////////////////////////////////////////////
struct IJointSurface : IModelObject
{
  /// Установить кривую границы первой сопрягаемой поверхности (массив рёбер).
  virtual void SetCurves1(const std::vector<IModelObjectPtr> & curves) = 0;
  /// Получить кривую границы первой сопрягаемой поверхности (массив рёбер).
  virtual std::vector<IModelObjectPtr> GetCurves1() = 0;
  /// Установить кривую границы второй сопрягаемой поверхности (массив рёбер).
  virtual void SetCurves2(const std::vector<IModelObjectPtr> & curves) = 0;
  /// Получить кривую границы второй сопрягаемой поверхности (массив рёбер).
  virtual std::vector<IModelObjectPtr> GetCurves2() = 0;
  /// Установить первую сопрягаемую поверхность.
  virtual void SetFace1(const IModelObjectPtr & face) = 0;
  /// Получить первую сопрягаемую поверхность.
  virtual IModelObjectPtr GetFace1() = 0;
  /// Установить вторую сопрягаемую поверхность.
  virtual void SetFace2(const IModelObjectPtr & face) = 0;
  /// Получить вторую сопрягаемую поверхность.
  virtual IModelObjectPtr GetFace2() = 0;
  /// Установить тип (условие) сопряжения соединяющей поверхности с первой поверхностью сопряжения.
  virtual void SetFace1ConnectType(ksConnectTypeEnum connectType) = 0;
  /// Получить тип (условие) сопряжения соединяющей поверхности с первой поверхностью сопряжения.
  virtual ksConnectTypeEnum GetFace1ConnectType() = 0;
  /// Установить тип (условие) сопряжения соединяющей поверхности с второй поверхностью сопряжения.
  virtual void SetFace2ConnectType(ksConnectTypeEnum connectType) = 0;
  /// Получить тип (условие) сопряжения соединяющей поверхности с второй поверхностью сопряжения.
  virtual ksConnectTypeEnum GetFace2ConnectType() = 0;
  /**
    \brief Установить направление сопряжения вдоль границы первой сопрягаемой поверхности.
    \details От направления зависит форма поверхности соединения вдоль границы соединения. Тип (условие) не зависит.
    \param[in] sense - направление сопряжения (true - инвертированое, false - прямое).
  */
  virtual void SetSense1(bool sense) = 0;
  /**
    \brief Получить направление сопряжения вдоль границы первой сопрягаемой поверхности.
    \details От направления зависит форма поверхности соединения вдоль границы соединения. Тип (условие) не зависит.
    \return Направление сопряжения (true - инвертированое, false - прямое).
  */
  virtual bool GetSense1() = 0;
  /**
    \brief Установить направление сопряжения вдоль границы второй сопрягаемой поверхности.
    \details От направления зависит форма поверхности соединения вдоль границы соединения. Тип (условие) не зависит.
    \param[in] sense - направление сопряжения (true - инвертированое, false - прямое).
  */
  virtual void SetSense2(bool sense) = 0;
  /**
    \brief Получить направление сопряжения вдоль границы второй сопрягаемой поверхности.
    \details От направления зависит форма поверхности соединения вдоль границы соединения. Тип (условие) не зависит.
    \return Направление сопряжения (true - инвертированое, false - прямое).
  */
  virtual bool GetSense2() = 0;
  /**
    \brief Установить натяжение поверхности сопряжения вдоль границы первой сопрягаемой поверхности (в процентах).
    \details Влияет на форму поверхности: чем натяжение больше, тем больше кривизна поверхности соединения вблизи границы, 
             и наоборот, чем меньше натяжение, тем кривизна поверхности меньше
    \param[in] tension - величина натяжения в процентах, от 0 до 100.
  */
  virtual void SetTension1(double tension) = 0;
  /**
    \brief Получить натяжение поверхности сопряжения вдоль границы первой сопрягаемой поверхности (в процентах).
    \details Влияет на форму поверхности: чем натяжение больше, тем больше кривизна поверхности соединения вблизи границы, 
             и наоборот, чем меньше натяжение, тем кривизна поверхности меньше
    \return - Величина натяжения в процентах, от 0 до 100.
  */
  virtual double GetTension1() = 0;
  /**
    \brief Установить натяжение поверхности сопряжения вдоль границы второй сопрягаемой поверхности (в процентах).
    \details Влияет на форму поверхности: чем натяжение больше, тем больше кривизна поверхности соединения вблизи границы, 
             и наоборот, чем меньше натяжение, тем кривизна поверхности меньше
    \param[in] tension - величина натяжения в процентах, от 0 до 100.
  */
  virtual void SetTension2(double tension) = 0;
  /**
    \brief Получить натяжение поверхности сопряжения вдоль границы второй сопрягаемой поверхности (в процентах).
    \details Влияет на форму поверхности: чем натяжение больше, тем больше кривизна поверхности соединения вблизи границы, 
             и наоборот, чем меньше натяжение, тем кривизна поверхности меньше
    \return - Величина натяжения в процентах, от 0 до 100.
  */
  virtual double GetTension2() = 0;
  /**
    \brief Установить тип построения боковых рёбер поверхности сопряжения в месте соединения с границей первой сопрягаемой поверхности.
    \param[in] sideEdges - тип построения (true - как продление рёбер сопрягаемой поверхности, false - по нормали к граничному ребру).
  */
  virtual void SetSideEdges1(bool sideEdges) = 0;
  /**
    \brief Получить тип построения боковых рёбер поверхности сопряжения в месте соединения с границей первой сопрягаемой поверхности.
    \return Тип построения (true - как продление рёбер сопрягаемой поверхности, false - по нормали к граничному ребру).
  */
  virtual bool GetSideEdges1() = 0;
  /**
    \brief Установить тип построения боковых рёбер поверхности сопряжения в месте соединения с границей второй сопрягаемой поверхности.
    \param[in] sideEdges - тип построения (true - как продление рёбер сопрягаемой поверхности, false - по нормали к граничному ребру).
  */
  virtual void SetSideEdges2(bool sideEdges) = 0;
  /**
    \brief Получить тип построения боковых рёбер поверхности сопряжения в месте соединения с границей второй сопрягаемой поверхности.
    \return Тип построения (true - как продление рёбер сопрягаемой поверхности, false - по нормали к граничному ребру).
  */
  virtual bool GetSideEdges2() = 0;
  /// Установить признак общего натяжения на обоих границах (если натяжение общее, используется значение натяжения для первой границы).
  virtual void SetGeneralTension(bool generalTension) = 0;
  /// Получить признак общего натяжения на обоих границах (если натяжение общее, используется значение натяжения для первой границы).
  virtual bool IsGeneralTension() = 0;
  /// Установить признак проверки самопересечения (true - проверить поверхность сопряжения на наличие самопересечений, false - не проверять).
  virtual void SetCheckSelfIntersection(bool checkSelfIntersection) = 0;
  /// Получить признак проверки самопересечения (true - проверить поверхность сопряжения на наличие самопересечений, false - не проверять).
  virtual bool IsCheckSelfIntersection() = 0;
  /// Установить признак автоматического разбиения (true - автоматически разбить поверхность сопряжения на грани, false - не разбивать).
  virtual void SetAutoSegmentation(bool autoSegmentation) = 0;
  /// Получить признак автоматического разбиения (true - автоматически разбить поверхность сопряжения на грани, false - не разбивать).
  virtual bool IsAutoSegmentation() = 0;
  /// Добавить новое ребро после ребра с указанным индексом поверхности сопряжения. Вершины рёбер находятся на разных границах сопряжения.
  virtual bool AddNewEdge(int32_t indexAt) = 0;
  /// Удалить ребро поверхности сопряжения с указанным индексом. Вершины рёбер находятся на разных границах сопряжения.
  virtual bool DeleteEdge(int32_t index) = 0;
  /// Получить количество ребер поверхности сопряжения.
  virtual int32_t GetEdgesCount() = 0;
  /**
    \brief Установить параметры вершины ребра поверхности сопряжения.
    \details Если задан объект ассоциативной точки (associateVertex), параметр (t) и координаты точки (x, y, z) будут проигнорированы.
             Если задан параметр (t) и не задан объект ассоциативной точки (associateVertex), координаты точки (x, y, z) будут проигнорированы.
             Если не задан объект ассоциативной точки (associateVertex) и параметр (t), будут использованы координаты точки (x, y, z).
    \param[in] edgeIndex - индекс ребра для установки параметров его вершины.
    \param[in] startPoint - признак, на границе с какой из сопрягаемых поверхностей лежит вершина (true - на первой, false - на второй).
    \param[in] x, y, z - координаты точки (проекция этой точки на границу сопряжения станет новой вершиной ребра).
    \param[in] t - параметр новой вершины на границе сопряжения. Если задан параметр, координаты будут проигнорированы.
    \param[in] associateVertex - ассоциативная точка, проекция которой на границу сопряжения станет новой вершиной ребра.
               Ссылка на объект ассоциативной точки сохранится, и вершина ребра будет с ней связана.
    \return Успешность установки параметров вершины ребра поверхности сопряжения.
  */
  virtual bool SetEdgePointParam(int32_t edgeIndex, bool startPoint, double x, double y, double z,
                                 std::optional<double> t = std::nullopt, const IModelObjectPtr & associateVertex = nullptr) = 0;
  /**
    \brief Получить параметры вершины ребра поверхности сопряжения.
    \param[in] edgeIndex - индекс ребра для установки параметров его вершины.
    \param[in] startPoint - признак, на границе с какой из сопрягаемых поверхностей лежит вершина (true - на первой, false - на второй).
    \param[out] x, y, z - координата вершины ребра.
    \param[out] t - параметр вершины на границе сопряжения.
    \param[out] associateVertex - ассоциативная точка, связанная с вершиной ребра.
    \return Успешность получения параметров точки ребра поверхности сопряжения.
  */
  virtual bool GetEdgePointParam(int32_t edgeIndex, bool startPoint, double & x, double & y, double & z, double & t,
                                 IModelObjectPtr & associateVertex) = 0;
  /**
     \brief Получить параметры вершин рёбер поверхности сопряжения.
     \details Параметры разбиваются по различным массивам, в зависимости от того, на какой из двух границ сопряжения они лежат.
     \param[out] points1 - массив координат вершин рёбер на границе с первой сопрягаемой поверхностью.
                 points1[i * 3], points1[i * 3 + 1], points1[i * 3 + 2] - координаты вершины для i-го ребра.
     \param[out] t1 - массив параметров вершин рёбер на кривой границы с первой сопрягаемой поверхностью. 
                      Индексы параметров соотносятся с индексами рёбер.
     \param[out] associateVertexes1 - массив ассоциативных точек, связанных с вершинами рёбер на границе с первой сопрягаемой поверхностью.
                 Индексы ассоциативных вершин соотносятся с индексами рёбер.
     \param[out] points2 - массив координат вершин рёбер на границе с второй сопрягаемой поверхностью.
                 points1[i * 3], points1[i * 3 + 1], points1[i * 3 + 2] - координаты вершины для i-го ребра.
     \param[out] t2 - массив параметров вершин рёбер на кривой границы с второй сопрягаемой поверхностью. 
                      Индексы параметров соотносятся с индексами рёбер.
     \param[out] associateVertexes2 - массив ассоциативных точек, связанных с вершинами рёбер на границе с второй сопрягаемой поверхностью.
                 Индексы ассоциативных вершин соотносятся с индексами рёбер.
     \return Успешность получения параметров рёбер поверхности сопряжения.
  */
  virtual bool GetEdgePointParams(std::vector<double> & points1, std::vector<double> & t1,
                                  std::vector<IModelObjectPtr> & associateVertexes1, std::vector<double> & points2,
                                  std::vector<double> & t2, std::vector<IModelObjectPtr> & associateVertexes2) = 0;
};

