  /// Получить способ пересчета по индексу.
  virtual ksToleranceRecalcsEnum GetRecalcType(int32_t index) = 0;
  /// Получить способ пересчета по имени переменной или компонента.
  virtual ksToleranceRecalcsEnum GetRecalcTypeByName(const std::wstring & name) = 0;
  /// Получить способ пересчета по объекту.
  virtual ksToleranceRecalcsEnum GetRecalcTypeByObject(const IKompasAPIObjectPtr & object) = 0;
  /// Установить пользовательский способ пересчета для вставки по индексу.
  virtual void SetRecalcUserType(int32_t index, const std::wstring & recalcUserType) = 0;
  /// Установить пользовательский способ пересчета для вставки по имени.
  virtual void SetRecalcUserTypeByName(const std::wstring & name, const std::wstring & recalcUserType) = 0;
  /// Установить пользовательский способ пересчета для вставки по объекту.
  virtual void SetRecalcUserTypeByObject(const IKompasAPIObjectPtr & object, const std::wstring & recalcUserType) = 0;
  /// Установить пользовательский способ пересчета для вставки по индексу.
  virtual std::wstring GetRecalcUserType(int32_t index) = 0;
  /// Установить пользовательский способ пересчета для вставки по имени.
