  /// Установить пользовательский способ пересчета для вставки по объекту.
  virtual std::wstring GetRecalcUserTypeByObject(const IKompasAPIObjectPtr & object) = 0;
  /// Установить коэффициент по индексу.
  virtual void SetCoefficient(int32_t index, double coefficient) = 0;
  /// Установить коэффициент по имени.
