////////////////////////////////////////////////////////////////////////////////
//
/// Грань 3D.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IFace : IModelObject
{
  /// Получить тип поверхности.
  virtual ksMathSurface3DTypeEnum GetSurface3DType() = 0;
  /// Получить тип базовой поверхности.
  virtual ksMathSurface3DTypeEnum GetBaseSurface3DType() = 0;
  /// Получить математическую поверхность.
  virtual IMathSurface3DPtr GetMathSurface() = 0;
  /// Получить признак ориентации нормали грани (относительно ориентации нормали поверхности).
  virtual bool GetNormalOrientation() = 0;
  /// Получить массив циклов.
  virtual std::vector<ILoopPtr> GetLoops() = 0;
  /// Получить массив граней, стыкующихся с данной гранью.
  virtual std::vector<IFacePtr> GetConnectedFaces() = 0;
  /// Получить массив ребер, ограничивающих грань.
  virtual std::vector<IEdgePtr> GetLimitingEdges() = 0;
  /// Проверить связанность граней.
  virtual bool IsConnectedWith(const IFacePtr & otherFace) = 0;
  /// Получить максимальный радиус.
  virtual double GetRadius() = 0;
  /// Получить параметры конической грани (угол в радианах).
  virtual bool GetConeParam(double & height, double & angle, double & radius) = 0;
  /// Получить площадь грани.
  virtual double GetArea(ksLengthUnitsEnum unit) = 0;
  /// Получить параметры триангуляционной сетки.
  virtual ITessellationPtr GetTessellation() = 0;
  /**
   \brief Получить площадь грани.
   \param[in] unit - единицы измерения длины из перечисления ksLengthUnitsEnum.
   \param[in] angleTolerance - ограничение углового отклонения (в радианах) при аппроксимации оболочки треугольными пластинами.
   \return Вычисленная площадь.
   */
  virtual double GetAreaWithAccuracy(ksLengthUnitsEnum unit, double angleTolerance) = 0;
  /// Получить тело.
  virtual IBodyPtr GetBody() = 0;
  /// Получить признак того, что грань является плоской.
  virtual bool IsPlanar() = 0;
  /// Получить признак того, что грань является конической.
  virtual bool IsCone() = 0;
  /// Получить признак того, что грань является цилиндрической.
  virtual bool IsCylinder() = 0;
  /// Получить признак того, что грань является тором.
  virtual bool IsTorus() = 0;
  /// Получить признак сферичности грани.
  virtual bool IsSphere() = 0;
  /// Получить признак того, что грань является NURBS-поверхностью.
  virtual bool IsNurbsSurface() = 0;
  /// Получить признак того, что грань является поверхностью вращения.
  virtual bool IsRevolved() = 0;
  /// Получить признак того, что грань является поверхностью по траектории.
  virtual bool IsSwept() = 0;
  /// Получить признак выпуклости грани.
  virtual ksSurfaceSalientTypeEnum GetSalient() = 0;
  /// Получить координаты точки на грани.
  virtual bool GetPoint(double paramU, double paramV, double & x, double & y, double & z) = 0;
  /// Получить нормаль грани.
  virtual bool GetNormal(double paramU, double paramV, double & x, double & y, double & z) = 0;
  /// Получить начальное значение параметра U.
  virtual double GetParamUMin() = 0;
  /// Получить конечное значение параметра U.
  virtual double GetParamUMax() = 0;
  /// Получить начальное значение параметра V.
  virtual double GetParamVMin() = 0;
  /// Получить конечное значение параметра V.
  virtual double GetParamVMax() = 0;
  /// Получить ближайшую проекцию точки на поверхность.
  virtual bool NearPointProjection(double x, double y, double z, double & u, double & v) = 0;
  /// Получить параметры грани по параметрам поверхности.
  virtual bool GetFaceParam(double surfaceU, double surfaceV, double & faceU, double & faceV) = 0;
  /// Получить параметры поверхности по параметрам грани.
  virtual bool GetSurfaceParam(double faceU, double faceV, double & surfaceU, double & surfaceV) = 0;
  /// Получить расстояние между точкой и проекцией точки на грань.
  virtual double GetDistanceToPoint(double x, double y, double z) = 0;
};

