////////////////////////////////////////////////////////////////////////////////
struct IArc : IDrawingObject
{
  /// Установить радиус дуги.
  virtual void SetRadius(double radius) = 0;
  /// Получить радиус дуги.
  virtual double GetRadius() = 0;
  /// Установить направление построения дуги (true - по часовой стрелке, false - против часовой стрелки).
  virtual void SetDirection(bool direction) = 0;
  /// Получить направление построения дуги (true - по часовой стрелке, false - против часовой стрелки).
  virtual bool GetDirection() = 0;
  /// Установить координату центра дуги Xc.
  virtual void SetXc(double xc) = 0;
  /// Получить координату центра дуги Xc.
  virtual double GetXc() = 0;
  /// Установить координату центра дуги Yc.
  virtual void SetYc(double yc) = 0;
  /// Получить координату центра дуги Yc.
  virtual double GetYc() = 0;
  /// Установить координату первой точки дуги X1.
  virtual void SetX1(double x1) = 0;
  /// Получить координату первой точки дуги X1.
  virtual double GetX1() = 0;
  /// Установить координату первой точки дуги Y1.
  virtual void SetY1(double y1) = 0;
  /// Получить координату первой точки дуги Y1.
  virtual double GetY1() = 0;
  /// Установить координату второй точки дуги X2.
  virtual void SetX2(double x2) = 0;
  /// Получить координату второй точки дуги X2.
  virtual double GetX2() = 0;
  /// Установить координату второй точки дуги Y2.
  virtual void SetY2(double y2) = 0;
  /// Получить координату второй точки дуги Y2.
  virtual double GetY2() = 0;
  /// Установить координату средней точки, лежащей на дуге по оси X.
  virtual void SetX3(double x3) = 0;
  /// Получить координату средней точки, лежащей на дуге по оси X.
  virtual double GetX3() = 0;
  /// Установить координату средней точки, лежащей на дуге по оси Y.
  virtual void SetY3(double y3) = 0;
  /// Получить координату средней точки, лежащей на дуге по оси Y.
  virtual double GetY3() = 0;
  /// Установить угол между осью X и отрезком, соединяю­щим первую точку дуги с началом координат (в градусах).
  virtual void SetAngle1(double angle1) = 0;
  /// Получить угол между осью 0X и отрезком, соединяю­щим первую точку дуги с началом координат (в градусах).
  virtual double GetAngle1() = 0;
  /// Установить угол между осью X и отрезком, соединяю­щим вторую точку дуги с началом координат (в градусах).
  virtual void SetAngle2(double angle2) = 0;
  /// Получить угол между осью X и отрезком, соединяю­щим вторую точку дуги с началом координат (в градусах).
  virtual double GetAngle2() = 0;
};

