  /// Установить стиль линии кривой в вершине.
  virtual void SetVertexStyle(int32_t vertexIndex, int32_t vertexStyle) = 0;
  /// Получить количество вершин без учета концов.
  virtual int32_t GetVertexCount() = 0;
  /// Получить типы ограничений на концах мультилинии.
  virtual ksMlEndLimiterEnum GetEndLimiter(bool first) = 0;
  /// Установить типы ограничений на концах мультилинии.
  virtual void SetEndLimiter(bool first, ksMlEndLimiterEnum endLimiter) = 0;
  /// Установить параметр ограничителя (в процентах от ширины мультилинии).
  virtual void SetEndParameter(bool first, double endParameter) = 0;
  /// Получить параметр ограничителя (в процентах от ширины мультилинии).
  virtual double GetEndParameter(bool first) = 0;
  /// Получить стиль линии кривой в законцовке.
