////////////////////////////////////////////////////////////////////////////////
//
/// Кривая Безье.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IBezier : IDrawingObject
{
  /// Установить замкнутость кривой.
  virtual void SetClosed(bool closed) = 0;
  /// Получить замкнутость кривой.
  virtual bool IsClosed() = 0;
  /// Получить количество опорных точек.
  virtual int32_t GetPointsCount() = 0;
  /// Установить параметры узлов  (true - узел представлен опорной точкой и двумя крайними, false - только опорные точки).
  virtual void SetPoints(bool allPoints, const std::vector<double> & points) = 0;
  /// Получить параметры узлов (true - узел представлен опорной точкой и двумя крайними, false - только опорные точки).
  virtual std::vector<double> GetPoints(bool allPoints) = 0;

  /**
    \brief Добавить узел.
    \param[in] index - индекс добавляемого узла.
    \param[in] xBase - координаты опорной точки узла оси X.
    \param[in] yBase - координаты опорной точки узла оси Y.
    \param[in] xLeft - координаты левой точки узла оси X.
    \param[in] yLeft - координаты левой точки узла оси Y.
    \param[in] xRight - координаты правой точки узла оси X.
    \param[in] yRight - координаты правой точки узла оси Y.
    \return Успешность добавления.
  */
  virtual bool AddPoint(int32_t index, double xBase, double yBase, double * xLeft, double * yLeft, double * xRight,
                        double * yRight) = 0;

  /**
    \brief Получить параметры узла.
    \param[in] index - индекс добавляемого узла.
    \param[out] xBase - координаты опорной точки узла оси X.
    \param[out] yBase - координаты опорной точки узла оси Y.
    \param[out] xLeft - координаты левой точки узла оси X.
    \param[out] yLeft - координаты левой точки узла оси Y.
    \param[out] xRight - координаты правой точки узла оси X.
    \param[out] yRight - координаты правой точки узла оси Y.
    \return Успешность получения.
  */
  virtual bool GetPoint(int32_t index, double * xBase, double * yBase, double * xLeft, double * yLeft, double * xRight,
                        double * yRight) = 0;
  /// Удалить узел по индексу.
  virtual bool DeletePoint(int32_t index) = 0;
  /// Удалить все узлы.
  virtual bool Clear() = 0;
  /// Прочитать файл с данными.
  virtual bool ReadFromFile(const std::wstring & fileName) = 0;
  /// Записать файл с данными.
  virtual bool WriteToFile(const std::wstring & fileName) = 0;
};

