////////////////////////////////////////////////////////////////////////////////
//
/// NURBS-кривая.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct INurbs : IDrawingObject
{
  /// Установить признак замкнутости кривой.
  virtual void SetClosed(bool closed) = 0;
  /// Получить признак замкнутости кривой.
  virtual bool IsClosed() = 0;
  /// Установить порядок кривой (степень + 1).
  virtual void SetDegree(int32_t degree) = 0;
  /// Получить порядок кривой (степень + 1).
  virtual int32_t GetDegree() = 0;
  /// Получить признак периодичности NURBS-кривой.
  virtual bool IsPeriodic() = 0;
  /// Получить количество точек.
  virtual int32_t GetPointsCount() = 0;
  /**
    \brief Установить параметры NURBS-кривой в виде массивов.
    \param[in] points - массив координат точек кривой.
    \param[in] weights - массив весов точек.
    \param[in] knots - массив узлов сплайна.
    \param[in] degree - порядок кривой (степень + 1).
    \param[in] closed - признак замкнутости кривой.
    \return Успешность операции.
  */
  virtual bool SetNurbsParams(const std::vector<double> & points, const std::vector<double> & weights,
                              const std::vector<double> & knots, int32_t degree, bool closed) = 0;
  /**
    \brief Получить параметры NURBS-кривой в виде массивов.
    \param[out] points - массив координат точек кривой.
    \param[out] weights - массив весов точек.
    \param[out] knots - массив узлов сплайна.
    \return Успешность операции.
  */
  virtual bool GetNurbsParams(std::vector<double> & points, std::vector<double> & weights, std::vector<double> & knots) = 0;
  /// Добавить точку.
  virtual bool AddPoint(int32_t index, double x, double y, double weight) = 0;
  /// Получить параметры точки.
  virtual bool GetPoint(int32_t index, double & x, double & y, double & weight) = 0;
  /// Удалить точку.
  virtual bool DeletePoint(int32_t index) = 0;
  /// Удалить все точки.
  virtual bool Clear() = 0;
  /// Прочитать файл с данными NURBS-кривой.
  virtual bool ReadFromFile(const std::wstring & fileName) = 0;
  /// Записать файл с данными NURBS-кривой.
  virtual bool WriteToFile(const std::wstring & fileName) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Коллекция NURBS-кривых.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct INurbses : IDrawingObjects
{
  /// Получить NURBS-кривую, заданную по индексу.
  virtual INurbsPtr GetNurbs(int32_t index) = 0;
  /// Создать NURBS-кривую и добавить её в коллекцию.
  virtual INurbsPtr Add() = 0;
  /// Преобразовать кривую в NURBS-кривую и добавить её в коллекцию.
  virtual INurbsPtr Convert(const IDrawingObjectPtr & curve) = 0;
  /**
    \brief Преобразовать с указанием параметров кривую в NURBS-кривую и добавить её в коллекцию.
    \param[in] curve - исходная кривая.
    \param[in] aproximationType - способ аппроксимации.
    \param[in] step - шаг аппроксимации.
    \return NURBS-кривая.
  */
  virtual INurbsPtr ConvertToNurbsByPoints(const IDrawingObjectPtr & curve, ksNurbsByPointsAproximationTypeEnum aproximationType,
                                           double step) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Растровый объект.
/**
*/
////////////////////////////////////////////////////////////////////////////////
struct IRaster : IDrawingObject
{
  /**
    \brief Установить местоположение растрового объекта.
    \param[in] x, y - координаты левого нижнего угла объекта.
    \param[in] angle - угол поворота объекта (в градусах).
    \param[in] isFlippedVertical - признак зеркальной симметрии (true - отразить зеркально, false - не отражать).
    \return Успешность установки местоположения.
  */
  virtual bool SetPlacement(double x, double y, double angle, bool isFlippedVertical) = 0;
  /**
    \brief Получить местоположение растрового объекта.
    \param[out] x, y - координаты левого нижнего угла объекта.
    \param[out] angle - угол поворота объекта (в градусах).
    \param[out] isFlippedVertical - признак зеркальной симметрии (true - отражается зеркально, false - не отражается).
    \return Успешность получения местоположения.
  */
  virtual bool GetPlacement(double & x, double & y, double & angle, bool & isFlippedVertical) = 0;
  /// Установить масштаб объекта.
  virtual void SetScale(double scale) = 0;
  /// Получить масштаб объекта.
  virtual double GetScale() = 0;
  /// Установить имя файла растрового объекта.
  virtual void SetFileName(const std::wstring & fileName) = 0;
  /// Получить имя файла растрового объекта.
  virtual std::wstring GetFileName() = 0;
  /// Установить способ вставки (true - внедрить в документ, false - вставлять ссылкой).
  virtual void SetInsertionType(bool insertionType) = 0;
  /// Получить способ вставки (true - внедрить в документ, false - вставлять ссылкой).
  virtual bool GetInsertionType() = 0;
  /// Установить разрешение растра.
  virtual void SetResolution(double resolution) = 0;
  /// Получить разрешение растра.
  virtual double GetResolution() = 0;
  /// Установить режим отрисовки (true - показывать полностью, false - показывать часть).
  virtual void SetDisplayModePartial(bool displayModePartial) = 0;
  /// Получить режим отрисовки (true - показывать полностью, false - показывать часть).
  virtual bool GetDisplayModePartial() = 0;
  /// Установить высоту объекта.
  virtual void SetHeight(double height) = 0;
  /// Получить высоту объекта.
  virtual double GetHeight() = 0;
  /// Установить ширину объекта.
  virtual void SetWidth(double width) = 0;
  /// Получить ширину объекта.
  virtual double GetWidth() = 0;
  /// Получить исходную высоту изображения.
  virtual double GetSourceHeight() = 0;
  /// Получить исходную ширину изображения.
  virtual double GetSourceWidth() = 0;
  /// Получить цветовую палитру (количество разрядов).
  virtual int32_t GetPalette() = 0;
  /// Получить признак возможности изменения разрешения (true - разрешение можно менять, false - нельзя).
  virtual bool IsEnableChangeResolution() = 0;
  /// Получить признак заданных границ для объекта (true - границы заданы, false - не заданы).
  virtual bool IsCutBoundarySet() = 0;
};

