////////////////////////////////////////////////////////////////////////////////
//
/// Радиальный размер.
/**
  Радиальный размер можно создать без опорного объекта, установив параметры.
  Так же возможно установить опорный объект. В таком случае, параметры определятся по объекту.
*/
////////////////////////////////////////////////////////////////////////////////
struct IRadialDimension : IDrawingObject
{
  /// Получить координату центра по оси X.
  virtual double GetXc() = 0;
  /// Установить координату центра по оси X.
  virtual void SetXc(double xc) = 0;
  /// Получить координату центра по оси Y.
  virtual double GetYc() = 0;
  /// Установить координату центра по оси Y.
  virtual void SetYc(double yc) = 0;
  /// Получить радиус.
  virtual double GetRadius() = 0;
  /// Установить радиус.
  virtual void SetRadius(double radius) = 0;
  /// Получить тип радиального размера (true - от центра, false - не от центра).
  virtual bool GetDimensionType() = 0;
  /// Установить тип радиального размера (true - от центра, false - не от центра).
  virtual void SetDimensionType(bool dimensionType) = 0;
  /// Получить опорный объект.
  virtual IDrawingObjectPtr GetBaseObject() = 0;
  /// Установить опорный объект.
  virtual void SetBaseObject(const IDrawingObjectPtr & object) = 0;
  /// Получить угол наклона размерной линии (в градусах).
  virtual double GetAngle() = 0;
  /// Установить угол наклона размерной линии (в градусах).
  virtual void SetAngle(double angle) = 0;
  /**
    \brief Добавить ответвление для объекта.
    \param[in] branchBegin - сторона полки, соединённой с ответвлением (true - начало, false - конец).
    \param[in] branchObject - опорный объект для ответвления.
    \return Успешность добавления.
  */
  virtual bool AddBranch(bool branchBegin, const IDrawingObjectPtr & branchObject) = 0;
  /**
    \brief Добавить ответвление по параметрам дуги.
    \param[in] branchBegin - сторона полки, соединённой с ответвлением (true - начало, false - конец).
    \param[in] xc, yc - координаты центра дуги.
    \param[in] radius - радиус дуги.
    \param[in] angle1, angle2 - углы дуги (в градусах).
    \param[in] direction - направление построения дуги (true - прямое, false - обратное).
    \return Успешность добавления.
  */
  virtual bool AddBranchByArcParam(bool branchBegin, double xc, double yc, double radius, double angle1, double angle2,
                                   bool direction) = 0;
  /// Получить количество ответвлений.
  virtual int32_t GetBranchsCount() = 0;
  /**
    \brief Получить опорный объект для ответвления.
    \param[in] index - индекс ответвления.
    \return Опорный объект.
  */
  virtual IDrawingObjectPtr GetBranchObject(int32_t index) = 0;
  /**
    \brief Установить опорный объект для ответвления.
    \param[in] index - индекс ответвления для установки объекта.
    \param[in] branchObject - опорный объект.
  */
  virtual void SetBranchObject(int32_t index, const IDrawingObjectPtr & branchObject) = 0;
  /// Удалить дополнительное ответвление.
  virtual bool DeleteBranch(int32_t index) = 0;
  /**
    \brief Получить параметры ответвления.
    \param[in] index - индекс ответвления.
    \param[out] xc, yc - координаты центра.
    \param[in] radius - радиус.
    \param[in] angle1, angle2 - углы (если опорный объект - дуга) (в градусах).
    \param[in] direction - направление построения (если опорный объект - дуга) (true - прямое, false - обратное).
    \return Успешность получения параметров.
  */
  virtual bool GetBranchParam(int32_t index, double & xc, double & yc, double & angle1, double & angle2, bool & direction) = 0;
  /**
    \brief Установить параметры ответвления.
    \param[in] index - индекс ответвления.
    \param[out] xc, yc - координаты центра.
    \param[in] radius - радиус.
    \param[in] angle1, angle2 - углы (для опорного объекта - дуги) (в градусах).
    \param[in] direction - направление построения (для опорного объекта - дуги) (true - прямое, false - обратное).
    \return Успешность установки параметров.
  */
  virtual bool SetBranchParam(int32_t index, double xc, double yc, double angle1, double angle2, bool direction) = 0;
  /// Получить сторону полки, соединённую с ответвлением (true - начало, false - конец).
  virtual bool GetBranchBegin(int32_t index) = 0;
  /// Установить сторону полки, соединённую с ответвлением (true - начало, false - конец).
  virtual void SetBranchBegin(int32_t index, bool branchBegin) = 0;
  /// Получить координату по оси X начала полки.
  virtual double GetShelfX() = 0;
  /// Установить координату по оси X начала полки.
  virtual void SetShelfX(double shelfX) = 0;
  /// Получить координату по оси Y начала полки.
  virtual double GetShelfY() = 0;
  /// Получить координату по оси Y начала полки.
  virtual void SetShelfY(double shelfY) = 0;
};

