////////////////////////////////////////////////////////////////////////////////
//
/// Линейная сетка центров.
/**
  Линейная сетка центров позволяет создать центровые линии для группы объектов (дуг и окружностей), 
  центры которых расположены в узлах параллелограммной сетки
*/
////////////////////////////////////////////////////////////////////////////////
struct ILinearCentres : IDrawingObject
{
  /// Получить массив опорных объектов сетки.
  virtual std::vector<IDrawingObjectPtr> GetBaseObjects() = 0;
  /// Установить массив опорных объектов сетки.
  virtual void SetBaseObjects(const std::vector<IDrawingObjectPtr> & baseObjects) = 0;
  /**
    \brief Установить режим отрисовки (с разрывами/без разрывов).
    \details Режим "без разрывов" означает отрисовку линий, 
             если они пересекаются и в месте их пересечения нет центра опорного объекта.
    \param[in] hasBreaks - true - не отрисовывать пересекающиеся линии, false - отрисовывать.
  */
  virtual void SetHasBreaks(bool hasBreaks) = 0;
  /**
    \brief Получить режим отрисовки (с разрывами/без разрывов).
    \details Режим "без разрывов" означает отрисовку линий, 
             если они пересекаются и в месте их пересечения нет центра опорного объекта.
    \return true - не отрисовывать пересекающиеся линии, false - отрисовывать.
  */
  virtual bool IsHasBreaks() = 0;
  /// Установить угол наклона первой оси (в градусах).
  virtual void SetAxisAngle(double axisAngle) = 0;
  /// Получить наклон первой оси (угол в градусах).
  virtual double GetAxisAngle() = 0;
  /// Установить угол раствора (наклон второй оси относительно первой) (в градусах).
  virtual void SetTurnAngle(double turnAngle) = 0;
  /// Получить угол раствора (наклон второй оси относительно первой) (в градусах).
  virtual double GetTurnAngle() = 0;
  /// Получить массив координат вершин сетки (координаты в массив записаны попарно, по оси X и Y).
  virtual std::vector<double> GetCentres() = 0;
  /// Получить радиусы опорных объектов (дуг или окружностей).
  virtual std::vector<double> GetRadiuses() = 0;
  /**
    \brief Добавить обозначение центра в сетку.
    \details Метод только добавляет узел в сетку, опорный объект не создаётся.
    \param[in] x, y - координаты центра.
    \param[in] radius - радиус центра.
    \return Успешность добавления.
  */
  virtual bool AddCentre(double x, double y, double radius) = 0;
  /// Добавить обозначение центра в сетку объекту (добавить объект в массив опорных объектов).
  virtual bool AddCentreByObject(const IKompasAPIObjectPtr & object) = 0;
  /// Очистить список центров.
  virtual bool Clear() = 0;
  /// Удалить обозначение центра по индексу.
  virtual bool DeleteCentre(int32_t index) = 0;
  /// Удалить обозначение центра по координатам точки центра.
  virtual bool DeleteCentreByPoint(double x, double y) = 0;
};

