struct ISpecificationDescriptions : IKompasCollection
{
  /// Получить описание по индексу.
  virtual ISpecificationDescriptionPtr GetItem(int32_t index) = 0;
  /**
    \brief Добавить описание в документ и в коллекцию.
    \details К одному документу могут быть добавлены описания спецификации только разных стилей. 
      Если LayoutName и StyleID не заданы, то добавляется описание спецификации по умолчанию, 
      если оно не было создано ранее.
    \param[in] layoutName - имя библиотеки стилей.
    \param[in] styleId - номер стиля в библиотеке стилей.
    \param[in] spcName - имя документа спецификации, связанного с описанием спецификации.
    \return Описание спецификации.
  */
  virtual ISpecificationDescriptionPtr Add(const std::wstring & layoutName, int32_t styleId, const std::wstring & spcName) = 0;
  /// Получить описание спецификации по имени файла библиотеки оформлений и номеру стиля в библиотеке.
  virtual ISpecificationDescriptionPtr GetDescription(const std::wstring & layoutName, int32_t styleId) = 0;
  /// Получить текущее описание.
  virtual ISpecificationDescriptionPtr GetActive() = 0;
  /// Получить текущее описание, соответствующее библиотечному стилю.
  virtual ISpecificationDescriptionPtr GetActiveFromLibStyle() = 0;
  /// Получить события описания спецификации.
  virtual ISpecificationDescriptionEventsPtr Events() = 0;
  /// Получить состояние режима редактирования объектов спецификации.
  virtual ksSlaveActiveEnum IsSlaveActive() = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Описание спецификации.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISpecificationDescription : IKompasAPIObject
{
  /// Имя файла библиотеки стилей.
  virtual std::wstring GetLayoutName() = 0;
  /// Имя файла библиотеки стилей.
  virtual void SetLayoutName(const std::wstring & name) = 0;
  /// Номер стиля в библиотеке стилей.
  virtual int32_t GetStyleId() = 0;
  /// Номер стиля в библиотеке стилей.
  virtual void SetStyleId(int32_t styleId) = 0;
  /// Имя подключенного файла документа спецификации.
  virtual std::wstring GetSpecificationDocumentName() = 0;
  /// Имя подключенного файла документа спецификации.
  virtual void SetSpecificationDocumentName(const std::wstring & name) = 0;
  /// Текущее описание.
  virtual bool IsActive() = 0;
  /// Текущее описание.
  virtual void SetActive(bool active) = 0;
  /// Изменить описание.
  virtual bool Update() = 0;
  /// Удалить описание.
  virtual bool Delete() = 0;
  /// Стиль спецификации (только для чтения).
  virtual ISpecificationStylePtr GetSpecificationStyle() = 0;
  /// Настройки спецификации.
  virtual ISpecificationTuningPtr GetSpecificationTuning() = 0;
  /// Объекты спецификации.
  virtual std::vector<ISpecificationObjectPtr> GetObjects() = 0;
  /// Базовые объекты спецификации.
  virtual ISpecificationBaseObjectsPtr GetBaseObjects() = 0;
  /// Объекты спецификации - комментарии.
  virtual ISpecificationCommentObjectsPtr GetCommentObjects() = 0;
  /// Показывать на листе.
  virtual bool IsShowOnSheet() = 0;
  /// Показывать на листе.
  virtual void SetShowOnSheet(bool show) = 0;
  /// Текущий объект спецификации (выделенный или редактируемый в таблице спецификации).
  virtual ISpecificationObjectPtr GetCurrentObject() = 0;
  /// Текущий объект спецификации, заданный по указателю объекта или по индексу объекта.
  virtual void SetCurrentObject(const ISpecificationObjectPtr & object) = 0;
  /// Показывать все объекты.
  virtual bool IsShowAllObjects() = 0;
  /// Показывать все объекты.
  virtual void SetShowAllObjects(bool show) = 0;
  /// Отображаемое имя исполнения.
  virtual std::wstring GetPerformanceName(int32_t performanceIndex, int32_t blockIndex) = 0;
  /// Отображаемое имя исполнения.
  virtual void SetPerformanceName(int32_t performanceIndex, int32_t blockIndex, const std::wstring & name) = 0;
  /// Режим редактирования внешних объектов для описания спецификации сборки.
  virtual bool IsDelegateMode() = 0;
  /// Режим редактирования внешних объектов для описания спецификации сборки.
  virtual void SetDelegateMode(bool delegateMode) = 0;
  /// Необходимость перестроения спецификации.
  virtual bool IsNeedRebuild() = 0;
  /// Необходимость перестроения спецификации.
  virtual void SetNeedRebuild(bool needRebuild) = 0;
  /// Отличие стиля СП от библиотечного: 0 - не отличается, 1 -отличается, -1 стиль не найден.
  virtual ksSpecificationStyleDifferenceTypeEnum CompareStyleWithLibStyle() = 0;
  /// Получить параметры и имя колонки исполнения по индексу.
  virtual std::wstring GetPerformanceParam(int32_t displayPerformanceIndex, int32_t & performanceIndex, int32_t & blockIndex) = 0;
  /// Показывать только исключенные объекты.
  virtual bool IsShowExcludedObjects() = 0;
  /// Показывать только исключенные объекты.
  virtual void SetShowExcludedObjects(bool show) = 0;
  /// Количество исполнений.
  virtual int32_t GetPerformanceCount() = 0;
  /// Количество исполнений.
  virtual void SetPerformanceCount(int32_t count) = 0;
  /// Количество исполнений в блоке.
  virtual int32_t GetPerformanceCountInBlock() = 0;
  /// По геометрии получить массив объектов спецификации.
  virtual std::vector<ISpecificationBaseObjectPtr> GetSpecificationObjectsForGeom(
    const std::vector<IKompasAPIObjectPtr> & geometry, int32_t sectionNumber, NumericId attributeNumber) = 0;
  /// Получить спецификацию (или таблицу изменений) на листе.
  virtual ISheetSpecificationPtr GetSheetSpecification() = 0;
  /// Получить параметры для экспорта спецификации.
  virtual ISpecificationExportParametersPtr GetExportParameters() = 0;
  /// Экспортировать спецификацию.
  virtual bool Export(const std::wstring & fileName, const ISpecificationExportParametersPtr & parameters) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// События описания спецификации.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ISpecificationDescriptionEvents : IAPIObject
{
  /// Удалить все обработчики.
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;
  /// Описание обработчика события "Начало изменения настроек спецификации".
  using OnTuningSpcStyleBeginChangeHandler = std::function<bool(const ISpecificationDescriptionPtr & description)>;
  /// Добавить обработчик события "Начало изменения настроек спецификации".
  virtual void AddTuningSpcStyleBeginChangeHandler(const std::wstring & handlerOwner,
                                                   OnTuningSpcStyleBeginChangeHandler eventHandler) = 0;
  /// Описание обработчика события "Настройки спецификации изменились".
  using OnTuningSpcStyleChangeHandler = std::function<void(const ISpecificationDescriptionPtr & description, bool wasChanged)>;
  /// Добавить обработчик события "Настройки спецификации изменились".
  virtual void AddTuningSpcStyleChangeHandler(const std::wstring & handlerOwner, OnTuningSpcStyleChangeHandler eventHandler) = 0;
  /// Описание обработчика события "Изменилось текущее описание спецификации".
  using OnChangeCurrentSpcDescriptionHandler = std::function<void(const ISpecificationDescriptionPtr & description)>;
  /// Добавить обработчик события "Изменилось текущее описание спецификации".
  virtual void AddChangeCurrentSpcDescriptionHandler(const std::wstring & handlerOwner,
                                                     OnChangeCurrentSpcDescriptionHandler eventHandler) = 0;
  /// Описание обработчика события "Добавилось описание спецификации".
  using OnSpcDescriptionAddHandler = std::function<void(const ISpecificationDescriptionPtr & description)>;
  /// Добавить обработчик события "Добавилось описание спецификации".
  virtual void AddSpcDescriptionAddHandler(const std::wstring & handlerOwner, OnSpcDescriptionAddHandler eventHandler) = 0;
  /// Описание обработчика события "Удалилось описание спецификации".
  using OnSpcDescriptionRemoveHandler = std::function<void(const ISpecificationDescriptionPtr & description)>;
  /// Добавить обработчик события "Удалилось описание спецификации".
  virtual void AddSpcDescriptionRemoveHandler(const std::wstring & handlerOwner, OnSpcDescriptionRemoveHandler eventHandler) = 0;
  /// Описание обработчика события "Начало редактирования описания спецификации".
  using OnSpcDescriptionBeginEditHandler = std::function<bool(const ISpecificationDescriptionPtr & description)>;
  /// Добавить обработчик события "Начало редактирования описания спецификации".
  virtual void AddSpcDescriptionBeginEditHandler(const std::wstring & handlerOwner,
                                                 OnSpcDescriptionBeginEditHandler eventHandler) = 0;
  /// Описание обработчика события "Отредактировали описание спецификации".
  using OnSpcDescriptionEditHandler = std::function<void(const ISpecificationDescriptionPtr & description, bool wasChanged)>;
  /// Добавить обработчик события "Отредактировали описание спецификации".
  virtual void AddSpcDescriptionEditHandler(const std::wstring & handlerOwner, OnSpcDescriptionEditHandler eventHandler) = 0;
  /// Описание обработчика события "Начало расчета позиций".
  using OnBeginCalcPositionsHandler = std::function<bool()>;
  /// Добавить обработчик события "Начало расчета позиций".
  virtual void AddBeginCalcPositionsHandler(const std::wstring & handlerOwner, OnBeginCalcPositionsHandler eventHandler) = 0;
  /// Описание обработчика события "Проведен расчет позиций".
  using OnCalcPositionsHandler = std::function<void()>;
  /// Добавить обработчик события "Проведен расчет позиций".
  virtual void AddCalcPositionsHandler(const std::wstring & handlerOwner, OnCalcPositionsHandler eventHandler) = 0;
  /**
    \brief Описание обработчика события "Начало создания объекта СП (до диалога выбора раздела)".
    \param[in] objectType: -1 тип объекта не определен, 0 - базовый объект, 1 - вспомогательный.
    \return true - разрешить создание объекта СП, false - запретить.
  */
  using OnBeginCreateObjectHandler = std::function<bool(int32_t objectType)>;
  /// Добавить обработчик события "Начало создания объекта СП (до диалога выбора раздела)".
  virtual void AddBeginCreateObjectHandler(const std::wstring & handlerOwner, OnBeginCreateObjectHandler eventHandler) = 0;
};

