////////////////////////////////////////////////////////////////////////////////
//
/// События 2D документа.
/**
*/
////////////////////////////////////////////////////////////////////////////////
struct IKompasDocument2DEvents : IAPIObject
{
  /// Удалить все обработчики.
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;

  /// Описание обработчика "Начало перестроения ассоциативного чертежа".
  using OnBeginRebuildHandler = std::function<bool()>;
  /// Добавить обработчик события "Начало перестроения ассоциативного чертежа".
  virtual void AddBeginRebuildHandler(const std::wstring & handlerOwner, OnBeginRebuildHandler eventHandler) = 0;
  /// Описание обработчика "Ассоциативный чертеж перестроен".
  using OnRebuildHandler = std::function<bool()>;
  /// Добавить обработчик события "Ассоциативный чертеж перестроен".
  virtual void AddRebuildHandler(const std::wstring & handlerOwner, OnRebuildHandler eventHandler) = 0;
  /// Описание обработчика "Начало вставки фрагмента (до диалога выбора имени)".
  using OnBeginInsertFragmentHandler = std::function<bool()>;
  /// Добавить обработчик события "Начало вставки фрагмента (до диалога выбора имени)".
  virtual void AddBeginInsertFragmentHandler(const std::wstring & handlerOwner, OnBeginInsertFragmentHandler eventHandler) = 0;
  /// Описание обработчика "Начало выбора материала".
  using OnBeginChoiceMaterialHandler = std::function<bool()>;
  /// Добавить обработчик события "Начало выбора материала".
  virtual void AddBeginChoiceMaterialHandler(const std::wstring & handlerOwner, OnBeginChoiceMaterialHandler eventHandler) = 0;
  /// Описание обработчика "Закончен выбор свойства".
  using OnChoicePropertyHandler = std::function<bool(const IKompasAPIObjectPtr & object, NumericId propertyTypeId)>;
  /// Добавить обработчик события "Закончен выбор свойства".
  virtual void AddChoicePropertyHandler(const std::wstring & handlerOwner, OnChoicePropertyHandler eventHandler) = 0;
  /// Описание обработчика "Начало выбора свойства".
  using OnBeginChoicePropertyHandler = std::function<bool(const IKompasAPIObjectPtr & object, NumericId propertyTypeId)>;
  /// Добавить обработчик события "Начало выбора свойства".
  virtual void AddBeginChoicePropertyHandler(const std::wstring & handlerOwner, OnBeginChoicePropertyHandler eventHandler) = 0;
  /// Описание обработчика "Начало удаления значения свойства".
  using OnBeginDeletePropertyHandler = std::function<bool(const IKompasAPIObjectPtr & object, NumericId propertyTypeId)>;
  /// Добавить обработчик события "Начало удаления значения свойства".
  virtual void AddBeginDeletePropertyHandler(const std::wstring & handlerOwner, OnBeginDeletePropertyHandler eventHandler) = 0;
  /// Описание обработчика "Завершение удаления свойства".
  using OnDeletePropertyHandler = std::function<bool(const IKompasAPIObjectPtr & object, NumericId propertyTypeId)>;
  /// Добавить обработчик события "Завершение удаления свойства".
  virtual void AddDeletePropertyHandler(const std::wstring & handlerOwner, OnDeletePropertyHandler eventHandler) = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// Базовый класс 2D документов КОМПАС.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IKompasDocument2D : IKompasDocument
{
  /// Получить менеджер слоев и видов документа.
  virtual IViewsAndLayersManagerPtr GetViewsAndLayersManager() = 0;
  /**
    \brief Разбить объект на составляющие части.
    \details Разбить объект на составляющие части - отрезки, дуги, тексты.
             Возвращается указатель на временную группу - компонент сложного объекта.
    \param[in] object - разбиваемый объект.
    \param[in] level - уровень разбиения.
    \param[in] arrow - стрелка прогиба.
    \param[in] decomposeType - параметры СК (используются ksAllParam, ksViewAllParam или ksSheetAllParam).
    \return Группа объектов после разбиения.
  */
  virtual IDrawingGroupPtr DecomposeObject(const IKompasAPIObjectPtr & object, ksDecomposeObjectLevelEnum level, double arrow,
                                           ksDrawingObjectParamTypeEnum decomposeType) = 0;
  /**
    \brief Разбить документ спецификации на составляющие части.
    \details Разбить документ спецификации на составляющие части.
             Спецификация разбивается по листам (document - указатель на документ СП,
             numSheet - номер листа спецификации, начиная с 1)
             Текущим документом должен быть графический документ.
    \param[in] document - разбиваемый объект.
    \param[in] level - уровень разбиения.
    \param[in] arrow - стрелка прогиба.
    \param[in] numSheet - номер разбиваемого листа.
    \return Группа объектов после разбиения.
  */
  virtual IDrawingGroupPtr DecomposeSpecificationDocument(const ISpecificationDocumentPtr & document,
                                                          ksDecomposeObjectLevelEnum level, double arrow, int32_t numSheet) = 0;
  /// Получить обработчик событий 2D объектов по ключу, заданному при добавлении обработчика.
  virtual IDrawingObjectEventsPtr GetObject2DEvents(const std::wstring & handlerOwner) = 0;
  /// Получить результат редактирования 2D объекта
  virtual IDrawingObjectEventsResultPtr GetDrawingObjectEventsResult() = 0;
  /// Получить обработчик событий документа
  virtual IKompasDocument2DEventsPtr Events2D() = 0;
  /// Получить редактируемый макроэлемент.
  virtual IMacroObjectPtr GetEditMacroObject() = 0;
  /// Получить коллекцию групп.
  virtual IDrawingGroupsPtr GetDrawingGroups() = 0;
  /// Получить коллекцию именованных групп.
  virtual IDrawingGroupsPtr GetNamedGroups() = 0;
  /// Получить текущую группу.
  virtual IDrawingGroupPtr GetCurrentGroup() = 0;
  /// Получить менеджер селектированных объектов.
  virtual ISelectionManagerPtr GetSelectionManager() = 0;
  /// Получить менеджер выбранных объектов.
  virtual IChooseManagerPtr GetChooseManager() = 0;
  /**
    \brief Скопировать объекты по заданным параметрам.
    \param[in] objects - массив объектов, которые требуется скопировать.
    \param[in] params - параметры копирования, можно получить с помощью метода Getinterface. Доступные типы:
               KompasAPIObjectTypeEnum::ksObjectCopyObjectParam (интерфейс ICopyObjectParam),
               KompasAPIObjectTypeEnum::ksObjectCurveCopyObjectParam (интерфейс ICurveCopyObjectParam),
               KompasAPIObjectTypeEnum::ksObjectCircleCopyObjectParam (интерфейс ICircleCopyObjectParam),
               KompasAPIObjectTypeEnum::ksObjectCircularCopyObjectParam (интерфейс ICircularCopyObjectParam),
               KompasAPIObjectTypeEnum::ksObjectMeshCopyObjectParam (интерфейс IMeshCopyObjectParam).
    \return Массив скопированных объектов.
  */
  virtual std::vector<IDrawingObjectPtr> CopyObjects(const std::vector<IKompasAPIObjectPtr> & objects,
                                                     const ICopyObjectParamPtr & params) = 0;
  /**
    \brief Получить массив параметрических переменных.
    \param[in] externalOnly - true - получить только внешние переменные, false - все переменные.
    \return Массив переменных.
  */
  virtual std::vector<IVariablePtr> GetVariables(bool externalOnly) = 0;
  /**
    \brief Получить параметрическую переменную по индексу.
    \param[in] external - признак, из какой коллекции требуется вернуть переменную (true - коллекция внешних переменных, false - всех).
    \param[in] index - индекс переменной, которую надо вернуть.
    \return Параметрическая переменная.
  */
  virtual IVariablePtr GetVariable(bool external, int32_t index) = 0;
  /**
    \brief Получить параметрическую переменную по имени.
    \param[in] external - признак, из какой коллекции требуется вернуть переменную (true - коллекция внешних переменных, false - всех).
    \param[in] name - имя запрашиваемой переменной.
    \return Параметрическая переменная.
  */
  virtual IVariablePtr GetVariableByName(bool external, const std::wstring & name) = 0;
  /**
    \brief Получить параметрическую переменную, связанную с объектом размера.
    \param[in] dimension2D - объект размера, по которому необходимо получить переменную.
    \return Параметрическая переменная.
  */
  virtual IVariablePtr GetDimensionVariable(const IDimension2DPtr & dimension) = 0;
  /// Получить количество параметрических переменных (true - только внешних, false - всех).
  virtual int32_t GetVariablesCount(bool external) = 0;
  /// Обновить значения внешних переменных.
  virtual bool UpdateVariables() = 0;
  /// Получить таблицу переменных.
  virtual IVariableTablePtr GetVariableTable() = 0;
  /// Проверить допустимость создания новой переменной с данным именем.
  virtual bool IsVariableNameValid(const std::wstring & name) = 0;
  /**
    \brief Создать переменную и добавить переменную в массив переменных и документ.
    \param[in] name - имя переменной.
    \param[in] value - значение переменной.
    \param[in] note - комментарий к переменной.
    \return Параметрическая переменная.
  */
  virtual IVariablePtr AddVariable(const std::wstring & name, double value, const std::wstring & note) = 0;
  /// Перестроить документ.
  virtual bool RebuildDocument() = 0;
  /// Перестроить документ полностью (вместе со связями).
  virtual bool CompleteRebuildDocument() = 0;
  /**
    \brief Создать гиперссылку.
    \param[in] objects - объекты, для которых будет добавлен атрибут с гиперссылкой.
    \param[in] linkType - тип ссылки (на объект, на файл или web-страницу, e-mail).
    \param[in] text - текст гиперссылки.
    \param[in] linkObject - объект, на который указывает гиперссылка (для linkType == ksHyperLinkTypeEnum::ksHLObject).
    \param[in] level - уровень ссылки.
    \return Успешность создания ссылки.
  */
  virtual bool CreateHyperLink(const std::vector<IDrawingObjectPtr> & objects, ksHyperLinkTypeEnum linkType,
                               const std::wstring & text, const IDrawingObjectPtr & linkObject, int32_t level) = 0;
  /**
    \brief  Получить объекты, имеющие гиперссылку.
    \param[in] linkType - тип ссылки у объектов (ksHyperLinkTypeEnum::ksHLUnknown - не учитывать тип ссылки).
    \param[in] linkObject - объект, на который должна указывать гиперссылка (для linkType == ksHyperLinkTypeEnum::ksHLObject).
    \param[in] level - уровень гиперссылки (-1 - не учитывать уровень).
    \param[in] text - текст гиперссылки (пустая строка - не учитывать текст).
    \return Массив объектов с гиперссылкой.
  */
  virtual std::vector<IDrawingObjectPtr> GetHyperLinkObjects(ksHyperLinkTypeEnum linkType, const IDrawingObjectPtr & linkObject,
                                                             int32_t level, const std::wstring & text) = 0;
  /// Удалить гиперссылки у указанных объектов.
  virtual bool DeleteHyperLinks(const std::vector<IDrawingObjectPtr> & objects) = 0;
  /// Получить признак нахождения документа в режиме редактирования макроэлемента.
  virtual bool IsEditMacroVisibleRegime() = 0;
  /// Получить объект по уникальному идентификатору.
  virtual IDrawingObjectPtr GetObjectById(int64_t id) = 0;
  /// Получить объект процесса.
  virtual IProcess2DPtr GetLibProcess(ksProcess2DTypeEnum processType) = 0;
  /**
    \brief Найти ближайший объект к заданной точке, удовлетворяющий параметрам поиска.
    \param[in] x, y - координаты точки для поиска объекта.
    \param[in] limit - максимальное расстояние от указанной точки до объекта.
    \param[in] param - параметры поиска объектов, можно получить методом GetInterface (тип KompasAPIObjectTypeEnum::ksObjectFindObjectParameters).
    \return Найденный объект.
  */
  virtual IDrawingObjectPtr FindObject(double x, double y, double limit, const IFindObjectParametersPtr & param) = 0;
  /**
    \brief Найти ближайшие объекты к заданной точке, удовлетворяющие параметрам поиска.
    \param[in] x, y - координаты точки для поиска объектов.
    \param[in] limit - максимальное расстояние от указанной точки до объектов.
    \param[in] param - параметры поиска объектов, можно получить методом GetInterface (тип KompasAPIObjectTypeEnum::ksObjectFindObjectParameters).
    \return Найденные объекты.
  */
  virtual std::vector<IDrawingObjectPtr> FindObjects(double x, double y, double limit,
                                                     const IFindObjectParametersPtr & param) = 0;
  /**
    \brief Получить объекты с помощью выделения прямоугольником.
    \param[in] regionType - способ выбора относительно заданного прямоугольника.
    \param[in] minX, minY - координаты левой нижней вершины прямоугольника.
    \param[in] maxX, maxY - координаты правой верхней вершины прямоугольника.
    \return Найденные объекты.
  */
  virtual std::vector<IDrawingObjectPtr> SelectObjects(ksRegionTypeEnum regionType, double minX, double minY, double maxX,
                                                       double maxY) = 0;
  /// Получить массив интервальных переменных.
  virtual std::vector<IVariablePtr> GetIntervalVariables() = 0;
  /**
    \brief Создать интервальную переменную и добавить переменную в массив переменных и документ.
    \param[in] name - имя переменной.
    \param[in] firstValue - первое значение интервала переменной.
    \param[in] secondValue - второе значение интервала переменной.
    \return Созданная переменная.
  */
  virtual IVariablePtr AddIntervalVariable(const std::wstring & name, double firstValue, double secondValue) = 0;
  /// Получить интервальную переменную по индексу.
  virtual IVariablePtr GetIntervalVariable(int32_t index) = 0;
  /// Получить интервальную переменную по имени.
  virtual IVariablePtr GetIntervalVariableByName(const std::wstring & name) = 0;
  /// Получить массив функциональных переменных.
  virtual std::vector<IVariablePtr> GetUserFuncVariables() = 0;
  /**
    \brief Создать функциональную переменную, добавить её в массив переменных и документ.
    \param[in] name - имя переменной.
    \param[in] expression - выражение в виде строки для вычисления значения переменной.
               Например, d>=10?1:1.5 - значение равно 1, если параметр d >= 10, иначе значение равно 1.5.
    \return Созданная переменная.
  */
  virtual IVariablePtr AddUserFuncVariable(const std::wstring & name, const std::wstring & expression) = 0;
  /// Получить функциональную переменную по индексу.
  virtual IVariablePtr GetUserFuncVariable(int32_t index) = 0;
  /// Получить функциональную переменную по имени.
  virtual IVariablePtr GetUserFuncVariableByName(const std::wstring & name) = 0;
  /// Очистить Undo контейнер.
  virtual bool ClearUndo() = 0;
  /// Установить признак добавления команд в Undo-контейнер (true - добавлять, false - не добавлять).
  virtual void SetEnableUndo(bool enable) = 0;
  /// Получить признак добавления команд в Undo-контейнер (true - команды добавляются, false - не добавляются).
  virtual bool IsEnableUndo() = 0;
  /**
    \brief Установить признак объединения команд в Undo-контейнере.
    \details После вызова метода с beginContainer == true команды будут добавлятся в отдельный контейнер.
             Существует счётчик вызовов метода (при beginContainer == true счётчик увеличивается, 
             при beginContainer == false - уменьшается). 
             Контейнер с накопленными командами попадёт в Undo-список после вызова метода с beginContainer == false и
             установки вышеуказанного счётчика в нулевое значение.
             При выполнении Undo, команды из контейнера выполнятся в обратном порядке.
             При выполнении Redo, выполнится только первая команда из контейнера.
    \param[in] beginContainer - признак объединения команд в Undo-контейнере.
  */
  virtual void SetUndoContainer(bool beginContainer) = 0;
  /// Получить признак объединения команд в Undo-контейнере (true - команды объединяются, false - не объединяются).
  virtual bool IsUndoContainer() = 0;
  /// Разрушить объекты.
  virtual bool DestroyObjects(const std::vector<IKompasAPIObjectPtr> & objects) = 0;
  /**
    \brief Изменить порядок отрисовки объектов документа.
    \param[in] objects - объекты, для которых меняется порядок.
    \param[in] orderObject - объект, относительно которого меняется порядок.
    \param[in] orderType - тип изменения порядка объектов.
    \return Успешность выполнения.
  */
  virtual bool ChangeObjectsOrder(const std::vector<IKompasAPIObjectPtr> & objects, const IDrawingObjectPtr & orderObject,
                                  ksChangeOrderType orderType) = 0;
  /// Получить признак нахождения в режиме редактирования библиотечного элемента.
  virtual bool IsLibraryEditMode() = 0;
  /**
    \brief Запустить визуальный процесс создания объекта по типу объекта (параметры создаваемого объекта задаются пользователем).
    \param[in] objectType - тип создаваемого объекта.
    \return Созданный объект.
  */
  virtual IDrawingObjectPtr VisualCreateObject(DrawingObjectTypeEnum objectType) = 0;
  /**
    \brief Запустить визуальный процесс создания объекта по типу процесса (параметры создаваемого объекта задаются пользователем).
    \param[in] processType - тип процесса.
    \return Созданный объект.
  */
  virtual IDrawingObjectPtr RunCreateObjectProcess(ProcessTypeEnum processType) = 0;
  /**
    \brief Запустить визуальный процесс редактирования объекта (параметры редактирования задаются пользователем).
    \param[in] object - редактируемый объект.
    \return Успешность редактирования.
  */
  virtual bool VisualEditObject(const IDrawingObjectPtr & object) = 0;
  /// Получить радиус окружности вписанной в ловушку курсора.
  virtual double GetCursorLimit() = 0;
  /**
    \brief Запустить процесс вставки документа из файла или библиотеки документов (параметры вставки задаются пользователем).
    \param[in] fileName - имя файла - источника вставки.
    \param[in] processType - тип процесса вставки (например, ProcessTypeEnum::prInsertFragment или ProcessTypeEnum::prInsertRaster).
    \return Успешность вставки.
  */
  virtual bool ExecuteProcessOfDocumentFromFile(const std::wstring & fileName, ProcessTypeEnum processType) = 0;
  /**
    \brief Получить габариты объекта(ов) (вида, слоя, группы).
    \param[in] fileName - имя файла - источника вставки.
    \param[in] objects - массив объектов для получения габаритов.
    \param[out] x1, y1 - координаты левой нижней точки габаритов объектов.
    \param[out] x2, y2 - координаты правой верхней точки габаритов объектов.
    \return Успешность получения габаритов.
  */
  virtual bool GetObjectsGabarit(const std::vector<IKompasAPIObjectPtr> & objects, double & x1, double & y1, double & x2,
                                 double & y2) = 0;
  /**
    \brief Задать матрицу трансформации для СК документа.
    \param[in] x, y - координаты начальной точки.
    \param[in] angle - угол поворота (в градусах).
    \param[in] scaleX - коэффицент масштабирования по оси X.
    \param[in] scaleY - коэффицент масштабирования по оси Y.
    \return Успешность задания матрицы.
  */
  virtual bool CreateMatrix(double x, double y, double angle, double scaleX, double scaleY) = 0;
  /**
    \brief Удалить последнюю добавленную матрицу трансформации СК документа.
    \return Успешность удаления матрицы (true - матрица удалена, false - произошла ошибка, либо нет добавленных матриц).
  */
  virtual bool DeleteMatrix() = 0;
  /**
    \brief Преобразовать точку из СК вида в локальную СК.
    \param[in] x, y - координаты точки в СК вида.
    \param[out] xn, yn - преобразованные координаты точки в локальной СК документа.
    \return Успешность преобразования точки.
  */
  virtual bool TransformPointIntoMatrix(double x, double y, double & xn, double & yn) = 0;
  /**
    \brief Преобразовать точку из локальной СК в СК вида.
    \param[in] x, y - координаты точки в локальной СК документа.
    \param[out] xn, yn - преобразованные координаты точки СК вида.
    \return Успешность преобразования точки.
  */
  virtual bool TransformPointFromMatrix(double x, double y, double & xn, double & yn) = 0;
  /**
    \brief Преобразовать длину из СК вида в локальную СК документа.
    \details Если по оси X и по оси Y разный масштаб в локальной СК документа, масштаб по оси Y будет проигнорирован.
    \param[in, out] length - преобразовываемая длина.
    \return Успешность преобразования длины.
  */
  virtual bool TransformLengthIntoMatrix(double & length) = 0;
  /**
    \brief Преобразовать длину из локальную СК документа в СК вида.
    \details Если по оси X и по оси Y разный масштаб в локальной СК документа, масштаб по оси Y будет проигнорирован.
    \param[in, out] length - преобразовываемая длина.
    \return Успешность преобразования длины.
  */
  virtual bool TransformLengthFromMatrix(double & length) = 0;
  /**
    \brief Преобразовать угол из СК вида в локальную СК документа.
    \param[in, out] angle - преобразовываемый угол (в градусах).
    \return Успешность преобразования угла.
  */
  virtual bool TransformAngleIntoMatrix(double & angle) = 0;
  /**
    \brief Преобразовать угол из локальной СК документа в СК вида.
    \param[in, out] angle - преобразовываемый угол (в градусах).
    \return Успешность преобразования угла.
  */
  virtual bool TransformAngleFromMatrix(double & angle) = 0;
  /**
    \brief Трансформировать объекты в локальную СК документа.
    \param[in, out] objects - трансформируемые объекты.
    \return Успешность трансформирования.
  */
  virtual bool TransformObjects(const std::vector<IKompasAPIObjectPtr> & objects) = 0;
  /**
    \brief Удалить заданные объекты в заданной области.
    \param[in] clearGroup - группа объектов, среди которых будут удалятся объекты, попавшие в заданную область
               (nullptr - рассматриваются все объекты текущего вида).
    \param[in] regionGroup - группа объектов, определяющих границы области (будут использоваться только кривые).
    \param[in] inside - признак местоположения удаляемых объектов относительно границ (true - внутри, false - снаружи).
    \return Успешность удаления.
  */
  virtual bool ClearRegion(const IDrawingGroupPtr & clearGroup, const IDrawingGroupPtr & regionGroup, bool inside) = 0;
  /**
    \brief Сместить заданные объекты на заданное расстояние.
    \param[in] objects - смещаемые объекты.
    \param[in] dx - смещение по оси X.
    \param[in] dy - смещение по оси Y.
    \return Успешность смещения.
  */
  virtual bool MoveObjects(const std::vector<IKompasAPIObjectPtr> & objects, double dx, double dy) = 0;
  /**
    \brief Повернуть заданные объекты.
    \param[in] objects - поворачиваемые объекты.
    \param[in] x, y - координаты точки, относительно которой будет совершаться поворот.
    \param[in] angle - угол поворота.
    \return Успешность поворота.
  */
  virtual bool RotateObjects(const std::vector<IKompasAPIObjectPtr> & objects, double x, double y, double angle) = 0;
  /**
    \brief Отразить объекты относительно заданной оси симметрии.
    \param[in] objects - отражаемые объекты.
    \param[in] x1, y1 - координаты первой точки оси симметрии.
    \param[in] x2, y2 - координаты второй точки оси симметрии.
    \param[in] copy - признак копирования объектов (true - симметрия с копированием, false - симметрия без копирования).
    \param[in] textSymmetry - признак отражения текста (true - отражать текст, false - не отражать).
    \param[in] copyAttributes - признак копирования атрибутов при симметрии копированием (true - копировать атрибуты, false - не копировать).
    \return Группа отражённых объектов.
  */
  virtual IKompasAPIObjectPtr SymmetryObjects(const std::vector<IKompasAPIObjectPtr> & objects, double x1, double y1, double x2,
                                              double y2, bool copy, bool textSymmetry, bool copyAttributes) = 0;
  /// Установить признак необходимости перестроения дерева при изменении его состава (true - перестраивать, false - не перестраивать).
  virtual void SetTreeNeedRebuild(bool needRebuild) = 0;
  /// Получить признак необходимости перестроения дерева при изменении его состава (true - перестраивать, false - не перестраивать).
  virtual bool IsTreeNeedRebuild() = 0;
  /// Установить признак необходимости обновления узлов дерева при изменении свойств и состояний объектов документа (true - обновлять, false - не обновлять).
  virtual void SetTreeNeedUpdateItems(bool needUpdate) = 0;
  /// Получить признак необходимости обновления узлов дерева при изменении свойств и состояний объектов документа (true - обновляется, false - не обновляется).
  virtual bool IsTreeNeedUpdateItems() = 0;
  /**
    \brief Проверить и восстановить ассоциативность объектов.
    \param[in] dimensionTypes - массив типов размеров из перечисления DrawingObjectTypeEnum (ksAllObj - проверять все размеры).
       Возможные типы: ksDrLDimension, ksDrLBreakDimension, ksDrADimension, ksDrABreakDimension, ksDrDDimension, 
      ksDrRDimension, ksDrRBreakDimension, ksDrOrdinateDimension, ksDrArcDimension.
    \param[in] checkType - тип проверяемых объектов.
    \param[in] checkStyle - стили проверяемых объектов (ksCheckAllStyles - все стили).
    \param[out] completeAssocCount - количество объектов для которых создана ассоциативная связь.
    \param[out] incompleteAssocCount - количество объектов с неполной ассоциативной связью.
    \return Результат проверки ассоциативности объектов.
  */
  virtual ksCheckAssociationResultEnum CheckAssociation(const std::vector<DrawingObjectTypeEnum> & dimensionTypes,
                                                        ksCheckObjectsTypeEnum checkType,
                                                        const std::vector<ksCheckStyleEnum> & checkStyle,
                                                        int32_t & completeAssocCount, int32_t & incompleteAssocCount) = 0;
  /// Получить группу графических объектов, определяющих область выделения, используя визуальный процесс (рассчитать площадь указанных объектов).
  virtual IDrawingGroupPtr ViewGetObjectsArea() = 0;
  /**
    \brief Аппроксимировать кривую дугами и отрезками.
    \param[in] curve - кривая для аппроксимации.
    \param[in] epsilon - погрешность вычисления.
    \param[in] curentLayer - тип размещения (true - в текущий слой, false - на слой кривой).
    \param[in] maxRadius - максимальный радиус аппроксимации (0 - ограничение не накладывается).
    \param[in] smooth - признак гладкого споряжения (true - гладкое сопряжение, false - не гладкое сопряжение).
    \return Aпроксимированная кривая.
  */
  virtual IDrawingObjectPtr CreateApproximationCurve(const IDrawingObjectPtr & curve, double epsilon, bool curentLayer,
                                                     double maxRadius, bool smooth) = 0;
  /// Установить параметрические ограничения на список объектов.
  virtual bool ParametrizeObjects(const std::vector<IKompasAPIObjectPtr> & objects, const IParametrizationParamPtr & param) = 0;

  /// Установить признак активности параметрического режима.
  virtual void SetParametricMode(bool enable) = 0;
  /// Получить признак активности параметрического режима.
  virtual bool IsParametricMode() = 0;

  /// Установить признак активности ортогонального черчения.
  virtual void SetOrthogonalMode(bool enable) = 0;
  /// Получить признак активности ортогонального черчения.
  virtual bool IsOrthogonalMode() = 0;

  /// Запретить удаление временных объектов после завершения выполнения команды библиотеки.
  virtual bool KeepTemporaryObjects(const std::vector<IKompasAPIObjectPtr> & objects) = 0;

  /**
    \brief Усечь кривую по координатам.
    \param[in] curve - исходная кривая.
    \param[in] x1, y1 - первая точка (её проекция на кривую) для усечения.
    \param[in] x2, y2 - вторая точка (её проекция на кривую) для усечения.
    \param[in] x3, y3 - точка между первыми двумя (её проекция на кривую) для определения направления замкнутой кривой.
    \param[in] trimType - тип усечения.
    \return результирующая кривая в случае успеха, nullptr в случае неудачи.
  */
  virtual IDrawingObjectPtr TrimCurve(const IDrawingObjectPtr & curve, double x1, double y1, double x2, double y2, double x3,
                                      double y3, ksCurveTrimTypeEnum trimType) = 0;
  /**
    \brief Усечь кривую по параметрам.
    \param[in] curve - исходная кривая.
    \param[in] tMin, tMax - параметры точек на кривой для усечения.
    \param[in] tMiddle - параметр точки между первыми двумя для определения направления замкнутой кривой.
    \param[in] trimType - тип усечения.
    \return результирующая кривая в случае успеха, nullptr в случае неудачи.
  */
  virtual IDrawingObjectPtr TrimCurveByParam(const IDrawingObjectPtr & curve, double tMin, double tMax, double tMiddle,
                                             ksCurveTrimTypeEnum trimType) = 0;
};

