////////////////////////////////////////////////////////////////////////////////
//
/// Ассоциативный вид.
/**
  Ассоциативный вид чертежа содержит изображение объектов модели и созданных в ней элементов оформления.
*/
////////////////////////////////////////////////////////////////////////////////
struct IAssociationView : IView
{
  /// Получить полное имя файла-источника.
  virtual std::wstring GetSourceFileName() = 0;
  /// Установить полное имя файла-источника.
  virtual void SetSourceFileName(const std::wstring & fileName) = 0;
  /// Получить имя проекции.
  virtual std::wstring GetProjectionName() = 0;
  /// Установить имя проекции.
  virtual void SetProjectionName(const std::wstring & name) = 0;
  /// Получить признак разнесенности сборки.
  virtual bool IsExplodedView() = 0;
  /// Установить признак разнесенности сборки.
  virtual void SetExplodedView(bool explodedView) = 0;
  /// Масштабировать аннотационные объекты вида.
  virtual void SetDimensionLayoutScaling(bool dimensionLayoutScaling) = 0;
  /// Получить признак проекционной связи.
  virtual bool IsProjectionLink() = 0;
  /// Установить признак проекционной связи.
  virtual void SetProjectionLink(bool projectionLink) = 0;
  /// Получить признак разрез-сечение.
  virtual bool IsSection() = 0;
  /// Установить признак разрез-сечение.
  virtual void SetSection(bool section) = 0;
  /// Получить признак разогнутости листовой детали.
  virtual bool IsUnfold() = 0;
  /// Установить признак разогнутости листовой детали.
  virtual void SetUnfold(bool unfold) = 0;
  /**
    \brief Получить стиль видимых линий.
    \param[in] visibleLinesStyle - стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual int32_t GetVisibleLinesStyle() = 0;
  /**
    \brief Установить стиль видимых линий.
    \param[in] visibleLinesStyle - стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual void SetVisibleLinesStyle(int32_t visibleLinesStyle) = 0;
  /// Получить признак передачи невидимых линии в вид.
  virtual bool IsHiddenLines() = 0;
  /// Установить признак передачи невидимых линии в вид.
  virtual void SetHiddenLines(bool hiddenLines) = 0;
  /// Получить признак отображения невидимых линий.
  virtual bool IsHiddenLinesVisible() = 0;
  /// Установить признак отображения невидимых линий.
  virtual void SetHiddenLinesVisible(bool hiddenLinesVisible) = 0;
  /**
    \brief Получить стиль невидимых линий.
    \return стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual int32_t GetHiddenLinesStyle() = 0;
  /**
    \brief Установить стиль невидимых линий.
    \param[in] hiddenLinesStyle - стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual void SetHiddenLinesStyle(int32_t hiddenLinesStyle) = 0;
  /// Получить признак отображения линии перехода.
  virtual bool IsBreakLinesVisible() = 0;
  /// Установить признак отображения линии перехода.
  virtual void SetBreakLinesVisible(bool breakLinesVisible) = 0;
  /**
    \brief Получить стиль линий перехода.
    \return стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual int32_t GetBreakLinesStyle() = 0;
  /**
    \brief Установить стиль линий перехода.
    \param[in] breakLinesStyle - стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual void SetBreakLinesStyle(int32_t breakLinesStyle) = 0;
  /// Получить признак отображения линии сгиба.
  virtual bool IsBendLinesVisible() = 0;
  /// Установить признак отображения линии сгиба.
  virtual void SetBendLinesVisible(bool bendLinesVisible) = 0;
  /**
    \brief Получить стиль линий сгиба.
    \return стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual int32_t GetBendLinesStyle() = 0;
  /**
    \brief Установить стиль линий сгиба.
    \param[in] bendLinesStyle - стиль линий (значения системных стилей линий: ksCurveStyleEnum).
  */
  virtual void SetBendLinesStyle(int32_t bendLinesStyle) = 0;
  /// Получить опорный вид.
  virtual IViewPtr GetBaseView() = 0;
  /// Установить опорный вид.
  virtual void SetBaseView(const IViewPtr & baseView) = 0;
  /// Получить признак местного вида.
  virtual bool IsLocal() = 0;
  /// Установить признак местного вида.
  virtual void SetLocal(bool local) = 0;
  /// Создать местный вид.
  virtual bool CreateLocalView(const IDrawingObjectPtr & contour) = 0;
  /// Получить признак одинаковой штриховки всех деталей сборки (используется только в виде разреза\сечения).
  virtual bool IsSameHatch() = 0;
  /// Установить признак одинаковой штриховки всех деталей сборки (используется только в виде разреза\сечения).
  virtual void SetSameHatch(bool sameHatch) = 0;
  /**
    \brief Получить матрицу ассоциативного вида.
    \return Матрица, построчно записанная в массив (всего 16 значений).
  */
  virtual std::vector<double> GetProjectionMatrix() = 0;
  /**
    \brief Установить матрицу ассоциативного вида.
    \param[in] projectionMatrix - матрица, построчно записанная в массив (всего 16 значений).
  */
  virtual void SetProjectionMatrix(const std::vector<double> & projectionMatrix) = 0;
  /// Получить признак отображения осевых линий.
  virtual bool IsCenterLinesVisible() = 0;
  /// Установить признак отображения осевых линий.
  virtual void SetCenterLinesVisible(bool centerLinesVisible) = 0;
  /**
    \brief Получить признак чернового проецирования. При включенном черновом проецировании создание вида выполняется быстрее, 
      однако относительно мелкие в масштабах модели объекты могут не спроецироваться в чертеж.
    \return Флаг - признак чернового проецирования.
   */
  virtual bool IsUseOcclusion() = 0;
  /**
    \brief Установить признак чернового проецирования. При включенном черновом проецировании создание вида выполняется быстрее, 
      однако относительно мелкие в масштабах модели объекты могут не спроецироваться в чертеж.
      Опция доступна, если линии невидимого контура не показываются в виде.
    \param[in] useOcclusion - признак чернового проецирования. 
   */
  virtual void SetUseOcclusion(bool useOcclusion) = 0;
  /**
    \brief Получить массив ассоциативных объектов по 3D объекту.
    \param[in] modelObject - объект, относительно которого ищутся ассоциативные объекты.
    \return Массив найденых ассоциативных объектов.
   */
  virtual std::vector<IKompasAPIObjectPtr> GetAssociationObjects(const IModelObjectPtr & modelObject) = 0;
  /**
    \brief Получить признак видимости ассоциативных объектов по 3D объекту.
    \param[in] modelObject - объект, для которого возвращается признак видимости его ассоциативных объектов.
    \return Признак видимости ассоциативных объектов.
   */
  virtual bool IsAssociationObjectsVisible(const IModelObjectPtr & modelObject) = 0;
  /**
    \brief Получить массив рёбер грани, по точке на грани.
    \param[in] x, y - координаты точки на грани текущей системы координат вида.
    \return Массив искомых рёбер.
   */
  virtual std::vector<IDrawingObjectPtr> FindFaceEdges(double x, double y) = 0;
  /**
    \brief Получить массив граней, по точке на ней.
    \param[in] x, y - координаты точки на грани текущей системы координат вида.
    \param[in] document3D - документ, в котором следует искать грань.
    \return Искомая грань.
   */
  virtual IModelObjectPtr FindFace(double x, double y, const IKompasDocument3DPtr & document3D) = 0;
  /**
    \brief Получить координаты точки на виде по 3D коодинатам модели.
    \param[in] x, y, z - координаты точки в текущей системе координат.
    \param[out] xV, yV - координаты точки в текущей системы координат вида.
    \return Успешность получения координат.
   */
  virtual bool GetProjectionPoint(double x, double y, double z, double & xV, double & yV) = 0;
  /**
    \brief Получить флаг видимости проекции точки на виде с разрывами.
    \param[in] x, y, z - координаты точки в текущей системе координат.
    \return Флаг видимости проекции запрашиваемой точки на виде (true - видна, false - не видна).
   */
  virtual bool IsViewProjectionPointInBreakView(double x, double y, double z) = 0;
  /**
    \brief Восстановить стили объектов ассоциативного вида на значения по умолчанию.
    \return Успешность восстановления стилей объектов вида.
   */
  virtual bool RestoreStyles() = 0;
  /**
    \brief Установить массив проецируемых объектов. Вставка или тела.
    \param[in] objects - массив проецируемых на вид объектов. Если массив пустой, проецируется весь документ.
    \return Успешность установления проецируемых объектов.
   */
  virtual bool SetProjectionObjects(const std::vector<IModelObjectPtr> & objects) = 0;
  /// Получить массив проецируемых объектов. Вставка или тела.
  virtual std::vector<IModelObjectPtr> GetProjectionObjects(const IKompasDocument3DPtr & document3D) = 0;
  /// Перестроить вид.
  virtual bool Rebuild() = 0;
  /// Получить признак использования параметров ассоциативной штриховки из модели.
  virtual bool IsHatchParametersFromModel() = 0;
  /// Установить признак использования параметров ассоциативной штриховки из модели.
  virtual void SetHatchParametersFromModel(bool fromModel) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Копия геометрии.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct ICopyGeometry : IModelObject
{
  /// Установить исходные объекты массива.
  virtual void SetInitialObjects(const std::vector<IModelObjectPtr> & objects) = 0;
  /// Получить исходные объекты массива.
  virtual std::vector<IModelObjectPtr> GetInitialObjects() = 0;
  /// Разрушить массив.
  virtual bool Destroy() = 0;
  /// Проверить исходный ли объект для массива.
  virtual bool IsInitialObject(const IModelObjectPtr & object) = 0;
  /// Добавить объекты в массив копируемых объектов.
  virtual bool AddInitialObjects(const std::vector<IModelObjectPtr> & objects) = 0;
  /// Добавить объекты из файла в массив копируемых объектов.
  virtual bool AddInitialObjectsFromExternalDocument(const IKompasDocument3DPtr & externalDocument,
                                                     const ILocalCoordinateSystemPtr & externalLocalCS,
                                                     const std::vector<IModelObjectPtr> & objects) = 0;
  /// Очистить список исходных объектов массива.
  virtual bool Clear() = 0;
  /// Проверить пригодность объекта для операции.
  virtual bool IsSuitableObject(const IModelObjectPtr & object) = 0;
  /// Получить признак работы в контексте (true - работаем в контексте, false - по внешнему документу).
  virtual bool IsContextObjects() = 0;
  /// Установить признак работы в контексте (true - работаем в контексте, false - по внешнему документу).
  virtual void SetContextObjects(bool contextObjects) = 0;
  /// Получить имя файла внешнего документа.
  virtual std::wstring GetDocumentFileName() = 0;
  /// Открыть документ-источник на редактирование.
  virtual IKompasDocument3DPtr OpenDocument(bool visible, bool readOnly) = 0;
  /// Получить систему координат.
  virtual ILocalCoordinateSystemPtr GetLocalCS() = 0;
  /// Установить систему координат.
  virtual void SetLocalCS(const ILocalCoordinateSystemPtr & localCS) = 0;
  /// Получить систему координат внешнего документа.
  virtual ILocalCoordinateSystemPtr GetExternalLocalCS() = 0;
  /// Установить систему координат внешнего документа.
  virtual void SetExternalLocalCS(const ILocalCoordinateSystemPtr & externalLCS) = 0;
  /// Получить режим копирования коллекции геометрии.
  virtual bool IsByCollectionGeometry() = 0;
  /// Установить режим копирования коллекции геометрии.
  virtual void SetByCollectionGeometry(bool byCollectionGeometry) = 0;
  /// Получить копируемую коллекцию геометрии.
  virtual ICollectionGeometryPtr GetCollectionGeometry() = 0;
  /// Установить копируемую коллекцию геометрии.
  virtual void SetCollectionGeometry(const ICollectionGeometryPtr & collectionGeometry) = 0;
  /// Получить признак зеркального копирования.
  virtual bool IsMirrorCopy() = 0;
  /// Установить признак зеркального копирования.
  virtual void SetMirrorCopy(bool mirrorCopy) = 0;
  /// Получить способ построения операции.
  virtual ksCopyGeometryBuildingTypeEnum GetBuildingType() = 0;
  /// Установить способ построения операции.
  virtual void SetBuildingType(ksCopyGeometryBuildingTypeEnum buildingType) = 0;
  /// Получить признак автоматического обновления.
  virtual bool IsAutoUpdate() = 0;
  /// Установить признак автоматического обновления.
  virtual void SetAutoUpdate(bool autoUpdate) = 0;
  /// Получить признак слежения за источником.
  virtual bool IsWatchForSourceChange() = 0;
  /// Установить признак слежения за источником.
  virtual void SetWatchForSourceChange(bool watchForSourceChange) = 0;
  /// Обновить по источнику.
  virtual bool Synchronize() = 0;
  /// Получить массив копируемых объектов из внешнего документа.
  virtual std::vector<IModelObjectPtr> GetExternalInitialObjects(const IKompasDocument3DPtr & externalDocument3D) = 0;
  /// Получить систему координат из внешнего документа.
  virtual ILocalCoordinateSystemPtr GetExternalLocalCoordinateSystem(const IKompasDocument3DPtr & externalDocument3D) = 0;
  /// Получить признак изменения направления для копируемого объекта.
  virtual bool IsInitialObjectReverseDirection(const IModelObjectPtr & object) = 0;
  /// Установить признак изменения направления для копируемого объекта.
  virtual bool SetInitialObjectReverseDirection(const IModelObjectPtr & object, bool reverseDirection) = 0;
  /// Получить признак изменения направления для коллекции геометрии.
  virtual bool IsCollectionGeometryReverseDirection() = 0;
  /// Установить признак изменения направления для коллекции геометрии.
  virtual bool SetCollectionGeometryReverseDirection(bool reverseDirection) = 0;
};

