  /// Получить коллекцию пользовательских объектов 3D.
  virtual IUserObjects3DPtr GetUserObjects() = 0;
  /// Получить коллекцию отверстий 3D.
  virtual IHoles3DPtr GetHoles3D() = 0;
  /// Получить коллекцию фасок.
  virtual IChamfersPtr GetChamfers() = 0;
  /// Получить коллекцию операций скруглений.
  virtual IFilletsPtr GetFillets() = 0;
  /// Получить коллекцию операций уклонов.
  virtual IInclinesPtr GetInclines() = 0;
  /// Получить коллекцию ребер жесткости.
  virtual IRibsPtr GetRibs() = 0;
  /// Получить коллекцию операций оболочек.
  virtual IShellsPtr GetShells() = 0;
  /// Получить коллекцию булевых операций.
  virtual IBooleansPtr GetBooleans() = 0;
  /// Получить коллекцию операций сечений.
