////////////////////////////////////////////////////////////////////////////////
//
/// Коллекция групп слоев в 3D.
/**
  Коллекция может быть коллекцией динамических и нединамических групп.
  Нединамические группы могут содержать вложенные коллекции групп слоёв. 
  Динамическая группа слоёв содержит слои, удовлетворяющие условиям фильтрации, 
    заданным с помощью интерфейса ILayerFilterConditions.
  Динамическая группа формируется автоматически, и включает в себя все слои, удовлетворяющие условиям фильтрации.
*/
////////////////////////////////////////////////////////////////////////////////
struct ILayerGroups3D : IKompasCollection
{
  /// Получить группу по индексу.
  virtual ILayerGroup3DPtr GetLayerGroup3D(int32_t index) = 0;
  /// Получить группу по имени.
  virtual ILayerGroup3DPtr GetLayerGroup3DByName(const std::wstring & name) = 0;
  /// Получить группу по уникальному идентификатору.
  virtual ILayerGroup3DPtr GetLayerGroup3DById(NumericId uniqueId) = 0;
  /// Создать группу и добавить её в коллекцию.
  virtual ILayerGroup3DPtr Add() = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Группа слоев в 3D.
/**
  Группа может быть динамической или нединамической (в зависимости, из какой коллекции она создана).
  Нединамические группы слоёв могут содержать вложенные коллекции групп слоёв.
  Динамическая группа слоёв содержит слои, удовлетворяющие условиям фильтрации, 
    заданным с помощью интерфейса ILayerFilterConditions.
  Динамическая группа формируется автоматически, и включает в себя все слои, удовлетворяющие условиям фильтрации.
*/
////////////////////////////////////////////////////////////////////////////////
struct ILayerGroup3D : IKompasAPIObject
{
  /// Получить владельца группы слоёв (другая группа слоёв, или nullptr).
  virtual ILayerGroup3DPtr GetOwnerGroup() = 0;
  /// Получить вложенную коллекцию групп слоёв (только для нединамических групп).
  virtual ILayerGroups3DPtr GetLayerGroups() = 0;
  /// Получить коллекцию слоёв текущей группы.
  virtual ILayers3DPtr GetLayers() = 0;
  /// Установить имя группы слоёв.
  virtual void SetName(const std::wstring & name) = 0;
  /// Получить имя группы слоёв.
  virtual std::wstring GetName() = 0;
  /// Удалить группу слоёв.
  virtual bool Delete() = 0;
  /// Получить уникальный идентификатор группы слоёв.
  virtual NumericId GetUniqueId() = 0;
  /// Получить коллекцию условий фильтрации (для динамических групп).
  virtual ILayerFilterConditionsPtr GetLayerFilterConditions() = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Cтроительная ось (базовый класс строительных осей).
/**
 
*/
////////////////////////////////////////////////////////////////////////////////
struct IBuildingAxis : IDrawingObject
{
  /// Установить тип марки (true - двойная, false - одинарная).
  virtual void SetDoubleMark(bool mark) = 0;
  /// Получить тип марки (true - двойная, false - одинарная).
  virtual bool IsDoubleMark() = 0;
  /// Установить размер марки (значения параметра пересчитываются в зависимости от текущей системы координат для объекта).
  virtual void SetMarkSize(double size) = 0;
  /// Получить размер марки (значения параметра пересчитываются в зависимости от текущей системы координат для объекта).
  virtual double GetMarkSize() = 0;
  /// Установить длину пунктира.
  virtual void SetDottedLength(double length) = 0;
  /// Получить длину пунктира.
  virtual double GetDottedLength() = 0;
  /// Установить длину промежутка.
  virtual void SetInterval(double interval) = 0;
  /// Получить длину промежутка.
  virtual double GetInterval() = 0;
  /// Установить длину штриха.
  virtual void SetStroke(double stroke) = 0;
  /// Получить длину штриха.
  virtual double GetStroke() = 0;
  /// Получить текст обозначения оси.
  virtual ITextPtr GetText() = 0;
  /// Получить текст перед обозначением оси.
  virtual ITextPtr GetTextBefore() = 0;
  /// Получить текст после обозначения оси.
  virtual ITextPtr GetTextAfter() = 0;
  /// Установить признак автоопределения длины штриха.
  virtual void SetAutoStroke(bool autoStroke) = 0;
  /// Получить признак автоопределения длины штриха.
  virtual bool IsAutoStroke() = 0;

  /**
    \brief Получить координаты точек для вставки дополнительных элементов.
    \param[in] first - true для первого ответвления, false для второго ответвления.
    \param[out] points - массив координат точек для подключения дополнительных узлов марок.
    \param[out] directions - массив направлений (углы относительно центра родительского узла).
    \param[out] nodes - массив родительских узлов для точек подключения.
    \return Успешность получения.
  */
  virtual bool GetInsertionPoints(bool first, std::vector<double> & points, std::vector<double> & directions,
                                  std::vector<IMarkNodePtr> & nodes) = 0;
  /// Получить узел марки по координатам (limit - максимальное расстояние от точки до узла при поиске).
  virtual IMarkNodePtr GetNodeByPoint(double x, double y, double limit) = 0;
  /// Добавить узел марки по координатам.
  virtual IMarkNodePtr AddNodeByPoint(ksMarkNodeEnum nodeType, double x, double y) = 0;
};

