////////////////////////////////////////////////////////////////////////////////
//
/// Узел для вставки дополнительных марок.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IMarkNode : IKompasAPIObject
{
  /// Установить тип узла марки.
  virtual void SetMarkType(ksMarkNodeEnum markType) = 0;
  /// Получить тип узла марки.
  virtual ksMarkNodeEnum GetMarkType() = 0;
  /// Установить признак двойной окружности узла (для окружностей, true - двойная, false - одинарная).
  virtual void SetDoubleMark(bool doubleMark) = 0;
  /// Получить признак двойной окружности узла (для окружностей, true - двойная, false - одинарная).
  virtual bool IsDoubleMark() = 0;
  /// Установить длину указателя.
  virtual void SetRefLength(double refLength) = 0;
  /// Получить длину указателя.
  virtual double GetRefLength() = 0;
  /// Получить текст обозначения.
  virtual ITextPtr GetText() = 0;
  /// Получить коллекцию узлов марок (true - слева, false - справа по направлению оси).
  virtual IMarkNodesPtr GetMarkNodes(bool left) = 0;
  /// Удалить узел.
  virtual bool Delete() = 0;
  /**
    \brief Получить координаты точек для вставки дополнительных элементов.
    \details Значения координат и направлений пересчитываются в зависимости от текущей системы координат для объекта.
    \param[in] leftJut - true - для координат точек левого ответвления, false - для правого; \n
                         для круглой оси нужно передавать true.
    \param[out] points - массив координат точек для подключения дополнительных узлов марок.
    \param[out] directions - массив направлений (углы относительно центра родительского узла, в градусах).
    \return Успешность выполнения операции.
  */
  virtual bool GetInsertionPoints(bool leftJut, std::vector<double> & points, std::vector<double> & directions) = 0;
};

