  virtual void SetOnlyThinLine(bool onlyThinLine) = 0;
  /// Получить способ отрисовки объектов (true - только тонкими линиями, false - как в оригинале).
  virtual bool IsOnlyThinLine() = 0;
  /// Установить диапазон листов документа для сохранения в растр.
  virtual void SetSheetsRange(ksSheetsRangeEnum range) = 0;
  /// Получить диапазон листов документа для сохранения в растр.
