  /// Удалить пользовательскую проекцию.
  virtual bool Delete() = 0;
  /// Создать пользовательскую проекцию.
  virtual bool Update() = 0;
  /// Установить признак активности динамического сечения (true - динамическое сечение включено, false - выключено).
  virtual void SetApplyDynamicCrossSection(bool applyDynamicCrossSection) = 0;
  /// Получить признак активности динамического сечения (true - включить динамическое сечение, false - выключить).
  virtual bool IsApplyDynamicCrossSection() = 0;
  /// Установить динамическое сечение.
