////////////////////////////////////////////////////////////////////////////////
//
/// Параметры линейчатой поверхности 'По двум кривым'.
/**
  Дополнительный интерфейс для IRuledSurface.
*/
////////////////////////////////////////////////////////////////////////////////
struct IRuledSurfaceParametersByCurves : IKompasAPIObject
{
  /// Установить первую цепочку кривых.
  virtual void SetCurves1(const std::vector<IModelObjectPtr> & curves) = 0;
  /// Получить первую цепочку кривых.
  virtual std::vector<IModelObjectPtr> GetCurves1() = 0;
  /// Установить вторую цепочку кривых.
  virtual void SetCurves2(const std::vector<IModelObjectPtr> & curves) = 0;
  /// Получить вторую цепочку кривых.
  virtual std::vector<IModelObjectPtr> GetCurves2() = 0;
  /// Установить признак автоматического разбиения результирующей поверхности на грани (true - автоматическое, false - пользовательское).
  virtual void SetAutoSegmentation(bool autoSegmentation) = 0;
  /// Получить признак автоматического разбиения результирующей поверхности на грани (true - автоматическое, false - пользовательское).
  virtual bool IsAutoSegmentation() = 0;
  /// Добавить ребро после указанного индексом.
  virtual bool AddNewEdge(int32_t index) = 0;
  /// Удалить ребро по индексу.
  virtual bool DeleteEdge(int32_t index) = 0;
  /// Получить количество ребер.
  virtual int32_t GetEdgesCount() = 0;
  /**
    \brief Установить параметры вершины ребра поверхности.
    \details Если задан объект ассоциативной точки (associateVertex), параметр (t) и координаты точки (x, y, z) будут проигнорированы.
             Если задан параметр (t) и не задан объект ассоциативной точки (associateVertex), координаты точки (x, y, z) будут проигнорированы.
             Если не задан объект ассоциативной точки (associateVertex) и параметр (t), будут использованы координаты точки (x, y, z).
    \param[in] edgeIndex - индекс ребра для установки параметров его вершины.
    \param[in] startPoint - признак, на какой цепочке кривых лежит вершина (true - на первой, false - на второй).
    \param[in] x, y, z - координаты точки (проекция этой точки на заданный сегмент станет новой вершиной ребра).
    \param[in] t - параметр новой вершины на заданном сегменте. Если задан параметр, координаты будут проигнорированы.
    \param[in] segment - сегмент цепочки кривых, которому принадлежит задаваемая вершина.
    \param[in] associateVertex - ассоциативная точка, проекция которой на заданный сегмент станет новой вершиной ребра.
               Ссылка на объект ассоциативной точки сохранится, и вершина ребра будет с ней связана.
    \return Успешность установки параметров вершины ребра поверхности.
  */
  virtual bool SetEdgePointParam(int32_t edgeIndex, bool startPoint, double x, double y, double z,
                                 std::optional<double> t = std::nullopt, const IModelObjectPtr & segment = nullptr,
                                 const IModelObjectPtr & associateVertex = nullptr) = 0;
  /**
    \brief Получить параметры вершины ребра поверхности.
    \param[in] edgeIndex - индекс ребра для установки параметров его вершины.
    \param[in] startPoint - признак, на какой из цепочек кривых лежит вершина (true - на первой, false - на второй).
    \param[out] x, y, z - координата вершины ребра.
    \param[out] t - параметр вершины на заданном сегменте.
    \param[out] segment - сегмент цепочки кривых, которому принадлежит заданная вершина.
    \param[out] associateVertex - ассоциативная точка, связанная с вершиной ребра.
    \return Успешность получения параметров точки ребра поверхности.
  */
  virtual bool GetEdgePointParam(int32_t edgeIndex, bool startPoint, double & x, double & y, double & z, double & t,
                                 IModelObjectPtr & segment, IModelObjectPtr & associateVertex) = 0;
  /**
    \brief Получить параметры вершин рёбер поверхности.
    \details Параметры разбиваются по различным массивам, в зависимости от того, на какой из двух границ сопряжения они лежат.
    \param[out] points1 - массив координат вершин рёбер на первой цепочке кривых.
                points1[i * 3], points1[i * 3 + 1], points1[i * 3 + 2] - координаты вершины для i-го ребра.
    \param[out] t1 - массив параметров вершин рёбер на сегментах первой цепочки кривых. Индексы параметров соотносятся с индексами рёбер.
    \param[out] segments1 - массив сегментов первой цепочки кривых, которым принадлежат вершины. Индексы соотносятся с индексами рёбер.
    \param[out] associateVertexes1 - массив ассоциативных точек, связанных с вершинами рёбер на первой цепочке кривых.
                Индексы ассоциативных вершин соотносятся с индексами рёбер.
    \param[out] points2 - массив координат вершин рёбер на второй цепочке кривых.
                points1[i * 3], points1[i * 3 + 1], points1[i * 3 + 2] - координаты вершины для i-го ребра.
    \param[out] t2 - массив параметров вершин рёбер на сегментах второй цепочки кривых. Индексы параметров соотносятся с индексами рёбер.
    \param[out] segments2 - массив сегментов второй цепочки кривых, которым принадлежат вершины. Индексы соотносятся с индексами рёбер.
    \param[out] associateVertexes2 - массив ассоциативных точек, связанных с вершинами рёбер на второй цепочке кривых.
                Индексы ассоциативных вершин соотносятся с индексами рёбер.
    \return Успешность получения параметров рёбер поверхности.
  */
  virtual bool GetEdgePointParams(std::vector<double> & points1, std::vector<double> & t1,
                                  std::vector<IModelObjectPtr> & segments1, std::vector<IModelObjectPtr> & associateVertexes1,
                                  std::vector<double> & points2, std::vector<double> & t2,
                                  std::vector<IModelObjectPtr> & segments2,
                                  std::vector<IModelObjectPtr> & associateVertexes2) = 0;
  /// Установить способ выравнивания сечения.
  virtual void SetSectionAlignmentType(ksRuledSurfaceSectionAlignmentTypeEnum alignmentType) = 0;
  /// Получить способ выравнивания сечения.
  virtual ksRuledSurfaceSectionAlignmentTypeEnum GetSectionAlignmentType() = 0;
  /// Установить признак разбиения на грани.
  virtual void SetSplitEdges(bool splitEdges) = 0;
  /// Получить признак разбиения на грани.
  virtual bool IsSplitEdges() = 0;
};

