/**
                 
*/
////////////////////////////////////////////////////////////////////////////////
struct IBranchs3D : IAPIObject
{
  /// Получить количество ответвлений.
  virtual int32_t GetBranchCount() = 0;
  /// Получить координаты координаты начала полки или точки привязки.
  virtual bool GetBranchBeginPoint(double & x, double & y, double & z) = 0;
  /// Установить координаты начала полки или точки привязки.
  virtual bool SetBranchBeginPoint(double x, double y, double z) = 0;
  /// Получить координаты конечной точки ответвления.
  virtual bool GetBranchEndPoint(int32_t index, double & x, double & y, double & z) = 0;
  /// Установить координаты конечной точки ответвления.
  virtual bool SetBranchEndPoint(int32_t index, double x, double y, double z) = 0;
  /// Установить массив координат точек ответвления.
  virtual void SetBranchPoints(int32_t index, const std::vector<double> & points) = 0;
  /// Получить массив координат точек ответвления.
  virtual std::vector<double> GetBranchPoints(int32_t index) = 0;
  /// Получить число точек в ответвлении.
  virtual int32_t GetBranchPointsCount(int32_t index) = 0;
  /// Добавить ответвление.
  virtual bool AddBranch(const std::vector<double> & points, const IModelObjectPtr & object) = 0;
  /// Добавить прямолинейное ответвление.
  virtual bool AddBranchByPoint(double x, double y, double z, const IModelObjectPtr & object) = 0;
  /// Удалить ответвление.
  virtual bool DeleteBranch(int32_t index) = 0;
  /// Получить объект на который ссылается ответвление.
  virtual IModelObjectPtr GetBranchObject(int32_t index) = 0;
  /// Получить список объектов.
  virtual std::vector<IModelObjectPtr> GetBranchObjects() = 0;
  /// Получить массив координат конечных точек ответвления.
  virtual std::vector<double> GetBranchEndPoints() = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// Измерение расстояния и угла.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IMeasurement3D : IKompasAPIObject
{
  /// Получить первый объект.
  virtual IModelObjectPtr GetObject1() = 0;
  /// Установить первый объект.
  virtual void SetObject1(const IModelObjectPtr & object1) = 0;
  /// Получить второй объект.
  virtual IModelObjectPtr GetObject2() = 0;
  /// Установить второй объект.
  virtual void SetObject2(const IModelObjectPtr & object2) = 0;
  /// Получить признак вычисления за пределами первого объекта (для кривых и плоскостей).
  virtual bool IsExtendObject1() = 0;
  /// Получить признак вычисления за пределами второго объекта (для кривых и плоскостей).
  virtual bool IsExtendObject2() = 0;
  /// Получить признак краткого формата результата.
  virtual bool IsBriefly() = 0;
  /// Установить признак краткого формата результата.
  virtual void SetBriefly(bool briefly) = 0;
  /// Выполнить расчет.
  virtual ksMeasureResultEnum Calculate() = 0;
  /// Получить минимальное расстояние.
  virtual double GetLmin() = 0;
  /// Получить максимальное расстояние.
  virtual double GetLmax() = 0;
  /// Получить расстояние по нормали.
  virtual double GetLNormal() = 0;
  /// Получить признак применимости расчета угла (true - если для данных объектов угол имеет смысл).
  virtual bool IsAngleValid() = 0;
  /// Получить угол между объектами (в градусах).
  virtual double GetAngle() = 0;
  /// Получить первую точку отрезка минимального расстояния.
  virtual bool GetMinPoint1(double & x, double & y, double & z) = 0;
  /// Получить вторую точку отрезка минимального расстояния.
  virtual bool GetMinPoint2(double & x, double & y, double & z) = 0;
  /// Получить первую точку отрезка максимального расстояния.
  virtual bool GetMaxPoint1(double & x, double & y, double & z) = 0;
  /// Получить вторую точку отрезка максимального расстояния.
  virtual bool GetMaxPoint2(double & x, double & y, double & z) = 0;
  /// Получить первую точку отрезка расстояния по нормали.
  virtual bool GetNormalPoint1(double & x, double & y, double & z) = 0;
  /// Получить вторую точку отрезка расстояния по нормали.
  virtual bool GetNormalPoint2(double & x, double & y, double & z) = 0;
  /// Установить направляющий объект.
  virtual void SetDirectionObject(const IModelObjectPtr & directionObj) = 0;
  /// Получить направляющий объект.
  virtual IModelObjectPtr GetDirectionObject() = 0;
  /// Получить признак вычисления проекции зазора или проекции расстояния (true - зазор, false - расстояние).
  virtual bool GetGap() = 0;
  /// Установить признак вычисления проекции зазора или проекции расстояния (true - зазор, false - расстояние).
  virtual void SetGap(bool gap) = 0;
  /// Получить направляющий вектор.
  virtual IVector3DPtr GetDirectionVector() = 0;
};

