////////////////////////////////////////////////////////////////////////////////
//
/// Объект для отрисовки дополнительной геометрии.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IOpenGLObject : public IAPIObject
{
  /// Начать разграничение вершин примитива или группы подобных примитивов.
  virtual bool glBegin(int32_t mode) = 0;
  /// Завершить разграничение вершин примитива или группы подобных примитивов.
  virtual bool glEnd() = 0;
  /// Включить возможности GL на стороне сервера.
  virtual bool glEnable(int32_t cap) = 0;
  /// Отключить возможности GL на стороне сервера.
  virtual bool glDisable(int32_t cap) = 0;
  /// Установить текущий цвет.
  virtual bool glColor3d(double r, double g, double b) = 0;
  /// Установить толщину линии.
  virtual bool glLineWidth(double w) = 0;
  /// Установить пунктирность линии.
  virtual bool glLineStipple(int32_t factor, short pattern) = 0;
  /// Установить диаметр растровой точки.
  virtual bool glPointSize(double w) = 0;
  /// Установить режим растеризации полигонов.
  virtual bool glPolygonMode(int32_t face, int32_t mode) = 0;
  /// Добавить двумерную вершину.
  virtual bool glVertex2d(double x, double y) = 0;
  /// Добавить двумерные вершины.
  virtual bool glVertex2dv(double * verticesCoords, int32_t countDouble) = 0;
  /// Добавить трехмерную вершину.
  virtual bool glVertex3d(double x, double y, double z) = 0;
  /// Добавить трехмерные вершины.
  virtual bool glVertex3dv(double * verticesCoords, int32_t countDouble) = 0;
  /// Добавить четырехмерную вершину.
  virtual bool glVertex4d(double x, double y, double z, double w) = 0;
  /// Добавить четырехмерные вершины.
  virtual bool glVertex4dv(double * verticesCoords, int32_t countDouble) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Вспомогательные функции для диалогов.
/**
  Содержит методы отрисовки ресурсов/документов/текста/объектов в заданном окне.
*/
////////////////////////////////////////////////////////////////////////////////
struct IApplicationDialogsUtils : IAPIObject
{
  /**
    \brief Отрисовать слайд по идентификатору в RCDATA.
    \param[in] windowHandle - дескриптор окна для отрисовки слайда.
    \param[in] slideId - идентификатор слайда в файле ресурсов.
    \param[in] module - модуль ресурсов. Можно создать по имени файла ресурсов с помощью интерфейса IApplication.
               Возможна передача nullptr, тогда будет использован модуль текущей библиотеки.
    \return Успешность отрисовки.
  */
  virtual bool DrawSlide(WindowHandle windowHandle, int32_t slideId, ResourceModule module) = 0;
  /**
    \brief Отрисовать слайд из текстового файла с RCDATA.
    \param[in] windowHandle - дескриптор окна для отрисовки слайда.
    \param[in] fileName - имя файла текстового файла с RCDATA.
    \return Успешность отрисовки.
  */
  virtual bool DrawSlideFromFile(WindowHandle windowHandle, const std::wstring & fileName) = 0;
  /**
    \brief Отрисовать документ.
    \param[in] windowHandle - дескриптор окна для отрисовки документа.
    \param[in] document - документ для отрисовки.
    \return Успешность отрисовки.
  */
  virtual bool DrawKompasDocument(WindowHandle windowHandle, const IKompasDocumentPtr & document) = 0;
  /**
    \brief Отрисовать документ по имени файла.
    \param[in] windowHandle - дескриптор окна для отрисовки документа.
    \param[in] filePath - путь к файлу документа.
    \return Успешность отрисовки.
  */
  virtual bool DrawKompasDocumentByPath(WindowHandle windowHandle, const std::wstring & filePath) = 0;
  /**
    \brief Отрисовать группу объектов.
    \param[in] windowHandle - дескриптор окна для отрисовки группы.
    \param[in] group - группа объектов, которую требуется отрисовать.
    \return Успешность отрисовки.
  */
  virtual bool DrawKompasGroup(WindowHandle windowHandle, const IDrawingGroupPtr & group) = 0;
  /**
    \brief Отрисовать текст Компас.
    \param[in] windowHandle - дескриптор окна для отрисовки текста.
    \param[in] text - текст (объект).
    \return Успешность отрисовки.
  */
  virtual bool DrawKompasText(WindowHandle windowHandle, const IKompasAPIObjectPtr & text) = 0;
  /**
    \brief Отрисовать текст.
    \param[in] windowHandle - дескриптор окна для отрисовки текста.
    \param[in] text - Текст, который требуется отрисовать.
    \return Успешность отрисовки.
  */
  virtual bool DrawText(WindowHandle windowHandle, const std::wstring & text) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Узел дерева.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IPropertyTreeNode : IAPIObject
{
  /// Добавить узел в дерево.
  virtual bool AddNode(const IPropertyTreeNodePtr & node, const IPropertyTreeNodePtr & after) = 0;
  /// Удалить дочерний узел.
  virtual bool DeleteNode(const IPropertyTreeNodePtr & node) = 0;
  /// Удалить все дочерние узлы.
  virtual bool DeleteSubItems() = 0;
  /// Удалить узел.
  virtual bool Delete() = 0;
  /// Получить родительский узел.
  virtual IPropertyTreeNodePtr GetParentNode() = 0;
  /// Получить признак корневого узла.
  virtual bool IsRootNode() = 0;
  /// Получить дочерний узел по индексу.
  virtual IPropertyTreeNodePtr GetChild(int32_t index) = 0;
  /// Получить количество дочерних узлов.
  virtual int32_t GetChildsCount() = 0;
  /// Получить данные узла (ключ узла).
  virtual int64_t GetNodeData() = 0;
  /// Установить данные узла (ключ узла).
  virtual void SetNodeData(int64_t data) = 0;
  /// Получить признак раскрытости узла.
  virtual bool IsExpanded() = 0;
  /// Установить признак раскрытости узла.
  virtual void SetExpanded(bool expanded) = 0;
  /// Получить признак узла, содержащего дочерние узлы (дочерние узлы могут отсутствовать).
  virtual bool IsItemsHolder() = 0;
  /// Установить признак узла, содержащего дочерние узлы (дочерние узлы могут отсутствовать).
  virtual void SetItemsHolder(bool itemsHolder) = 0;
  /// Скрыть заголовок узла и раскрыть дочерние узлы.
  virtual void HideHeader() = 0;
  /// Установить иконку.
  virtual bool SetNodeIcon(int32_t icon, const std::wstring & iconFont) = 0;
  /// Получить признак выделенного узла.
  virtual bool IsSelected() = 0;
  /// Установить признак выделенного узла.
  virtual void SetSelected(bool selected) = 0;
  /// Получить признак выбранного узла.
  virtual bool IsChosen() = 0;
  /// Установить признак выбранного узла.
  virtual void SetChosen(bool chosen) = 0;
  /// Получить текст узла.
  virtual std::wstring GetText() = 0;
  /// Установить текст узла.
  virtual void SetText(const std::wstring & text) = 0;
  /// Начать редактирование заголовка узла.
  virtual bool EditText() = 0;
  /// Прокрутить к узлу.
  virtual bool BringIntoView() = 0;
  /// Установить разрешение перемещения узла.
  virtual void SetDragPermitted(bool dragPermitted) = 0;
  /// Установить разрешение для завершения перемещения.
  virtual void SetDropPermission(ksDropPermissionEnum dropPermission) = 0;
  /// Переместить узлы.
  virtual bool MoveNodes(const std::vector<IPropertyTreeNodePtr> & nodes, const IPropertyTreeNodePtr & after) = 0;
};


////////////////////////////////////////////////////////////////////////////////
//
/// События дерева.
/**
  
*/
////////////////////////////////////////////////////////////////////////////////
struct IPropertyTreeEvents : IAPIObject
{
  /// Удалить все обработчики
  virtual void RemoveAllHandlers(const std::wstring & handlerOwner) = 0;

  /// Описание обработчика события "Узел селектирован".
  using OnSelectNodesHandler = std::function<bool(const std::vector<IPropertyTreeNodePtr> & nodes)>;
  /// Добавить обработчик события "Узел селектирован".
  virtual void AddSelectNodesHandler(const std::wstring & handlerOwner, OnSelectNodesHandler eventHandler) = 0;

  /// Описание обработчика события "Снято селектирование узла".
  using OnUnselectNodesHandler = std::function<bool(const std::vector<IPropertyTreeNodePtr> & nodes)>;
  /// Добавить обработчик события "Снято селектирование узла".
  virtual void AddUnselectNodesHandler(const std::wstring & handlerOwner, OnUnselectNodesHandler eventHandler) = 0;

  /// Описание обработчика события "Узел свернут".
  using OnCollapseNodeHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Узел свернут".
  virtual void AddCollapseNodeHandler(const std::wstring & handlerOwner, OnCollapseNodeHandler eventHandler) = 0;

  /// Описание обработчика события "Узел развернут".
  using OnExpandNodeHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Узел развернут".
  virtual void AddExpandNodeHandler(const std::wstring & handlerOwner, OnExpandNodeHandler eventHandler) = 0;

  /// Описание обработчика события "Двойной клик по узлу дерева".
  using OnNodeDblClickHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Двойной клик по узлу дерева".
  virtual void AddNodeDblClickHandler(const std::wstring & handlerOwner, OnNodeDblClickHandler eventHandler) = 0;

  /// Описание обработчика события "Событие начала переименования узла дерева".
  using OnBeginTextEditHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Событие начала переименования узла дерева".
  virtual void AddBeginTextEditHandler(const std::wstring & handlerOwner, OnBeginTextEditHandler eventHandler) = 0;

  /// Описание обработчика события "Событие завершения переименования узла дерева".
  using OnEndTextEditHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Событие завершения переименования узла дерева".
  virtual void AddEndTextEditHandler(const std::wstring & handlerOwner, OnEndTextEditHandler eventHandler) = 0;

  /// Описание обработчика события "Событие начала перемещения узла дерева".
  using OnNodeDragStartedHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Событие начала перемещения узла дерева".
  virtual void AddNodeDragStartedHandler(const std::wstring & handlerOwner, OnNodeDragStartedHandler eventHandler) = 0;

  /// Описание обработчика события "Событие перемещения узла дерева".
  using OnNodeDragOverHandler = std::function<bool(const IPropertyTreeNodePtr & node, const IPropertyTreeNodePtr & dragNode,
                                                   bool ctrlPressed, bool requiredDropAfter)>;
  /// Добавить обработчик события "Событие перемещения узла дерева".
  virtual void AddNodeDragOverHandler(const std::wstring & handlerOwner, OnNodeDragOverHandler eventHandler) = 0;

  /// Описание обработчика события "Событие завершения перемещения узла дерева".
  using OnNodeDragDropedHandler =
    std::function<bool(const IPropertyTreeNodePtr & node, const IPropertyTreeNodePtr & dragNode, bool ctrlPressed)>;
  /// Добавить обработчик события "Событие завершения перемещения узла дерева".
  virtual void AddNodeDragDropedHandler(const std::wstring & handlerOwner, OnNodeDragDropedHandler eventHandler) = 0;

  /// Описание обработчика события "Запрос контекстного меню для узла дерева".
  using OnContextMenuRequestHandler = std::function<bool(const IPropertyTreeNodePtr & node)>;
  /// Добавить обработчик события "Запрос контекстного меню для узла дерева".
  virtual void AddContextMenuRequestHandler(const std::wstring & handlerOwner, OnContextMenuRequestHandler eventHandler) = 0;
};

////////////////////////////////////////////////////////////////////////////////
//
/// Элемент панели свойств - Дерево.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IPropertyTree : IPropertyControl
{
  /// Создать новый узел дерева.
  virtual IPropertyTreeNodePtr CreateNode(const std::wstring & name) = 0;
  /// Добавить узел в дерево.
  virtual bool AddNode(const IPropertyTreeNodePtr & node) = 0;
  /// Получить признак возможности изменять высоту дерева.
  virtual bool IsResizable() = 0;
  /// Установить признак возможности изменять высоту дерева.
  virtual void SetResizable(bool resizable) = 0;
  /// Получить минимальную высоту дерева.
  virtual int32_t GetMinHeight() = 0;
  /// Установить минимальную высоту дерева.
  virtual void SetMinHeight(int32_t minHeight) = 0;
  /// Получить список выделенных узлов.
  virtual std::vector<IPropertyTreeNodePtr> GetSelectedNodes() = 0;
  /// Получить корневой узел дерева.
  virtual IPropertyTreeNodePtr GetRootNode() = 0;
  /// Найти узел по имени.
  virtual IPropertyTreeNodePtr FindNodeByName(const std::wstring & name) = 0;
  /// Найти узел по данным библиотеки.
  virtual IPropertyTreeNodePtr FindNodeByNodeData(int64_t data) = 0;
  /// Получить признак автоматического расчета высоты контрола (true - растягивать на всю доступную область).
  virtual bool IsAutoSize() = 0;
  /// Установить признак автоматического расчета высоты контрола (true - растягивать на всю доступную область).
  virtual void SetAutoSize(bool autoSize) = 0;
  /// Получить признак возможности множественного выбора узлов в дереве.
  virtual bool IsMultiSelect() = 0;
  /// Установить признак возможности множественного выбора узлов в дереве.
  virtual void SetMultiSelect(bool multiSelect) = 0;
  /// Получить признак возможности перемещение узлов в дереве.
  virtual bool IsEnableDrag() = 0;
  /// Установить признак возможности перемещение узлов в дереве.
  virtual void SetEnableDrag(bool enableDrag) = 0;
  /// Получить события дерева.
  virtual IPropertyTreeEventsPtr Events() = 0;
};

