  /// Получить текущий столбец.
  virtual int32_t GetCurrentColumn() = 0;
  /// Установить текущую строку.
  virtual void SetCurrentRow(int32_t row) = 0;
  /// Получить текущую строку.
  virtual int32_t GetCurrentRow() = 0;
  /// Обновить параметры сетки.
  virtual void UpdateParam() = 0;
  /// Очистить таблицу.
  virtual bool Clear() = 0;
  /// Инициализировать параметры столбца.
  virtual bool InitColumn(int32_t column, const std::wstring & caption, const std::wstring & tips, bool readOnly) = 0;
  /// Инициализировать столбец с иконкой.
  virtual bool InitColumnIcon(int32_t column, int32_t icon, const std::wstring & iconFont) = 0;
  /// Добавить столбец.
  virtual bool AddColumn(const std::wstring & caption, const std::wstring & tips, bool readOnly) = 0;
  /// Удалить столбец.
  virtual bool DeleteColumn(int32_t column) = 0;
  /// Установить ширину столбца.
  virtual void SetColumnWidth(int32_t column, int32_t width) = 0;
  /// Получить ширину столбца.
  virtual int32_t GetColumnWidth(int32_t column) = 0;
  /// Установить значение в ячейке.
  virtual void SetCellValue(int32_t row, int32_t column, const PropertyValue & value) = 0;
  /// Получить значение в ячейке.
  virtual PropertyValue GetCellValue(int32_t row, int32_t column) = 0;
  /// Установить признак отображения значения в ячейке.
  virtual void SetCellValueVisible(int32_t row, int32_t column, bool visible) = 0;
  /// Получить признак отображения значения в ячейке.
  virtual bool GetCellValueVisible(int32_t row, int32_t column) = 0;
  /// Установить доступность редактирования ячейки.
  virtual void SetEnableEdit(int32_t row, int32_t column, bool enableEdit) = 0;
  /// Получить доступность редактирования ячейки.
  virtual bool IsEnableEdit(int32_t row, int32_t column) = 0;
  /// Удалить строку.
  virtual bool DeleteRow(int32_t row) = 0;
  /// Инициализировать строковую ячейку.
  virtual bool InitStringCell(int32_t row, int32_t column, const std::wstring & text) = 0;
  /// Инициализировать вещественную ячейку.
  virtual bool InitRealCell(int32_t row, int32_t column, double value, double spinValue, double minValue, double maxValue) = 0;
  /// Инициализировать целочисленную ячейку.
  virtual bool InitIntCell(int32_t row, int32_t column, int32_t value, int32_t spinValue, int32_t minValue, int32_t maxValue) = 0;
  /// Инициализировать ячейку с чекбоксом.
  virtual bool InitCheckBoxCell(int32_t row, int32_t column, bool value) = 0;
  /// Инициализировать ячейку обозначения.
  virtual bool InitMarkingCell(int32_t row, int32_t column, const std::wstring & marking, bool additionalNumberVisibility,
                               bool docCodeVisibility) = 0;
  /// Инициализировать строковую ячейку со списком значений.
  virtual bool InitStringComboCell(int32_t row, int32_t column, const std::wstring & value,
                                   const std::vector<std::wstring> & optionsList) = 0;
  /// Инициализировать целочисленную ячейку со списком значений.
  virtual bool InitIntComboCell(int32_t row, int32_t column, int32_t value, const std::vector<int32_t> & optionsList,
                                bool sorted) = 0;
  /// Инициализировать вещественную ячейку со списком значений.
  virtual bool InitRealComboCell(int32_t row, int32_t column, double value, const std::vector<double> & optionsList,
                                 bool sorted) = 0;
  /// Инициализировать ячейку с ссылкой.
  virtual bool InitLinkCell(int32_t row, int32_t column, const std::wstring & value) = 0;
  /// Инициализировать ячейку со списком значений c иконками.
  virtual bool InitIconsComboCell(int32_t row, int32_t column, int32_t currentValueIndex,
                                  const std::vector<std::wstring> & optionsList, const std::vector<int32_t> & optionsIcons,
                                  const std::vector<std::wstring> & optionsIconFonts) = 0;
  /// Инициализировать ячейку выбора цвета.
  virtual bool InitColorCell(int32_t row, int32_t column, int32_t value) = 0;
  /// Установить номер столбца, по которому будут сгруппированы данные.
