  /// Добавить обработчик события "Начало редактирования в ячейке".
  virtual void AddCellBeginEditHandler(OnCellBeginEditHandler eventHandler) = 0;

  /// Описание обработчика события "Изменился текущий объект".
  using OnChangeCurrentHandler = std::function<void(const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Изменился текущий объект".
  virtual void AddChangeCurrentHandler(OnChangeCurrentHandler eventHandler) = 0;

  /// Описание обработчика события "Начало добавления документа".
  using OnDocumentBeginAddHandler = std::function<bool(const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Начало добавления документа".
  virtual void AddDocumentBeginAddHandler(OnDocumentBeginAddHandler eventHandler) = 0;

  /// Описание обработчика события "Добавление документа в объекте СП".
  using OnDocumentAddHandler = std::function<void(const ISpecificationObjectPtr & obj, const std::wstring & nameDoc)>;
  /// Добавить обработчик события "Добавление документа в объекте СП".
  virtual void AddDocumentAddHandler(OnDocumentAddHandler eventHandler) = 0;

  /// Описание обработчика события "Удаление документа из объекта СП".
  using OnDocumentRemoveHandler = std::function<void(const ISpecificationObjectPtr & obj, const std::wstring & nameDoc)>;
  /// Добавить обработчик события "Удаление документа из объекта СП".
  virtual void AddDocumentRemoveHandler(OnDocumentRemoveHandler eventHandler) = 0;

  /// Описание обработчика события "Начало измения геометрии объекта СП".
  using OnBeginGeomChangeHandler = std::function<bool(const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Начало измения геометрии объекта СП".
  virtual void AddBeginGeomChangeHandler(OnBeginGeomChangeHandler eventHandler) = 0;

  /// Описание обработчика события "Геометрия объекта СП изменилась".
  using OnGeomChangeHandler = std::function<void(const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Геометрия объекта СП изменилась".
  virtual void AddGeomChangeHandler(OnGeomChangeHandler eventHandler) = 0;

  /// Описание обработчика события "Начало редактирования\создания объекта (false - запрещает процесс)".
  using OnBeginProcessHandler =
    std::function<bool(ksSpecificationObjectTypeEnum specificationObjectType, const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Начало редактирования\создания объекта (false - запрещает процесс)".
  virtual void AddBeginProcessHandler(OnBeginProcessHandler eventHandler) = 0;

  /// Описание обработчика события "Конец редактирования\создания объекта".
  using OnEndProcessHandler = std::function<void(ksSpecificationObjectTypeEnum specificationObjectType)>;
  /// Добавить обработчик события "Конец редактирования\создания объекта".
  virtual void AddEndProcessHandler(OnEndProcessHandler eventHandler) = 0;

  /// Описание обработчика события "Создание объекта".
  using OnCreateHandler = std::function<void(const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Создание объекта".
  virtual void AddCreateHandler(OnCreateHandler eventHandler) = 0;

  /// Описание обработчика события "Редактирование объекта".
  using OnUpdateHandler = std::function<void(const ISpecificationObjectPtr & obj)>;
  /// Добавить обработчик события "Редактирование объекта".
  virtual void AddUpdateHandler(OnUpdateHandler eventHandler) = 0;

  /// Описание обработчика события "Начало копирования объекта".
