////////////////////////////////////////////////////////////////////////////////
//
/// Меню.
/**

*/
////////////////////////////////////////////////////////////////////////////////
struct IMenu : IAPIObject
{
  /// Загрузить меню из ресурсов или из манифеста.
  virtual bool Load(int32_t menuId, ResourceModule module) = 0;
  /// Установить текст пункту меню.
  virtual bool SetText(int32_t commandId, const std::wstring & text) = 0;
  /// Установить текст пункту меню по позиции.
  virtual bool SetTextByPositionPath(const std::vector<int32_t> & positionPath, const std::wstring & text) = 0;
  /// Установить состояние пункту меню.
  virtual bool SetState(int32_t commandId, bool enabled, bool checked) = 0;
  /// Установить состояние пункту меню по позиции.
  virtual bool SetStateByPositionPath(const std::vector<int32_t> & positionPath, bool enabled, bool checked) = 0;

  /// Получить позицию пункта меню.
  virtual std::vector<int32_t> GetPositionPath(int32_t commandId) = 0;
  /// Получить идентификатор пункта меню по позиции.
  virtual int32_t GetCommandId(const std::vector<int32_t> & positionPath) = 0;
  /// Получить количество элементов меню.
  virtual int32_t GetItemCount(const std::vector<int32_t> & positionPath) = 0;

  /// Получить тип элемента меню.
  virtual ksMenuItemTypeEnum GetItemType(const std::vector<int32_t> & positionPath) = 0;

  /// Получить текст пункта меню.
  virtual std::wstring GetText(int32_t commandId) = 0;
  /// Получить текст пункта меню по позиции.
  virtual std::wstring GetTextByPositionPath(const std::vector<int32_t> & positionPath) = 0;
  /// Получить состояние пункта меню.
  virtual bool GetState(int32_t commandId, bool & enable, bool & checked) = 0;
  /// Получить состояние пункта меню по позиции.
  virtual bool GetStateByPositionPath(const std::vector<int32_t> & positionPath, bool & enabled, bool & checked) = 0;

  /// Удалить пункт меню.
  virtual bool Delete(int32_t commandId) = 0;
  /// Удалить пункт меню по позиции.
  virtual bool DeleteByPositionPath(const std::vector<int32_t> & positionPath) = 0;
  /// Очистить меню.
  virtual void Clear() = 0;

  /// Вставить пункт меню на указанную позицию.
  virtual void Insert(const std::vector<int32_t> & positionPath, int32_t commandId, const std::wstring & text, int32_t icon,
                      const std::wstring & iconFont) = 0;
  /// Добавить пункт меню.
  virtual void Append(int32_t commandId, const std::wstring & text, int32_t icon, const std::wstring & iconFont) = 0;

  /// Вставить подменю на указанную позицию.
  virtual void InsertSubMenu(const std::vector<int32_t> & positionPath, const std::wstring & text, const IMenuPtr & subMenu) = 0;
  /// Добавить подменю.
  virtual void AppendSubMenu(const std::wstring & text, const IMenuPtr & subMenu) = 0;

  /// Вставить разделитель.
  virtual void InsertSeparator(const std::vector<int32_t> & positionPath) = 0;
  /// Добавить разделитель.
  virtual void AppendSeparator() = 0;
};

